def _suppress_noisy_warning(message, category, filename, lineno, file=None, line=None):
    text = str(message)
    if issubclass(category, ResourceWarning):
        return
    if issubclass(category, RuntimeWarning) and "renamed to `ddgs`" in text:
        return
    return _original_showwarning(message, category, filename, lineno, file=file, line=line)


warnings.showwarning = _suppress_noisy_warning


