def _append_runtime_log(rendered):
    """Persist the server print stream for the UI's history panel.

    The Electron console still receives the same live stream, while this
    bounded file gives the renderer a reliable history endpoint after startup
    reconnects.  Logs are capped so a stuck provider cannot fill the user's
    disk.
    """
    text = str(rendered or '').strip()
    if not text:
        return
    try:
        _RUNTIME_LOG_PATH.parent.mkdir(parents=True, exist_ok=True)
        stamp = time.strftime('%Y-%m-%d %H:%M:%S')
        with _RUNTIME_LOG_LOCK:
            with _RUNTIME_LOG_PATH.open('a', encoding='utf-8') as handle:
                handle.write(f'[{stamp}] {text}\n')
            if _RUNTIME_LOG_PATH.stat().st_size > 4 * 1024 * 1024:
                lines = _RUNTIME_LOG_PATH.read_text(encoding='utf-8', errors='ignore').splitlines()
                _RUNTIME_LOG_PATH.write_text('\n'.join(lines[-8000:]) + '\n', encoding='utf-8')
    except Exception:
        # Logging must never interfere with media generation or startup.
        pass


def print(*args, **kwargs):
    rendered = " ".join(str(arg) for arg in args)
    if any(snippet in rendered for snippet in _SUPPRESSED_LOG_SNIPPETS):
        return
    if "ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â°ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â Rescuing" in rendered and "unresolved scenes" in rendered:
        args = (
            rendered
            .replace("ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â°ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â Rescuing", "rescue pass:")
            .replace(" | ", ", ")
            .replace("...", ""),
        )
    kwargs.setdefault('flush', True)
    try:
        _original_print(*args, **kwargs)
    except (OSError, UnicodeEncodeError):
        fallback_args = [
            str(arg).encode('ascii', 'replace').decode('ascii')
            for arg in args
        ]
        _original_print(*fallback_args, **kwargs)
    _append_runtime_log(rendered)
builtins.print = print

