_cms_runtime_secret = (os.environ.get('VIDZEO_DESKTOP_SECRET') or '').strip()

def _cms_runtime_authorized():
    global _cms_runtime_secret
    expected = _cms_runtime_secret or (os.environ.get('VIDZEO_DESKTOP_SECRET') or '').strip()
    received = (request.headers.get('X-Vidzeo-Runtime-Key') or '').strip()
    if not expected and received and len(received) == 64 and all(c in '0123456789abcdef' for c in received.lower()):
        if request.remote_addr in {'127.0.0.1', '::1', '::ffff:127.0.0.1'} and not request.headers.get('Origin'):
            _cms_runtime_secret = received
            expected = received
    return bool(
        expected and received
        and request.remote_addr in {'127.0.0.1', '::1', '::ffff:127.0.0.1'}
        and not request.headers.get('Origin')
        and not request.headers.get('X-Forwarded-For')
        and not request.headers.get('Forwarded')
        and secrets.compare_digest(expected, received)
    )


@app.before_request
def _protect_cms_managed_engine():
    if request.path in {'/api/youtube/session/import-extension', '/api/youtube/session/import-managed-browser', '/api/youtube/session/inherit-vidnets', '/api/youtube/session/status'}:
        return None
    if os.environ.get('VIDZEO_DESKTOP_SECRET') and request.path.startswith('/api/') and not _cms_runtime_authorized():
        return jsonify({'error': 'Authenticated CMS runtime access required'}), 403


@app.route('/api/cms-runtime', methods=['GET'])
def api_cms_runtime():
    if not _cms_runtime_authorized():
        return jsonify({'error': 'Authenticated CMS runtime access required'}), 403
    return jsonify({'ok': True})


@app.after_request
def _apply_security_headers(response):
    response.headers.setdefault('X-Content-Type-Options', 'nosniff')
    response.headers.setdefault('X-Frame-Options', 'DENY')
    response.headers.setdefault('Referrer-Policy', 'no-referrer')
    response.headers.setdefault('Permissions-Policy', 'camera=(), microphone=(), geolocation=()')
    if request.path.startswith('/api/'):
        response.headers.setdefault('Cache-Control', 'no-store')
    return response

