def _json_error(message, status_code=400):
    return jsonify({"error": message}), status_code


def _extract_bearer_token():
    header = request.headers.get('Authorization', '')
    if not header.lower().startswith('bearer '):
        if _is_local_request():
            return ''
        raise AuthServiceError("Authentication required.", status_code=401)
    return header.split(' ', 1)[1].strip()


def _extract_device_context():
    device_info = {}
    raw_device_info = (request.headers.get('X-Vidzeo-Device-Info') or '').strip()
    if raw_device_info:
        try:
            decoded = urllib.parse.unquote(raw_device_info)
            parsed = json.loads(decoded)
            if isinstance(parsed, dict):
                device_info = parsed
        except Exception:
            device_info = {}
    return {
        "device_fingerprint": (request.headers.get('X-Vidzeo-Device-Fingerprint') or '').strip(),
        "device_info": device_info,
        "last_login_ip": (request.headers.get('X-Forwarded-For') or request.remote_addr or '').split(',')[0].strip(),
        "user_agent": (request.headers.get('User-Agent') or '').strip(),
    }


def _get_authenticated_state():
    token = _extract_bearer_token()
    delegated = None
    if token.startswith('vna_'):
        if not _is_local_request() or not _is_trusted_browser_origin():
            raise AuthServiceError('Local agent access requires localhost.', status_code=403)
        from services.agent_access import authorized_credentials
        try:
            delegated = authorized_credentials(token, request.method, request.path)
        except PermissionError as exc:
            raise AuthServiceError(str(exc), status_code=403) from None
        request.vidzeo_agent = True
        request.vidzeo_agent_owner = delegated['owner_id']
        agent_key = token
        token = delegated['access_token']
    mode = str(os.environ.get('VIDZEO_AUTH_MODE', '')).strip().lower() or 'local'
    packaged = str(os.environ.get('VIDZEO_PACKAGED', '0')).strip() == '1'
    allowed = mode in {'local', 'offline', 'byok'} and (
        not packaged or os.environ.get('VIDZEO_ALLOW_PACKAGED_LOCAL_AUTH') == '1' or mode == 'local'
    )
    if token in {'', 'local-bypass', 'local-dev-token'} and allowed and _is_local_request() and _is_trusted_browser_origin():
        if delegated and delegated['owner_id'] != 'local-user':
            raise AuthServiceError('Agent account identity did not match.', status_code=403)
        if token == 'local-bypass' and not delegated:
            # Sign-in-free worker build: CLI subcommands authenticate with the
            # fixed 'local-bypass' token and no paired account. Treat that as a
            # local agent owner so external_agent LLM jobs remain admissible.
            request.vidzeo_agent = True
            request.vidzeo_agent_owner = 'local-user'
        return "local-dev-token", {
            "access_state": "active",
            "email": "local@vidzeo.app",
            "plan": "pro",
            "role": "authenticated",
            "user_id": "local-user",
            "tier": "pro",
        }
    if not token or token in {'local-bypass', 'local-dev-token'}:
        raise AuthServiceError('Authentication required.', status_code=401)
    device = delegated['device_context'] if delegated else _extract_device_context()
    try:
        state = sync_authenticated_user(token, **device)
    except AuthServiceError as exc:
        if not delegated or getattr(exc, 'status_code', 0) != 401:
            raise
        from services.agent_access import refresh_credentials
        try:
            delegated = refresh_credentials(agent_key)
        except Exception:
            raise AuthServiceError('Agent session expired. Sign in and pair again in Settings.', status_code=401) from None
        token = delegated['access_token']
        state = sync_authenticated_user(token, **delegated['device_context'])
    if delegated and str(state.get('user_id') or state.get('id') or '') != delegated['owner_id']:
        raise AuthServiceError('Agent account identity did not match.', status_code=403)
    return token, state


def _is_local_request():
    remote_addr = (request.remote_addr or '').strip()
    return remote_addr in {'127.0.0.1', '::1', '::ffff:127.0.0.1', ''}


def _is_trusted_browser_origin():
    origin = (request.headers.get('Origin') or request.headers.get('Referer') or '').strip()
    if not origin:
        return True
    try:
        parsed = urllib.parse.urlparse(origin)
        return (
            parsed.scheme in {'http', 'https'}
            and parsed.hostname in {'localhost', '127.0.0.1', '::1'}
            and (parsed.port in {None, 5000, int(os.environ.get('VIDZEO_PORT', '5000'))})
        )
    except Exception:
        return False


def _cleanup_browser_auth_flows():
    now = time.time()
    expired_ids = [
        flow_id
        for flow_id, flow in browser_auth_flows.items()
        if (now - float(flow.get('created_at') or 0)) > BROWSER_AUTH_FLOW_TTL_SECONDS
    ]
    for flow_id in expired_ids:
        browser_auth_flows.pop(flow_id, None)


def _create_browser_auth_flow(device_context=None):
    _cleanup_browser_auth_flows()
    flow_id = secrets.token_urlsafe(18)
    flow_secret = secrets.token_urlsafe(24)
    # Keep the PKCE verifier on the backend instead of browser localStorage.
    # The callback can therefore be completed in the user's default browser
    # while the desktop app safely polls the same short-lived flow.
    code_verifier = secrets.token_urlsafe(64)
    code_challenge = base64.urlsafe_b64encode(
        hashlib.sha256(code_verifier.encode('ascii')).digest()
    ).rstrip(b'=').decode('ascii')
    browser_auth_flows[flow_id] = {
        "secret": flow_secret,
        "created_at": time.time(),
        "status": "pending",
        "payload": None,
        "error": "",
        "code_verifier": code_verifier,
        "code_challenge": code_challenge,
        "device_context": device_context or {},
    }
    return {
        "flow_id": flow_id,
        "flow_secret": flow_secret,
    }


def _get_browser_auth_flow(flow_id, flow_secret=None):
    _cleanup_browser_auth_flows()
    flow = browser_auth_flows.get(flow_id)
    if not flow:
        return None
    if flow_secret is not None and flow.get('secret') != flow_secret:
        return None
    return flow


def _device_context_for_browser_completion(flow):
    current_context = _extract_device_context()
    if current_context.get("device_fingerprint"):
        return current_context

    stored_context = flow.get("device_context") if isinstance(flow, dict) else {}
    if not isinstance(stored_context, dict):
        stored_context = {}

    return {
        **current_context,
        **stored_context,
        "last_login_ip": current_context.get("last_login_ip") or stored_context.get("last_login_ip"),
        "user_agent": current_context.get("user_agent") or stored_context.get("user_agent"),
    }


def require_authenticated_user(view_func):
    @wraps(view_func)
    def wrapped(*args, **kwargs):
        try:
            token, state = _get_authenticated_state()
        except AuthServiceError as exc:
            return _json_error(str(exc), getattr(exc, "status_code", 401) or 401)
        request.vidzeo_access_token = token
        request.vidzeo_user = state
        if not getattr(request, 'vidzeo_agent', False) and request.is_json:
            payload = request.get_json(silent=True)
            if isinstance(payload, dict):
                nested = payload.get('config') if isinstance(payload.get('config'), dict) else {}
                if payload.get('llm_provider', nested.get('llm_provider')) == 'external_agent':
                    return _json_error('Use a paired local agent key for external_agent mode.', 400)
        return view_func(*args, **kwargs)
    return wrapped


def require_active_access(view_func):
    @wraps(view_func)
    @require_authenticated_user
    def wrapped(*args, **kwargs):
        if (request.vidzeo_user or {}).get('access_state') != 'active':
            return _json_error("An active plan is required to use the studio.", 403)
        return view_func(*args, **kwargs)
    return wrapped


def require_admin_user(view_func):
    @wraps(view_func)
    def wrapped(*args, **kwargs):
        try:
            token = _extract_bearer_token()
            admin_state = verify_admin(token)
        except AuthServiceError as exc:
            return _json_error(str(exc), getattr(exc, "status_code", 403) or 403)
        request.vidzeo_access_token = token
        request.vidzeo_admin = admin_state
        return view_func(*args, **kwargs)
    return wrapped


def _browser_auth_callback_url(flow_id, flow_secret):
    base_url = request.host_url.rstrip('/')
    # Keep this URL byte-for-byte equal to the Supabase redirect allow-list.
    # The one-time flow is stored in an HttpOnly localhost cookie rather than
    # query parameters, which some redirect validators treat as a mismatch.
    return f"{base_url}/auth/browser-callback"


def _browser_auth_cookie_value(flow_id, flow_secret):
    return f"{flow_id}.{flow_secret}"


def _browser_auth_cookie_flow():
    raw = (request.cookies.get('vidzeo_browser_auth') or '').strip()
    if not raw or '.' not in raw:
        return '', ''
    return raw.split('.', 1)


def _browser_auth_provider_url(flow_id, flow_secret, flow):
    """Build the provider URL for the desktop's one-time PKCE flow."""
    auth = public_auth_config()
    supabase_url = str(auth.get("supabase_url") or "").rstrip('/')
    if not supabase_url:
        return ''
    callback_url = _browser_auth_callback_url(flow_id, flow_secret)
    query = urllib.parse.urlencode({
        "provider": "google",
        "redirect_to": callback_url,
        "code_challenge": flow.get("code_challenge") or '',
        "code_challenge_method": "S256",
        # A desktop sign-in must let the person deliberately select the
        # Google account to use instead of silently reusing a website login.
        "prompt": "select_account",
    })
    return f"{supabase_url}/auth/v1/authorize?{query}"


