def _render_browser_auth_callback_page(flow_id, flow_secret):
    flow_id_json = json.dumps(flow_id)
    flow_secret_json = json.dumps(flow_secret)
    return f"""<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Completing Vidzeo Sign In</title>
    <style>
        :root {{ color-scheme: dark; }}
        body {{
            margin: 0;
            min-height: 100vh;
            display: grid;
            place-items: center;
            padding: 24px;
            background: radial-gradient(circle at top, rgba(86, 210, 255, 0.18), transparent 35%), #071018;
            color: #f8fbff;
            font-family: Inter, ui-sans-serif, system-ui, sans-serif;
        }}
        main {{
            width: min(520px, 100%);
            padding: clamp(24px, 4vw, 40px);
            border-radius: 28px;
            border: 1px solid rgba(86, 210, 255, 0.18);
            background: rgba(9, 15, 24, 0.92);
            text-align: center;
        }}
        h1 {{ margin: 0; font-size: clamp(2rem, 4vw, 2.8rem); }}
        p {{ color: rgba(216, 228, 245, 0.72); line-height: 1.7; }}
        .status {{ margin-top: 22px; font-weight: 700; }}
        .status.error {{ color: #ff9ca8; }}
        .status.success {{ color: #8ff1e6; }}
    </style>
</head>
<body>
    <main>
        <h1>Finishing sign-in</h1>
        <p>Vidnets Studio is securely connecting your Google account to the desktop app.</p>
        <div class="status" id="statusCopy">Completing authentication...</div>
    </main>

    <script>
        window.__VIDZEO_AUTH_FLOW__ = {{
            flowId: {flow_id_json},
            flowSecret: {flow_secret_json}
        }};
    </script>
    <script>
        const flow = window.__VIDZEO_AUTH_FLOW__;
        const statusEl = document.getElementById('statusCopy');

        function setStatus(message, type = 'info') {{
            statusEl.textContent = message;
            statusEl.className = `status ${{type}}`;
        }}

        async function completeBrowserSignin(payload) {{
            const response = await fetch('/api/auth/browser/complete', {{
                method: 'POST',
                headers: {{ 'Content-Type': 'application/json' }},
                body: JSON.stringify({{
                    flow_id: flow.flowId,
                    flow_secret: flow.flowSecret,
                    ...payload
                }})
            }});
            if (!response.ok) {{
                const errorPayload = await response.json().catch(() => ({{ error: 'Browser sign-in could not be completed.' }}));
                throw new Error(errorPayload.error || 'Browser sign-in could not be completed.');
            }}
        }}

        async function init() {{
            try {{
                const url = new URL(window.location.href);
                const code = url.searchParams.get('code');
                const errorDescription = url.searchParams.get('error_description') || url.searchParams.get('error');
                if (errorDescription) {{
                    await completeBrowserSignin({{ error: errorDescription }}).catch(() => {{}});
                    throw new Error(errorDescription);
                }}

                const hashParams = new URLSearchParams(window.location.hash.replace(/^#/, ''));
                const accessToken = hashParams.get('access_token');
                const refreshToken = hashParams.get('refresh_token');
                if (accessToken && refreshToken) {{
                    await completeBrowserSignin({{
                        accessToken,
                        refreshToken,
                        expiresAt: Number(hashParams.get('expires_at') || 0),
                        user: {{}}
                    }});
                }} else if (code) {{
                    await completeBrowserSignin({{ code }});
                }} else {{
                    throw new Error('Google sign-in finished but Supabase did not return a desktop session.');
                }}

                setStatus('Sign-in complete. You can return to Vidnets Studio.', 'success');
                window.setTimeout(() => window.close(), 1800);
            }} catch (error) {{
                setStatus(error.message || 'Google sign-in could not be completed.', 'error');
            }}
        }}

        init();
    </script>
</body>
</html>"""


