# Custom output directories registered by /api/generate and /api/queue/add.
# Videos rendered into a user-chosen folder stay playable at /output/<name>
# and show up in the project gallery.
_EXTRA_OUTPUT_DIRS = set()
_EXTRA_OUTPUT_DIRS_LOCK = threading.Lock()


def register_output_dir(output_dir):
    """Register a custom output directory so /output/ URLs and the gallery can serve its files."""
    if not output_dir:
        return
    try:
        resolved = Path(str(output_dir)).resolve()
    except Exception:
        return
    if not resolved.exists() or not resolved.is_dir():
        return
    with _EXTRA_OUTPUT_DIRS_LOCK:
        _EXTRA_OUTPUT_DIRS.add(str(resolved))
    _persist_registered_output_dirs()


def _custom_dirs_state_file():
    try:
        return TEMP_DIR / '.vidzeo_custom_output_dirs.json'
    except Exception:
        return None



def _persist_registered_output_dirs():
    with _EXTRA_OUTPUT_DIRS_LOCK:
        dirs = list(_EXTRA_OUTPUT_DIRS)
    state_file = _custom_dirs_state_file()
    if state_file is None:
        return
    try:
        state_file.parent.mkdir(parents=True, exist_ok=True)
        state_file.write_text(json.dumps({'dirs': dirs}, indent=2), encoding='utf-8')
    except Exception:
        pass


def _load_registered_output_dirs():
    state_file = _custom_dirs_state_file()
    if state_file is None or not state_file.exists():
        return
    try:
        data = json.loads(state_file.read_text(encoding='utf-8'))
        for entry in (data.get('dirs') or []):
            register_output_dir(entry)
    except Exception:
        pass


_load_registered_output_dirs()


def _safe_media_resolutions(filename, roots):
    """Return (root, resolved_candidate) pairs for a filename, blocking traversal escapes."""
    results = []
    for root in roots:
        try:
            root_resolved = root.resolve()
            candidate = (root_resolved / filename).resolve()
        except Exception:
            continue
        if candidate == root_resolved or root_resolved in getattr(candidate, 'parents', ()):
            results.append((root_resolved, candidate))
    return results


def _resolve_output_file(filename):
    """Find a file under OUTPUT_DIR or a registered custom output dir. Returns Path or None."""
    with _EXTRA_OUTPUT_DIRS_LOCK:
        extra_roots = [Path(item) for item in list(_EXTRA_OUTPUT_DIRS)]
    for _root, candidate in _safe_media_resolutions(filename, [OUTPUT_DIR] + extra_roots):
        if candidate.is_file():
            return candidate
    return None


def _resolve_temp_file(filename):
    for _root, candidate in _safe_media_resolutions(filename, [TEMP_DIR]):
        if candidate.is_file():
            return candidate
    return None


def _send_media_file(target, cache_control='private, max-age=60'):
    """Send a media file with Range/ETag support for every video container."""
    mimetype = _VIDEO_MIME_TYPES.get(target.suffix.lower())
    if mimetype:
        response = send_file(target, mimetype=mimetype, conditional=True, etag=True)
        response.headers['Accept-Ranges'] = 'bytes'
        response.headers['Cache-Control'] = cache_control
        return response
    return send_from_directory(str(target.parent), target.name)


@app.route('/output/<path:filename>')
def serve_output(filename):
    if not _is_local_request():
        abort(403)
    target = _resolve_output_file(filename)
    if target is None:
        return abort(404)
    return _send_media_file(target)

@app.route('/temp/<path:filename>')
def serve_temp(filename):
    if not _is_local_request():
        abort(403)
    target = _resolve_temp_file(filename)
    if target is None:
        return abort(404)
    return _send_media_file(target, cache_control='private, no-cache')


