@app.route('/api/runtime/logs')
def api_runtime_logs():
    """Return the most recent bounded server log lines for the desktop UI."""
    try:
        limit = int(request.args.get('limit', 80) or 80)
    except (TypeError, ValueError):
        limit = 80
    limit = max(1, min(200, limit))
    log_path = Path(globals().get('SERVER_ACTIVITY_LOG') or _RUNTIME_LOG_PATH)
    try:
        lines = log_path.read_text(encoding='utf-8', errors='replace').splitlines()[-limit:]
    except OSError:
        lines = []
    # Runtime logs are user-visible and can contain provider headers or
    # accidental key echoes from third-party libraries. Redact common secret
    # forms at the API boundary even if an older process wrote them verbatim.
    redacted = []
    for line in lines:
        value = re.sub(r'(?i)(authorization\s*:\s*bearer\s+)\S+', r'\1[redacted]', str(line))
        value = re.sub(r'(?i)(api[_-]?key\s*[=:]\s*)\S+', r'\1[redacted]', value)
        redacted.append(value)
    return jsonify({'lines': redacted, 'count': len(redacted)})


