_YOUTUBE_CONNECTOR_ORIGINS = {
    "chrome-extension://gkpolooknidedbhcljjpembcjnollpni",
    "http://127.0.0.1:3210",
    "http://localhost:3210",
}


@app.route('/api/youtube/session/import-extension', methods=['OPTIONS', 'POST'])
def api_youtube_session_import_extension():
    origin = (request.headers.get('Origin') or '').strip()
    is_approved = (
        not origin
        or origin in _YOUTUBE_CONNECTOR_ORIGINS
        or origin.startswith('http://127.0.0.1:')
        or origin.startswith('http://localhost:')
    )
    if not is_approved:
        return _json_error("Chrome connector origin is not approved.", 403)

    response_headers = {
        "Access-Control-Allow-Origin": origin or "*",
        "Access-Control-Allow-Methods": "POST, OPTIONS",
        "Access-Control-Allow-Headers": "Content-Type, X-Vidzeo-Chrome-Connector",
        "Vary": "Origin",
    }
    if request.method == 'OPTIONS':
        response = app.response_class(status=204)
        for key, value in response_headers.items():
            response.headers[key] = value
        return response

    if (request.headers.get('X-Vidzeo-Chrome-Connector') or '').strip() != '1':
        return _json_error("Chrome connector header is required.", 403)
    payload = request.get_json(silent=True) or {}
    records = payload.get('cookies') if isinstance(payload, dict) else None
    if not isinstance(records, list):
        return _json_error("Cookie records are required.", 400)
    browser = str(payload.get('browser') or 'chrome').strip().lower()
    if browser not in {'chrome', 'edge'}:
        browser = 'chrome'

    try:
        from services import youtube_session
        username = str(payload.get('username') or '').strip()
        kwargs = {"username": username} if username else {}
        youtube_session.import_cookie_records(
            records,
            browser=browser,
            source=f"Trusted {browser.title()} browser connector",
            profile="Vidzeo YouTube profile",
            **kwargs,
        )
        status = youtube_session.session_status()
        if not status.get('ready') or not status.get('verified_authenticated'):
            response = _json_error("YouTube session was not verified.", 503)
        else:
            response = jsonify({
                "success": True,
                "connector": "chrome-extension",
                "session": status,
            })
    except Exception as exc:
        response = _json_error(str(exc), 400)
    response = make_response(response)
    for key, value in response_headers.items():
        response.headers[key] = value
    return response


