@app.route('/api/youtube/session/import-managed-browser', methods=['POST'])
def api_youtube_session_import_managed_browser():
    """Accept cookies only from the packaged desktop browser connector.

    The desktop process launches a dedicated Chrome/Edge profile and reads its
    filtered cookies through the browser-control channel. Keeping this endpoint
    local and protected by a per-process token prevents ordinary web content
    from injecting account cookies into the broker.
    """
    if not _is_local_request():
        return _json_error("Managed YouTube connector is local-only.", 403)

    expected_token = (os.environ.get('VIDZEO_DESKTOP_CONNECTOR_TOKEN') or '').strip()
    supplied_token = (request.headers.get('X-Vidzeo-Desktop-Connector') or '').strip()
    if not expected_token or not supplied_token or not secrets.compare_digest(expected_token, supplied_token):
        return _json_error("Managed YouTube connector token is invalid.", 403)

    payload = request.get_json(silent=True) or {}
    browser = str(payload.get('browser') or 'chrome').strip().lower()
    if browser not in {'chrome', 'edge'}:
        return _json_error("Managed connector supports Chrome or Edge.", 400)
    records = payload.get('cookies')
    if not isinstance(records, list):
        return _json_error("Cookie records are required.", 400)

    try:
        from services import youtube_session
        youtube_session.import_cookie_records(
            records,
            browser=browser,
            source=f"Vidzeo managed {browser.title()} connection",
            profile="Vidzeo YouTube profile",
        )
        status = youtube_session.session_status()
        if not status.get('ready') or not status.get('verified_authenticated'):
            return _json_error("YouTube did not verify the connected account.", 503)
        return jsonify({
            "success": True,
            "connector": "managed-browser",
            "session": status,
        })
    except Exception as exc:
        return _json_error(str(exc), 400)


@app.route('/api/youtube/session/import-cookies', methods=['POST'])
def api_youtube_session_import_cookies():
    payload = request.get_json(silent=True) or {}
    cookie_data = payload.get('cookie_data')
    if not cookie_data:
        return _json_error("Cookie data is required (Netscape text or JSON).", 400)
    try:
        from services import youtube_session
        if isinstance(cookie_data, list):
            youtube_session.import_cookie_records(cookie_data, browser="chrome", source="Manual Import")
        elif isinstance(cookie_data, str):
            raw = cookie_data.lstrip('\ufeff').strip()
            if raw.startswith("["):
                parsed = json.loads(raw)
                youtube_session.import_cookie_records(parsed, browser="chrome", source="Manual JSON Import")
            elif raw.startswith("{"):
                parsed = json.loads(raw)
                records = parsed.get("cookies") if isinstance(parsed, dict) else None
                if not isinstance(records, list):
                    raise ValueError("JSON cookie data must be an array or an object with a cookies array")
                youtube_session.import_cookie_records(records, browser="chrome", source="Manual JSON Import")
            else:
                youtube_session.import_cookie_bytes(raw.encode("utf-8"), browser="chrome")
        status = youtube_session.session_status()
        return jsonify({"success": True, "session": status})
    except Exception as exc:
        return _json_error(f"Failed to import cookies: {exc}", 400)


@app.route('/api/youtube/session/disconnect', methods=['POST'])
def api_youtube_session_disconnect():
    try:
        from services import youtube_session
        youtube_session.invalidate_session("User manual disconnect")
        try:
            target = youtube_session._secure_store_path()
            target.unlink(missing_ok=True)
            youtube_session._clear_cookie_update_state()
        except Exception:
            pass
        status = youtube_session.session_status()
        return jsonify({"success": True, "session": status})
    except Exception as exc:
        return _json_error(str(exc), 500)


