@app.route('/api/auth/browser/complete', methods=['POST'])
def api_auth_browser_complete():
    data = request.json or {}
    flow_id = (data.get('flow_id') or '').strip()
    flow_secret = (data.get('flow_secret') or '').strip()
    flow = _get_browser_auth_flow(flow_id, flow_secret=flow_secret)
    if not flow:
        return _json_error("Browser auth flow not found.", 404)

    # The callback is intentionally idempotent.  A browser can retry a POST
    # after a network hiccup while the desktop poller is already seeing the
    # completed state; never redeem the one-time code twice.
    if flow.get('status') == 'completed' and flow.get('payload'):
        return jsonify({"success": True})

    callback_error = str(data.get('error_description') or data.get('error') or '').strip()
    if callback_error:
        # OAuth providers report cancellations and consent failures on the
        # callback URL. Persist that result so the desktop poller can stop
        # waiting instead of leaving the landing screen in an endless state.
        flow['status'] = 'error'
        flow['error'] = callback_error[:240]
        return _json_error(flow['error'], 400)

    access_token = (data.get('accessToken') or '').strip()
    refresh_token = (data.get('refreshToken') or '').strip()
    oauth_code = (data.get('code') or '').strip()
    if oauth_code and (not access_token or not refresh_token):
        try:
            session = exchange_pkce_code(oauth_code, flow.get('code_verifier') or '')
        except AuthServiceError as exc:
            flow['status'] = 'error'
            flow['error'] = str(exc)
            return _json_error(flow['error'], getattr(exc, "status_code", 401) or 401)
        access_token = (session.get('access_token') or '').strip()
        refresh_token = (session.get('refresh_token') or '').strip()
        expires_at = session.get('expires_at')
        if not expires_at and session.get('expires_in'):
            try:
                expires_at = int(time.time()) + int(session.get('expires_in'))
            except (TypeError, ValueError):
                expires_at = 0
        data = {
            **data,
            "expiresAt": expires_at or 0,
            "user": session.get('user') or data.get('user') or {},
        }
    if not access_token or not refresh_token:
        flow['status'] = 'error'
        flow['error'] = 'Supabase session tokens were missing from the browser sign-in flow.'
        return _json_error(flow['error'], 400)

    try:
        auth_state = sync_authenticated_user(access_token, **_device_context_for_browser_completion(flow))
    except AuthServiceError as exc:
        flow['status'] = 'error'
        flow['error'] = str(exc)
        return _json_error(flow['error'], getattr(exc, "status_code", 401) or 401)

    flow['payload'] = {
        "accessToken": access_token,
        "refreshToken": refresh_token,
        "expiresAt": data.get('expiresAt') or 0,
        "user": data.get('user') or {},
        **auth_state,
    }
    # The verifier is useful only until this one-time exchange completes.
    flow.pop('code_verifier', None)
    flow.pop('code_challenge', None)
    flow['status'] = 'completed'
    flow['error'] = ''
    return jsonify({"success": True})


