@app.route('/api/agent/access', methods=['GET'])
@app.route('/api/agent/pair', methods=['POST'])
@app.route('/api/agent/revoke', methods=['POST'])
@require_active_access
def api_agent_access():
    if not _is_local_request() or not _is_trusted_browser_origin():
        return _json_error('Agent pairing is available only in the local app.', 403)
    if request.method == 'POST' and not request.is_json:
        return _json_error('A JSON request is required.', 415)
    from services import agent_access
    owner = str(request.vidzeo_user.get('user_id') or request.vidzeo_user.get('id') or '')
    try:
        if request.path.endswith('/pair'):
            payload = request.get_json(silent=True) or {}
            if not isinstance(payload, dict):
                return _json_error('Invalid pairing request.', 400)
            result = agent_access.pair(request.vidzeo_access_token, request.vidzeo_user,
                                      _extract_device_context(), payload.get('refresh_token', ''))
        elif request.path.endswith('/revoke'):
            result = agent_access.revoke(owner)
        else:
            result = agent_access.status(owner)
        response = jsonify(result)
        response.headers['Cache-Control'] = 'no-store'
        return response
    except PermissionError as exc:
        return _json_error(str(exc), 403)


@app.route('/api/agent/capabilities', methods=['GET'])
@app.route('/api/agent/requests', methods=['GET'])
@app.route('/api/agent/requests/<request_id>', methods=['GET'])
@app.route('/api/agent/requests/<request_id>/complete', methods=['POST'])
@app.route('/api/agent/jobs/<job_id>', methods=['GET'])
@app.route('/api/agent/jobs/<job_id>/retry', methods=['POST'])
@require_active_access
def api_agent_bridge(request_id=None, job_id=None):
    if not _is_local_request() or not _is_trusted_browser_origin():
        return _json_error('Agent functions require localhost.', 403)
    from services import agent_bridge
    owner = str(request.vidzeo_user.get('user_id') or request.vidzeo_user.get('id') or '')
    try:
        if job_id is not None:
            item = get_queue_manager().get_item_snapshot(job_id)
            if not item or (item.get('config') or {}).get('agent_owner_id') != owner:
                return _json_error('Agent job was not found for this account.', 404)
            if request.method == 'POST':
                if not request.is_json:
                    return _json_error('A JSON request is required.', 415)
                qm = get_queue_manager()
                if not qm.resume_item(job_id):
                    return _json_error('This job cannot be retried while active or completed.', 409)
                qm.start_worker(_queue_generation_callback)
                item = qm.get_item_snapshot(job_id)
            result = {'item': item}
        elif request_id is not None:
            if request.method == 'POST':
                if not request.is_json or request.content_length and request.content_length > 2_100_000:
                    return _json_error('Send a JSON response under 2 MB.', 400)
                payload = request.get_json(silent=True)
                if not isinstance(payload, dict):
                    return _json_error('Response must contain content or error.', 400)
                result = agent_bridge.complete_request(request_id, owner, payload.get('content'), payload.get('error', ''))
            else:
                result = agent_bridge.read_request(request_id, owner)
        elif request.path.endswith('/requests'):
            result = {'requests': agent_bridge.pending_requests(owner)}
        else:
            result = {'version': 1, 'provider': 'external_agent', 'generation_endpoint': '/api/generate',
                      'execution_mode': 'queue', 'openrouter_allowed': False,
                      'request_kinds': ['text', 'vision'], 'request_transport': 'local_inbox',
                      'instructions': 'Submit a script, poll requests, inspect supplied local images, answer each exact schema using your own reasoning, and poll the job. No desktop window is required after pairing.',
                      'manual_model': 'qwen/qwen3.5-flash-02-23'}
        response = jsonify(result)
        response.headers['Cache-Control'] = 'no-store'
        return response
    except PermissionError as exc:
        return _json_error(str(exc), 403)
    except ValueError as exc:
        return _json_error(str(exc), 400)


@app.route('/api/openrouter/status', methods=['GET', 'POST'])
def api_openrouter_status():
    payload = request.get_json(silent=True) if request.method == 'POST' else {}
    if not isinstance(payload, dict):
        payload = {}
    key = payload.get('api_key')
    if key is None:
        key = payload.get('openrouter_api_key')
    if key is None:
        key = request.args.get('api_key')
    from services.openrouter_llm import check_openrouter_key_status
    result = check_openrouter_key_status(key)
    if result.get('ok') and key:
        os.environ['OPENROUTER_API_KEY'] = str(key).strip()
    return jsonify(result)



