@app.route('/api/projects')
@require_active_access
def api_projects():
    roots = [OUTPUT_DIR]
    with _EXTRA_OUTPUT_DIRS_LOCK:
        roots.extend(Path(item) for item in list(_EXTRA_OUTPUT_DIRS))
    projects = []
    seen_paths = set()
    for root in roots:
        for project in list_projects(root):
            if project.get("path") in seen_paths:
                continue
            seen_paths.add(project.get("path"))
            projects.append(project)
    projects.sort(key=lambda item: item.get("created_at") or 0, reverse=True)
    return jsonify(projects)

@app.route('/api/projects/delete', methods=['POST'])
@require_active_access
def api_projects_delete():
    data = request.json or {}
    filename = (data.get('filename') or '').strip()
    if not filename:
        return jsonify({"error": "filename required"}), 400
    roots = [OUTPUT_DIR]
    with _EXTRA_OUTPUT_DIRS_LOCK:
        roots.extend(Path(item) for item in list(_EXTRA_OUTPUT_DIRS))
    for root in roots:
        if delete_project(root, filename):
            return jsonify({"success": True})
    return jsonify({"error": "Project not found"}), 404


