def _sanitize_user_progress_message_base(fraction, raw_msg):
    if not raw_msg:
        raw_msg = ""
    msg_str = str(raw_msg).strip()
    msg_lower = msg_str.lower()

    import re
    count_match = re.search(r'(\d+)\s*(?:/|of)\s*(\d+)', msg_str)

    try:
        f = float(fraction)
    except Exception:
        f = 0.0

    is_final_message = bool(re.fullmatch(
        r'\s*(?:complete!?|completed|video ready|finished|done)\s*',
        msg_lower,
    ))
    if f >= 0.99 or is_final_message:
        return "Video Ready"
    if msg_lower.startswith('downloading youtube footage'):
        received = re.search(r'\((\d+) clips received\)', msg_lower)
        return "Downloading YouTube footage" + (f" ({received.group(1)} clips received)" if received else "")
    if msg_lower.startswith('searching youtube'):
        candidates = re.search(r'\((\d+) candidates found\)', msg_lower)
        return "Searching YouTube" + (f" ({candidates.group(1)} candidates found)" if candidates else "")
    if msg_lower.startswith(('checking youtube footage', 'checking media relevance')):
        label = 'Checking YouTube footage' if 'youtube' in msg_lower else 'Checking media relevance'
        return label + (f" {count_match.group(1)}/{count_match.group(2)}" if count_match else "")
    # Media recovery may run concurrently with the finalization coordinator.
    # Its count is still a scene-asset phase and must not be mislabeled as a
    # rendered video merely because another worker has advanced the fraction.
    if any(k in msg_lower for k in ['youtube', 'yt-v2', 'yt clips', 'web', 'image', 'stock']):
        if count_match:
            return f"Finding scene {count_match.group(1)}/{count_match.group(2)}"
        return "Finding YouTube footage" if any(k in msg_lower for k in ['youtube', 'yt-v2', 'yt clips']) else ("Finding stock media" if 'stock' in msg_lower else "Finding web images")
    if f >= 0.70 or any(k in msg_lower for k in ['rendering video', 'ffmpeg assembly', 'final mux', 'encoding final', 'finaliz']):
        if 'final' in msg_lower or f >= 0.94:
            return "Finalizing video"
        if count_match:
            return f"Rendering video {count_match.group(1)}/{count_match.group(2)}"
        return "Rendering video"
    if 'caption' in msg_lower or 'subtitle' in msg_lower:
        return "Generating captions"
    if any(k in msg_lower for k in ['query plan', 'query planning', 'source-query', 'scene plan', 'visual plan']):
        return "Planning visual searches"
    if count_match and any(k in msg_lower for k in ['media', 'scene', 'asset', 'rescue']):
        return f"Preparing media {count_match.group(1)}/{count_match.group(2)}"
    if any(k in msg_lower for k in ['media', 'footage', 'pool', 'candidate', 'rescue']):
        return "Preparing media" if f >= 0.40 else "Searching for media"
    if any(k in msg_lower for k in ['transcrib', 'whisper', 'align']):
        return "Aligning narration"
    if any(k in msg_lower for k in ['tts', 'voice', 'audio']):
        return "Generating narration"
    elif any(k in msg_lower for k in ['script', 'analyz', 'beat', 'llm']) or f < 0.15:
        return "Analyzing your script"
    elif f < 0.30:
        return "Generating narration"
    elif f < 0.50:
        return "Searching for media"
    elif f < 0.75:
        return "Preparing media"
    else:
        return "Rendering video"


def _sanitize_user_progress_message(fraction, raw_msg):
    """Keep a live wait hint visible while a provider call is quiet."""
    clean = _sanitize_user_progress_message_base(fraction, raw_msg)
    try:
        f = float(fraction)
    except Exception:
        f = 0.0
    raw = str(raw_msg or '').strip()
    lower = raw.lower()
    if f >= 0.99 or clean == 'Video Ready':
        return clean
    if ('still working' in lower or 'please wait' in lower) and clean not in {
        'Waiting in queue', 'Submitting video', 'Starting video generation',
    }:
        import re
        match = re.search(r'\((\d+)\s*s\)', raw, re.I)
        elapsed = f" ({match.group(1)}s)" if match else ''
        return f"{clean} - still working{elapsed}; please wait"
    return clean


def _make_progress_reporter(raw_callback=None):
    """Normalize concurrent progress callbacks without hiding active stages.

    Audio, captions, media retrieval, and rendering can report in parallel.
    Their local fractions are not comparable, so a slower branch must still be
    allowed to update the stage label while the public fraction stays
    monotonic. The callback state is shared by worker threads.
    """
    if raw_callback is None:
        return lambda fraction, message: None

    import threading

    state_lock = threading.RLock()
    last_fraction = -1.0
    last_message = ""
    last_stage_detail = {}

    def _stage_detail(message):
        """Return a monotonic progress tuple for count-bearing stage labels."""
        import re

        text = str(message or "")
        patterns = (
            ("media", r"^Finding scene\s+(\d+)\s*/\s*(\d+)$"),
        )
        for stage, pattern in patterns:
            match = re.search(pattern, text, flags=re.IGNORECASE)
            if not match:
                continue
            checked = int(match.group(1))
            total = int(match.group(2))
            ready = int(match.group(3)) if match.lastindex and match.lastindex >= 3 and match.group(3) else checked
            return stage, (checked, total, ready)
        return None, None

    def _report(fraction, message):
        nonlocal last_fraction, last_message
        try:
            clamped = max(0.0, min(1.0, float(fraction)))
        except Exception:
            clamped = 0.0
        clean_msg = _sanitize_user_progress_message(clamped, message)
        # Serialize state and delivery: workers can report from separate
        # threads, and their local fractions describe different phases.
        with state_lock:
            stage, detail = _stage_detail(clean_msg)
            if stage and detail:
                previous = last_stage_detail.get(stage)
                # Shadow/fallback branches report their own subset counts.
                # Ignore stale scene counts while allowing a different active
                # phase (such as captions) to remain visible.
                if previous and (
                    detail[0] < previous[0]
                    or detail[2] < previous[2]
                ):
                    return
                if previous:
                    detail = (
                        max(detail[0], previous[0]),
                        max(detail[1], previous[1]),
                        max(detail[2], previous[2]),
                    )
                last_stage_detail[stage] = detail

            # Never discard a real phase update just because another parallel
            # branch has a larger local fraction. Preserve a monotonic public
            # fraction and expose the current phase label.
            reported_fraction = max(last_fraction, clamped)
            if reported_fraction == last_fraction and clean_msg == last_message:
                return
            last_fraction = reported_fraction
            last_message = clean_msg
            try:
                raw_callback(reported_fraction, clean_msg)
                return
            except TypeError:
                pass
            except Exception:
                pass
            try:
                raw_callback(int(round(reported_fraction * 100)), clean_msg)
            except Exception:
                pass

    return _report



def _parse_resolution_value(value, default):
    import re

    if not value:
        return default
    match = re.search(r'(\d+)\s*x\s*(\d+)', str(value))
    if not match:
        return default
    return int(match.group(1)), int(match.group(2))


def _resolve_render_resolution(config):
    # An explicit render tuple is the most precise caller contract. Honour it
    # before applying a preset so API jobs and tests cannot be silently
    # redirected to the Shorts canvas.
    explicit = config.get('render_resolution') if isinstance(config, dict) else None
    if isinstance(explicit, (tuple, list)) and len(explicit) >= 2:
        try:
            explicit_w = max(320, int(explicit[0]))
            explicit_h = max(180, int(explicit[1]))
            return explicit_w, explicit_h
        except (TypeError, ValueError):
            pass

    if (config.get('type') or '').lower() == 'short':
        raw_value = config.get('resolution') or '1080x1920 (TikTok/Shorts)'
        # A supplied landscape aspect is an intentional override of the
        # vertical Shorts preset, including shorthand values such as 1080p.
        aspect = str(config.get('aspect_ratio') or '').strip().lower()
        try:
            aspect_w, aspect_h = (float(part) for part in aspect.split(':', 1))
        except (TypeError, ValueError):
            aspect_w = aspect_h = 0.0
        if aspect_w > 0.0 and aspect_h > 0.0 and aspect_w > aspect_h:
            return (1920, 1080)
        resolved = SHORT_FORM_RESOLUTIONS.get(raw_value)
        if resolved:
            return int(resolved['width']), int(resolved['height'])
        return _parse_resolution_value(raw_value, (1080, 1920))

    raw_value = config.get('image_resolution') or '1920x1080'
    width, height = _parse_resolution_value(raw_value, (1920, 1080))
    return (1080, 1920) if height > width else (1920, 1080)


def _path_to_url(path):
    try:
        resolved = Path(path).resolve()
        temp_resolved = TEMP_DIR.resolve()
        output_resolved = OUTPUT_DIR.resolve()
        resolved_str = str(resolved).lower()
        temp_str = str(temp_resolved).lower()
        output_str = str(output_resolved).lower()

        if resolved_str.startswith(temp_str):
            rel_part = str(resolved)[len(temp_str):].replace('\\', '/').strip('/')
            return f"/temp/{rel_part}"
        if resolved_str.startswith(output_str):
            rel_part = str(resolved)[len(output_str):].replace('\\', '/').strip('/')
            return f"/output/{rel_part}"
    except Exception:
        pass
    return path


def _memory_status_snapshot():
    """Return the current render headroom for the UI and retry workflow."""
    try:
        from services.render_resource_manager import render_memory_status
        return render_memory_status()
    except Exception as exc:
        snapshot = {
            "available_mb": 0,
            "free_mb": 0,
            "total_mb": 0,
            "process_rss_mb": 0,
            "error": f"{type(exc).__name__}: {exc}",
        }
    snapshot.update(warning=False, render_blocked=False, can_start_render=None,
                    admission_state='unknown', minimum_available_mb=384,
                    warning_threshold_mb=1024,
                    message='Memory measurement is unavailable; the renderer will check before starting.')
    return snapshot


def _checkpoint_safe(value):
    """Make checkpoint payloads JSON safe while removing credentials."""
    try:
        from services.storyboard_v2.store import redact_sensitive
        return redact_sensitive(value)
    except Exception:
        return value


def _prepare_video_output_package(config, name):
    """Create one durable folder for every generation and its retry state."""
    config = config if isinstance(config, dict) else {}
    existing = str(
        config.get("_output_package_dir")
        or config.get("output_package_dir")
        or ""
    ).strip()
    if existing:
        package_dir = Path(existing).expanduser().resolve()
    else:
        root = Path(config.get("output_dir") or OUTPUT_DIR).expanduser().resolve()
        safe_name = sanitize_output_name(name)
        stamp = time.strftime("%Y%m%d_%H%M%S")
        package_dir = root / f"{safe_name}_{stamp}_{secrets.token_hex(4)}"
    package_dir.mkdir(parents=True, exist_ok=True)
    for child in ("checkpoints", "queries", "editorial", "media", "render", "logs"):
        (package_dir / child).mkdir(parents=True, exist_ok=True)
    config["_output_package_dir"] = str(package_dir)
    config["output_package_dir"] = str(package_dir)
    config["output_dir"] = str(package_dir)
    # Seed the visual grammar per output package. The package folder survives
    # retries, so a retry stays consistent while a new video gets a distinct
    # palette, template rhythm, and motion sequence.
    package_seed = int(hashlib.sha256(str(package_dir).encode("utf-8")).hexdigest()[:12], 16)
    try:
        configured_seed = int(config.get("semantic_variation_seed"))
    except (TypeError, ValueError):
        configured_seed = 0
    if not configured_seed:
        configured_seed = package_seed
    config["semantic_variation_seed"] = configured_seed
    config.setdefault("variation_seed", configured_seed)
    register_output_dir(package_dir)
    marker = package_dir / "package.json"
    if not marker.exists():
        payload = {
            "schema_version": 1,
            "package_type": "vidnets-documentary-generation",
            "created_at": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
            "name": str(name or "Video"),
            # Job identity (Nov 10, 2026 BNSF incident): two jobs can share
            # a title, so the package dir name alone cannot tell them apart.
            # The marker pins the package to its producing job.
            "job_id": str(config.get("_queue_job_id") or config.get("job_id") or ""),
            "run_id": str(config.get("_pipeline_run_id") or config.get("_queue_run_id") or config.get("run_id") or ""),
            "status": "checkpointing",
        }
        marker.write_text(json.dumps(_checkpoint_safe(payload), indent=2), encoding="utf-8")
    return package_dir


def _write_generation_checkpoint(config, filename, payload, *, stage=None, status=None):
    """Atomically persist a small, inspectable checkpoint for retry/resume."""
    package_raw = (config or {}).get("_output_package_dir") or (config or {}).get("output_package_dir")
    if not package_raw:
        return None
    package_dir = Path(str(package_raw)).expanduser().resolve()
    checkpoint_dir = package_dir / "checkpoints"
    checkpoint_dir.mkdir(parents=True, exist_ok=True)
    target = checkpoint_dir / str(filename)
    temp = target.with_name(f".{target.name}.{secrets.token_hex(4)}.part")
    safe_payload = _checkpoint_safe(payload)
    try:
        with temp.open("w", encoding="utf-8", newline="\n") as handle:
            json.dump(safe_payload, handle, ensure_ascii=False, indent=2, default=str)
            handle.write("\n")
            handle.flush()
            os.fsync(handle.fileno())
        if str(filename) == 'media_plan.json' and target.is_file():
            # A failed retrieval attempt must not erase the prior real-media
            # ledger. Keep exact bytes/provenance before atomic replacement.
            from services.media_checkpoint_history import archive_media_checkpoint
            archive_media_checkpoint(target)
        os.replace(temp, target)
    finally:
        try:
            temp.unlink(missing_ok=True)
        except OSError:
            pass
    state = {
        "stage": stage or str(filename).rsplit(".", 1)[0],
        "status": status or "saved",
        "updated_at": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
        "checkpoint": str(target),
    }
    # state.json is the resume pointer (_resume_checkpointed_remotion_render
    # gates on state["stage"]/state["status"]): a torn write here used to
    # make a checkpointed job look unresumable after a crash. Write it with
    # the same temp + fsync + atomic replace as the checkpoint itself.
    # A failed pointer write must never fail the checkpoint save.
    state_target = package_dir / "checkpoints" / "state.json"
    state_temp = state_target.with_name(f".{state_target.name}.{secrets.token_hex(4)}.part")
    try:
        with state_temp.open("w", encoding="utf-8", newline="\n") as handle:
            json.dump(_checkpoint_safe(state), handle, ensure_ascii=False, indent=2)
            handle.write("\n")
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(state_temp, state_target)
    except OSError:
        pass
    finally:
        try:
            state_temp.unlink(missing_ok=True)
        except OSError:
            pass
    return str(target)


def _copy_generation_artifact(config, source, folder="render", filename=None):
    """Copy a small JSON/text audit into the per-video package when present."""
    package_raw = (config or {}).get("_output_package_dir") or (config or {}).get("output_package_dir")
    source_path = Path(str(source or "")).expanduser() if source else None
    if not package_raw or source_path is None or not source_path.is_file():
        return None
    if source_path.suffix.lower() not in {".json", ".jsonl", ".txt", ".csv"}:
        return None
    import shutil
    package_dir = Path(str(package_raw)).expanduser().resolve()
    destination_dir = package_dir / folder
    destination_dir.mkdir(parents=True, exist_ok=True)
    destination = destination_dir / (filename or source_path.name)
    try:
        shutil.copy2(source_path, destination)
        return str(destination)
    except OSError:
        return None


def _set_video_package_status(config, status, **extra):
    package_raw = (config or {}).get("_output_package_dir") or (config or {}).get("output_package_dir")
    if not package_raw:
        return
    package_dir = Path(str(package_raw)).expanduser().resolve()
    marker = package_dir / "package.json"
    payload = {
        "schema_version": 1,
        "package_type": "vidnets-documentary-generation",
        "status": str(status),
        "updated_at": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
        **dict(extra or {}),
    }
    try:
        marker.write_text(json.dumps(_checkpoint_safe(payload), indent=2, default=str), encoding="utf-8")
    except OSError:
        pass


def _is_video_path(path):
    return str(path or '').lower().endswith(('.mp4', '.mov', '.webm', '.mkv', '.avi'))


def _local_media_path_for_render(path):
    raw = str(path or '').strip()
    if not raw:
        return ''
    normalized = raw.replace('\\', '/')
    lowered = normalized.lower()
    if lowered.startswith('/temp/'):
        rel = normalized[len('/temp/'):].strip('/')
        return str(TEMP_DIR / rel)
    if lowered.startswith('/output/'):
        rel = normalized[len('/output/'):].strip('/')
        return str(OUTPUT_DIR / rel)
    if lowered.startswith('local-media://'):
        raw = urllib.parse.unquote(raw[len('local-media://'):].lstrip('/'))
    return raw


def _media_path_exists_for_render(path):
    local_path = _local_media_path_for_render(path)
    if not local_path:
        return False
    try:
        size = os.path.getsize(local_path)
        if not (os.path.isfile(local_path) and size > 64):
            return False
    except Exception:
        return False
    # Probe only files large enough to be real media.  Tiny stubs (unit
    # fixtures, watchdogs) skip the readability gate; truncated downloads that
    # matter are multi-MB and get rejected here before they can kill renders.
    if _is_video_path(local_path) and size > 65536 and not _video_file_readable(local_path):
        return False
    return True


def _render_media_is_synthetic(path, source_label=''):
    """Keep generated recovery plates out of production scene slots."""
    return is_synthetic_media(path, source_label)


def _video_file_readable(local_path):
    """True only when ffprobe can see a decodable video stream.

    Rejects salvaged/rotated clips that are truncated or missing their moov
    atom (a raw partial download promoted by filename pattern).  Cached on
    path+size+mtime so hot render-QA loops probe each file once.
    """
    try:
        stat = os.stat(local_path)
    except OSError:
        return False
    key = (str(local_path), stat.st_size, stat.st_mtime_ns)
    cached = _VIDEO_READABLE_CACHE.get(key)
    if cached is not None:
        return cached
    readable = False
    try:
        from services.youtube_pipeline_v2 import _source_has_video_stream
        readable = bool(_source_has_video_stream(local_path))
    except Exception:
        readable = False
    # Cache positive results only: a file probed mid-write must be re-checked
    # once it finishes growing, and a corrupt file may be repaired later.
    if readable:
        _VIDEO_READABLE_CACHE[key] = True
    if not readable:
        print(f"   [media] rejecting unreadable video file: {local_path}")
    return readable


_VIDEO_READABLE_CACHE = {}
_MEDIA_CONTENT_IDENTITY_CACHE = {}
_IMAGE_MEDIA_SUFFIXES = {
    '.jpg', '.jpeg', '.png', '.webp', '.avif', '.gif', '.bmp', '.tif', '.tiff', '.jfif'
}


def _media_duplicate_key(path):
    local_path = _local_media_path_for_render(path)
    if not local_path:
        return ''
    try:
        absolute_path = os.path.abspath(local_path).lower()
        local_file = Path(local_path)
        # Web resolvers copy the same downloaded image into each scene folder.
        # Path-only identity therefore made identical bytes look unique and
        # allowed consecutive web stills through the final adjacency gate.
        # Use a content identity for image assets while keeping video identity
        # path-based (different video moments may legitimately share a source).
        if local_file.is_file() and local_file.suffix.lower() in _IMAGE_MEDIA_SUFFIXES:
            stat = local_file.stat()
            cache_key = (absolute_path, int(stat.st_size), int(stat.st_mtime_ns))
            cached = _MEDIA_CONTENT_IDENTITY_CACHE.get(cache_key)
            if cached:
                return cached
            digest = hashlib.blake2b(digest_size=16)
            with local_file.open('rb') as handle:
                for chunk in iter(lambda: handle.read(1024 * 1024), b''):
                    digest.update(chunk)
            identity = f"image-content:{digest.hexdigest()}"
            _MEDIA_CONTENT_IDENTITY_CACHE[cache_key] = identity
            return identity
        return absolute_path
    except Exception:
        return str(local_path).strip().lower()


def _canonical_image_source(value):
    """Normalize UI source labels before source-specific policy runs."""
    raw = str(value or '').strip()
    lowered = raw.lower()
    if lowered.startswith('youtube clips') or lowered in {'youtube', 'yt clips'}:
        return 'YouTube Clips'
    if lowered.startswith('mixed media') or lowered == 'mixed':
        return 'Mixed Media'
    if lowered in {'real media', 'stock'}:
        return 'Stock Media'
    if lowered in {'custom', 'upload custom'}:
        return 'Custom Images'
    return raw

def _is_custom_media_source(config):
    if not isinstance(config, dict):
        return False
    return _canonical_image_source(config.get('image_source')) == 'Custom Images'



def _final_video_reuse_cap(config=None):
    # This setting counts copies of the same local file. Distinct downloaded
    # timestamp cuts have distinct paths/fingerprints and remain eligible; an
    # exact rendered cut is never replayed elsewhere in the timeline.
    if isinstance(config, dict) and str(config.get('image_source') or '').strip() in {
        'YouTube Clips', 'Mixed Media', 'Mixed',
    }:
        return 1
    value = ''
    if isinstance(config, dict):
        value = str(config.get('max_final_video_reuse_per_clip') or '').strip()
        if not value and str(config.get('image_source') or '').strip() in {'Mixed Media', 'Mixed'}:
            # Mixed Media is a diversity mode.  A verified YouTube source may
            # be cut into many local moments, but the exact rendered clip must
            # not be copied through the timeline when another lane can fill
            # the slot.  Keep one occurrence as the deterministic default;
            # explicit config/env can opt into a bounded higher cap.
            value = os.environ.get('VIDZEO_MIXED_MAX_FINAL_REUSE_PER_CLIP') or '1'
    if not value:
        if isinstance(config, dict) and str(config.get('image_source') or '').strip() == 'YouTube Clips':
            value = os.environ.get('VIDZEO_YT_MAX_FINAL_REUSE_PER_CLIP') or '2'
        elif isinstance(config, dict) and str(config.get('yt_allow_same_source_reuse') or '').strip().lower() in {'1', 'true', 'yes', 'on'}:
            value = os.environ.get('VIDZEO_YT_MAX_FINAL_REUSE_PER_CLIP') or '12'
    if not value:
        value = (
            os.environ.get('VIDZEO_MAX_FINAL_REUSE_PER_CLIP')
            or os.environ.get('VIDZEO_YT_ROTATION_REUSE_PER_CLIP')
            or '2'
        )
    try:
        cap = int(float(value or 2))
    except Exception:
        cap = 2
    max_cap = 2 if isinstance(config, dict) and str(config.get('image_source') or '').strip() == 'YouTube Clips' else 8
    if isinstance(config, dict) and str(config.get('image_source') or '').strip() in {'Mixed Media', 'Mixed'}:
        max_cap = 2
    return max(1, min(max_cap, cap))


def _enabled(value, default=False):
    """Normalize public boolean settings without treating 'false' as true."""
    if value is None:
        return bool(default)
    if isinstance(value, bool):
        return value
    return str(value).strip().lower() in {'1', 'true', 'yes', 'on'}


def _youtube_web_fallback_enabled(config=None):
    value = ''
    if isinstance(config, dict):
        value = str(config.get('allow_web_fallback_after_youtube_exhausted') or '').strip()
    if not value:
        value = os.environ.get('VIDZEO_YT_ALLOW_WEB_FALLBACK', '0')
    return str(value).strip().lower() in {'1', 'true', 'yes', 'on'}


def _media_reuse_key(path):
    return _media_duplicate_key(path) or str(path or '').strip().lower()


def _render_image_phash(path):
    local_path = _local_media_path_for_render(path)
    if not local_path or _is_video_path(local_path):
        return None
    try:
        from PIL import Image
        with Image.open(local_path) as img:
            gray = img.convert('L').resize((8, 8))
            pixels = list(gray.getdata())
        avg = sum(pixels) / max(1, len(pixels))
        value = 0
        for idx, pixel in enumerate(pixels):
            if pixel >= avg:
                value |= (1 << idx)
        return value
    except Exception:
        return None


def _render_phash_distance(left, right):
    try:
        return int(left ^ right).bit_count()
    except Exception:
        return 64


def _strict_visual_dedupe_enabled(config=None):
    value = ''
    if isinstance(config, dict):
        value = str(config.get('strict_visual_dedupe') or '').strip()
    if not value:
        value = os.environ.get('VIDZEO_STRICT_PHASH_DEDUP', '0')
    return str(value).strip().lower() in {'1', 'true', 'yes', 'on'}


def _media_paths_are_repetitive(left, right, config=None):
    if not left or not right:
        return False
    left_key = _media_duplicate_key(left)
    right_key = _media_duplicate_key(right)
    if left_key and right_key and left_key == right_key:
        return True
    if _is_video_path(left) or _is_video_path(right):
        return False
    if not _strict_visual_dedupe_enabled(config):
        return False
    left_hash = _render_image_phash(left)
    right_hash = _render_image_phash(right)
    return (
        left_hash is not None
        and right_hash is not None
        and _render_phash_distance(left_hash, right_hash) <= 3
    )


def _create_emergency_render_asset(
    render_resolution,
    title="",
    scene_text="",
    index=0,
    root_dir=None,
    graphic_fallback=False,
    visual_requirement=None,
):
    """Create a grounded motion-graphic fallback after real media fails.

    The native renderer applies the scene's normal motion treatment to this
    image.  Grounded fallback assets live outside the emergency/placeholder
    namespace, so production can use them intentionally while still rejecting
    accidental blank plates.
    """
    try:
        from PIL import Image, ImageDraw, ImageFilter
        width, height = render_resolution or (1280, 720)
        width = max(320, int(width or 1280))
        height = max(180, int(height or 720))
        seed_text = f"{title} {scene_text} {index}".encode("utf-8", errors="ignore")
        digest = hashlib.sha256(seed_text).digest()
        requirement = visual_requirement if isinstance(visual_requirement, dict) else {}
        semantic_text = " ".join((
            str(title or ""), str(scene_text or ""),
            str(requirement.get("domain") or ""), str(requirement.get("subject_type") or ""),
            str(requirement.get("visual_intent") or ""),
        )).casefold()
        sports_field = bool(re.search(
            r"\b(?:nfl|football|quarterback|backfield|goal line|touchdown|super bowl|seahawks|patriots|yard line)\b",
            semantic_text,
        ))
        if sports_field:
            # Neutral rescue art must remain visibly legible after video
            # grading and compression; the former near-black greens read as
            # empty frames at 1080p.
            base, accent = (17, 43, 28), (38, 91, 53)
        else:
            base = (12, 16, 24)
            accent = (26, 38, 52)
        image = Image.new("RGB", (width, height), base)
        draw = ImageDraw.Draw(image, "RGBA")
        for y in range(height):
            ratio = y / max(1, height - 1)
            color = tuple(int(base[channel] * (1 - ratio) + accent[channel] * ratio) for channel in range(3))
            draw.line([(0, y), (width, y)], fill=(*color, 255))
        # Subtle ambient radial vignette instead of harsh diagonal bands
        cx, cy = width // 2, height // 2
        max_r = int(((width // 2) ** 2 + (height // 2) ** 2) ** 0.5)
        for ring in range(0, max_r, max(1, max_r // 12)):
            alpha = int(40 * (ring / max_r))
            draw.ellipse(
                [(cx - ring, cy - ring), (cx + ring, cy + ring)],
                outline=(0, 0, 0, alpha),
                width=max(1, max_r // 12),
            )
        image = image.filter(ImageFilter.GaussianBlur(radius=1.2))
        # Keep emergency rescues visually deliberate and scene-specific even
        # when real media is exhausted. A neutral plate must read as an elevated
        # documentary archival dossier or field diagram, rather than collapsing
        # to a near-black vignette that looks like a blank frame at 1080p.
        if True:
            draw = ImageDraw.Draw(image, "RGBA")
            # A missing-media asset is a visual bed for Remotion's own
            # composition, never a generated text card. The caption track
            # remains the only automatic narration text source.
            if sports_field:
                left = int(width * 0.035)
                right = int(width * 0.965)
                top = int(height * 0.11)
                bottom = int(height * 0.92)
                draw.polygon(
                    [(left, top), (right, top), (right, bottom), (left, bottom)],
                    fill=(13, 48, 29, 220),
                    outline=(214, 226, 211, 188),
                )
                # Quiet field geometry, without invented yard numbers or a
                # fabricated play route. Individual director-led diagrams
                # can add grounded actors and motion on top.
                for mark in range(1, 9):
                    x = left + round((right - left) * mark / 9)
                    alpha = 104 if mark % 2 else 142
                    draw.line([(x, top), (x, bottom)], fill=(221, 231, 219, alpha), width=max(1, width // 960))
                    for y_ratio in (0.32, 0.50, 0.68):
                        y = round(top + (bottom - top) * y_ratio)
                        tick = max(4, width // 100)
                        draw.line([(x - tick, y), (x + tick, y)], fill=(236, 241, 231, min(240, alpha + 54)), width=max(1, width // 320))
                # Restrained end-zone bands make the field legible as a
                # football surface without inventing team marks, score, or
                # the play's route.
                zone_width = max(8, round((right - left) * 0.075))
                draw.rectangle(
                    (left + 1, top + 1, left + zone_width, bottom - 1),
                    fill=(226, 183, 75, 54),
                )
                draw.rectangle(
                    (right - zone_width, top + 1, right - 1, bottom - 1),
                    fill=(226, 183, 75, 54),
                )
                if any(token in semantic_text for token in ("goal line", "yard line", "one yard", "stripe")):
                    seam_y = int(height * 0.69)
                    draw.line(
                        [(left, seam_y), (right, seam_y)],
                        fill=(245, 243, 234, 224),
                        width=max(3, height // 240),
                    )
                    glow = Image.new("RGBA", (width, height), (0, 0, 0, 0))
                    glow_draw = ImageDraw.Draw(glow, "RGBA")
                    glow_draw.line(
                        [(left, seam_y), (right, seam_y)],
                        fill=(226, 184, 74, 58),
                        width=max(12, height // 35),
                    )
                    glow = glow.filter(ImageFilter.GaussianBlur(radius=max(8, height // 100)))
                    image = Image.alpha_composite(image.convert("RGBA"), glow).convert("RGB")
            else:
                # Cinematic Documentary Archival Dossier Graphic Plate
                # Transforms unavoidable graphic fallbacks into high-end archival dossier
                # cards (Vox / Lemmino / Johnny Harris style).
                # The bottom 38% remains completely clean for Remotion's animated dynamic subtitles.

                # 1. Ambient radial spotlight bloom in the upper quadrant for natural contrast
                spotlight = Image.new("RGBA", (width, height), (0, 0, 0, 0))
                sp_draw = ImageDraw.Draw(spotlight, "RGBA")
                spot_cx = width // 2
                spot_cy = int(height * 0.32)
                spot_max_r = int(height * 0.60)
                if any(k in semantic_text for k in ("royal", "queen", "king", "prince", "palace", "crown", "monarch")):
                    glow_color = (180, 140, 50)
                    accent_bar = (225, 185, 75)
                elif any(k in semantic_text for k in ("car", "police", "auto", "engine", "train", "rail", "speed")):
                    glow_color = (65, 115, 175)
                    accent_bar = (90, 165, 235)
                else:
                    glow_color = (70, 105, 150)
                    accent_bar = (100, 155, 215)

                for r in range(spot_max_r, 0, -max(1, spot_max_r // 16)):
                    glow_alpha = int(24 * (1 - r / spot_max_r))
                    sp_draw.ellipse(
                        [(spot_cx - r, spot_cy - int(r * 0.6)), (spot_cx + r, spot_cy + int(r * 0.6))],
                        fill=(*glow_color, glow_alpha),
                    )
                spotlight = spotlight.filter(ImageFilter.GaussianBlur(radius=max(12, height // 30)))
                image = Image.alpha_composite(image.convert("RGBA"), spotlight).convert("RGB")
                draw = ImageDraw.Draw(image, "RGBA")

                # 2. Archival coordinate grid (confined to top 65% of screen)
                grid_step = max(40, width // 24)
                grid_limit_y = int(height * 0.65)
                for gx in range(grid_step, width, grid_step):
                    draw.line([(gx, 0), (gx, grid_limit_y)], fill=(190, 215, 245, 12), width=1)
                for gy in range(grid_step, grid_limit_y, grid_step):
                    draw.line([(0, gy), (width, gy)], fill=(190, 215, 245, 12), width=1)

                # Crosshairs at select grid intersections
                tick_len = max(3, width // 380)
                for gx in range(grid_step * 2, width, grid_step * 3):
                    for gy in range(grid_step * 2, grid_limit_y, grid_step * 2):
                        draw.line([(gx - tick_len, gy), (gx + tick_len, gy)], fill=(210, 230, 255, 35), width=1)
                        draw.line([(gx, gy - tick_len), (gx, gy + tick_len)], fill=(210, 230, 255, 35), width=1)

                # 3. Viewfinder framing brackets (L-brackets at corners)
                margin_x = int(width * 0.045)
                margin_y = int(height * 0.065)
                bracket_len = int(width * 0.030)
                bracket_color = (205, 225, 250, 120)
                bracket_w = max(1, width // 800)

                draw.line([(margin_x, margin_y), (margin_x + bracket_len, margin_y)], fill=bracket_color, width=bracket_w)
                draw.line([(margin_x, margin_y), (margin_x, margin_y + bracket_len)], fill=bracket_color, width=bracket_w)
                draw.line([(width - margin_x, margin_y), (width - margin_x - bracket_len, margin_y)], fill=bracket_color, width=bracket_w)
                draw.line([(width - margin_x, margin_y), (width - margin_x, margin_y + bracket_len)], fill=bracket_color, width=bracket_w)
                draw.line([(margin_x, height - margin_y), (margin_x + bracket_len, height - margin_y)], fill=bracket_color, width=bracket_w)
                draw.line([(margin_x, height - margin_y), (margin_x, height - margin_y - bracket_len)], fill=bracket_color, width=bracket_w)
                draw.line([(width - margin_x, height - margin_y), (width - margin_x - bracket_len, height - margin_y)], fill=bracket_color, width=bracket_w)
                draw.line([(width - margin_x, height - margin_y), (width - margin_x, height - margin_y - bracket_len)], fill=bracket_color, width=bracket_w)

                # 4. Archival Dossier Header Badge (Upper quadrant, safe from subtitles)
                badge_x = margin_x + int(width * 0.015)
                badge_y = margin_y + int(height * 0.025)

                scene_num = max(1, int(index or 1))
                badge_label = f"DOCUMENTARY ARCHIVE // RECORD #{scene_num:02d}"

                entity_name = str(requirement.get("canonical_entity") or "").strip()
                if not entity_name:
                    terms = [str(t).strip() for t in (requirement.get("required_terms") or []) if str(t).strip()]
                    if terms:
                        entity_name = terms[0]
                if not entity_name and title:
                    entity_name = title.split(":")[-1].split("—")[-1].strip()
                if entity_name:
                    subject_label = f"SUBJECT // {entity_name.upper()[:45]}"
                else:
                    subject_label = f"SUBJECT // SCENE {scene_num:02d} OVERVIEW"

                subtext = str(requirement.get("visual_intent") or "").strip()
                if not subtext and scene_text:
                    subtext = scene_text.strip().split(".")[0]
                if len(subtext) > 70:
                    subtext = subtext[:67] + "..."

                from PIL import ImageFont
                def _get_font(font_name, target_size):
                    windir = os.environ.get("WINDIR", "C:\\Windows")
                    cand = os.path.join(windir, "Fonts", font_name)
                    try:
                        return ImageFont.truetype(cand, target_size)
                    except Exception:
                        return ImageFont.load_default()

                font_badge = _get_font("consola.ttf", max(11, int(height * 0.018)))
                font_title = _get_font("segoeui.ttf", max(18, int(height * 0.038)))
                font_sub = _get_font("segoeui.ttf", max(12, int(height * 0.020)))

                pill_w = max(260, int(width * 0.22))
                pill_h = max(24, int(height * 0.032))
                draw.rounded_rectangle(
                    [(badge_x, badge_y), (badge_x + pill_w, badge_y + pill_h)],
                    radius=4,
                    fill=(20, 32, 48, 190),
                    outline=(*accent_bar, 140),
                    width=1,
                )
                draw.text(
                    (badge_x + 12, badge_y + int(pill_h * 0.18)),
                    badge_label,
                    font=font_badge,
                    fill=(180, 215, 255, 230),
                )

                title_y = badge_y + pill_h + int(height * 0.018)
                draw.text(
                    (badge_x, title_y),
                    subject_label,
                    font=font_title,
                    fill=(240, 245, 255, 240),
                )

                if subtext:
                    sub_y = title_y + int(height * 0.046)
                    draw.text(
                        (badge_x, sub_y),
                        subtext.upper(),
                        font=font_sub,
                        fill=(155, 180, 210, 180),
                    )
                    rule_y = sub_y + int(height * 0.032)
                else:
                    rule_y = title_y + int(height * 0.046)

                rule_w = min(int(width * 0.45), max(300, int(width * 0.35)))
                draw.line([(badge_x, rule_y), (badge_x + rule_w, rule_y)], fill=(*accent_bar, 90), width=1)
                draw.ellipse(
                    [(badge_x - 3, rule_y - 3), (badge_x + 3, rule_y + 3)],
                    fill=(*accent_bar, 230),
                )

        target_root = Path(root_dir) if root_dir else TEMP_DIR
        target = target_root / "render_media" / ("graphics" if graphic_fallback else "emergency")
        target.mkdir(parents=True, exist_ok=True)
        prefix = "graphic_fallback" if graphic_fallback else "emergency_render"
        suffix = ".png" if graphic_fallback else ".jpg"
        path = target / f"{prefix}_{int(time.time() * 1000)}_{index}_{secrets.token_hex(3)}{suffix}"
        if graphic_fallback:
            image.save(path, "PNG", optimize=False)
        else:
            image.save(path, "JPEG", quality=92)
        return str(path)
    except Exception as exc:
        print(f"   [media] emergency render asset failed: {exc}")
        return None


def _fill_final_bad_slots_from_existing_media(
    final_paths,
    source_labels,
    bad_indices,
    scene_texts,
    render_resolution,
    title,
    prefer_video=True,
    config=None,
    allow_emergency=True,
    section_subjects=None,
):
    if not bad_indices:
        return 0
    bad_set = set(bad_indices)
    reusable_indices = [
        idx for idx, path in enumerate(final_paths or [])
        if idx not in bad_set
        and _media_path_exists_for_render(path)
        and (not prefer_video or _is_video_path(path))
    ]
    if not reusable_indices and prefer_video:
        reusable_indices = [
            idx for idx, path in enumerate(final_paths or [])
            if idx not in bad_set and _media_path_exists_for_render(path)
        ]
    strict_video_pool = isinstance(config, dict) and str(config.get('image_source') or '').strip() in {
        'YouTube Clips', 'Mixed Media', 'Mixed',
    }
    max_reuse_per_path = _final_video_reuse_cap(config) if strict_video_pool else 3
    reuse_counts = Counter(
        _media_reuse_key(path)
        for path in final_paths or []
        if path and _media_path_exists_for_render(path) and _media_reuse_key(path)
    )
    subject_locks = list(
        section_subjects
        or _section_subjects_from_config(config, len(final_paths or []))
        or []
    )
    filled = 0
    for idx in bad_indices:
        if idx >= len(final_paths):
            continue
        if reusable_indices:
            viable_reusable = [
                candidate_idx for candidate_idx in reusable_indices
                if reuse_counts.get(_media_reuse_key(final_paths[candidate_idx]), 0) < max_reuse_per_path
            ]
            if viable_reusable:
                # Section-aware: prefer candidates in the same section container if available
                section_aware_candidates = viable_reusable
                if subject_locks and idx < len(subject_locks) and len(subject_locks) > 1:
                    missing_section = str(subject_locks[idx] or "").strip().casefold()
                    if missing_section:
                        matching_section = [
                            c for c in viable_reusable
                            if c < len(subject_locks)
                            and str(subject_locks[c] or "").strip().casefold() == missing_section
                        ]
                        # An explicit scene/container identity is a hard reuse
                        # boundary. If its own media is unavailable, don't
                        # silently put another player, place, or list item on
                        # screen to make the timeline look complete.
                        section_aware_candidates = matching_section
                if not section_aware_candidates:
                    continue
                nearest = min(section_aware_candidates, key=lambda candidate_idx: abs(candidate_idx - idx))
                final_paths[idx] = final_paths[nearest]
                selected_key = _media_reuse_key(final_paths[idx])
                if selected_key:
                    reuse_counts[selected_key] += 1
                if idx < len(source_labels):
                    source_labels[idx] = f"{source_labels[nearest] or 'Media'} (final render reuse)"
                filled += 1
                continue
        if not allow_emergency:
            continue
        emergency_path = _create_emergency_render_asset(
            render_resolution,
            title=title,
            scene_text=scene_texts[idx] if idx < len(scene_texts or []) else "",
            index=idx + 1,
        )
        if emergency_path and _media_path_exists_for_render(emergency_path):
            final_paths[idx] = emergency_path
            if idx < len(source_labels):
                source_labels[idx] = "Emergency Visual Fallback"
            emergency_key = _media_reuse_key(emergency_path)
            if emergency_key:
                reuse_counts[emergency_key] += 1
            filled += 1
    if filled:
        fill_source = "existing media/emergency visuals" if allow_emergency else "existing real media"
        print(
            f"   [media] render QA: filled {filled}/{len(bad_indices)} final slot(s) "
            f"from {fill_source} after provider repair failed"
        )
    return filled


def _break_back_to_back_media_repeats(
    media_paths,
    source_labels=None,
    config=None,
    resolution_rows=None,
):
    """Reorder adjacent duplicate assets while keeping scene metadata aligned.

    Providers sometimes copy one downloaded still into several scene folders.
    The content-based duplicate key catches those copies, but the old repair
    only swapped paths and labels.  V2 also carries a resolution ledger, so a
    path swap must move its row at the same time or the manifest would claim
    the wrong source/subject for the rendered asset.
    """
    paths = list(media_paths or [])
    labels = list(source_labels or [])
    if len(labels) < len(paths):
        labels.extend([''] * (len(paths) - len(labels)))
    rows = resolution_rows if isinstance(resolution_rows, list) else None
    if rows is not None and len(rows) < len(paths):
        rows.extend({} for _ in range(len(paths) - len(rows)))
    fixed = 0

    # Inputs are immutable assets during this pass. Read each identity once;
    # repeatedly statting files inside full-timeline trial scans was cubic
    # work and could burn twenty minutes on 123 identical emergency plates.
    identity_cache = {}
    hash_cache = {}
    pair_cache = {}
    strict = _strict_visual_dedupe_enabled(config)
    for path in paths:
        if path and str(path) not in identity_cache:
            identity_cache[str(path)] = _media_duplicate_key(path)

    def repetitive(left, right):
        if not left or not right:
            return False
        pair = tuple(sorted((str(left), str(right))))
        if pair in pair_cache:
            return pair_cache[pair]
        left_key, right_key = identity_cache[str(left)], identity_cache[str(right)]
        result = bool(left_key and right_key and left_key == right_key)
        if not result and strict and not (_is_video_path(left) or _is_video_path(right)):
            for path in (left, right):
                if str(path) not in hash_cache:
                    hash_cache[str(path)] = _render_image_phash(path)
            left_hash, right_hash = hash_cache[str(left)], hash_cache[str(right)]
            result = bool(left_hash is not None and right_hash is not None
                          and _render_phash_distance(left_hash, right_hash) <= 3)
        pair_cache[pair] = result
        return result

    identities = set(identity_cache.values())
    if len(identities) == 1 and all(identities):
        # No permutation of identical bytes can improve adjacency.
        return paths, labels[:len(paths)], fixed

    for idx in range(1, len(paths)):
        if not repetitive(paths[idx - 1], paths[idx]):
            continue

        swap_idx = None
        # Prefer a later scene because that preserves the original narrative
        # ordering as much as possible.  A duplicate in the final slot has no
        # later candidate, however, so also consider earlier non-neighbouring
        # scenes.  This is common after bounded rescue reuses the last valid
        # still for two closing scenes.
        candidate_indices = list(range(idx + 1, len(paths))) + list(range(0, max(0, idx - 1)))
        if rows is not None and idx < len(rows):
            current_container = str(
                (rows[idx] or {}).get('container_id')
                if isinstance(rows[idx], dict) else ''
            ).strip()
            # Prefer an alternate from the same factual container before
            # borrowing a later scene. This keeps the diversity repair from
            # trading a duplicate still for a subject mismatch in listicles.
            candidate_indices.sort(
                key=lambda candidate_index: (
                    0
                    if current_container
                    and candidate_index < len(rows)
                    and isinstance(rows[candidate_index], dict)
                    and str(rows[candidate_index].get('container_id') or '').strip() == current_container
                    else 1,
                    candidate_index,
                )
            )
        for candidate_idx in candidate_indices:
            candidate = paths[candidate_idx]
            if not candidate:
                continue
            if rows is not None and idx < len(rows) and candidate_idx < len(rows):
                current_row = rows[idx] if isinstance(rows[idx], dict) else {}
                candidate_row = rows[candidate_idx] if isinstance(rows[candidate_idx], dict) else {}
                current_container = str(current_row.get('container_id') or '').strip()
                candidate_container = str(candidate_row.get('container_id') or '').strip()
                if current_container and candidate_container and current_container != candidate_container:
                    # Do not solve repetition by moving a different
                    # listicle subject into this scene. An unresolved repeat
                    # is preferable to a semantically wrong visual.
                    continue
                current_decision = current_row.get('visual_decision') or {}
                candidate_decision = candidate_row.get('visual_decision') or {}
                current_review = str(current_decision.get('verified_requirement_hash') or '')
                candidate_review = str(candidate_decision.get('verified_requirement_hash') or '')
                if current_review or candidate_review:
                    if not current_review or current_review != candidate_review:
                        # Shared containers do not imply interchangeable
                        # narrated facts. Keep a review bound to its beat.
                        continue
                if (_render_media_is_synthetic(paths[idx], labels[idx])
                        or _render_media_is_synthetic(candidate, labels[candidate_idx])):
                    continue
            # Only four boundaries can change in a swap. Their exact delta
            # equals a whole-timeline comparison without rescanning every
            # unchanged edge for every candidate.
            edges = {edge for edge in (idx - 1, idx, candidate_idx - 1, candidate_idx)
                     if 0 <= edge < len(paths) - 1}
            current_repeats = sum(
                repetitive(paths[edge], paths[edge + 1]) for edge in edges
            )
            def proposed_path(position):
                return paths[candidate_idx] if position == idx else paths[idx] if position == candidate_idx else paths[position]
            proposed_repeats = sum(
                repetitive(proposed_path(edge), proposed_path(edge + 1)) for edge in edges
            )
            if proposed_repeats >= current_repeats:
                continue
            swap_idx = candidate_idx
            break

        if swap_idx is None:
            continue
        paths[idx], paths[swap_idx] = paths[swap_idx], paths[idx]
        labels[idx], labels[swap_idx] = labels[swap_idx], labels[idx]
        if rows is not None:
            scene_fields = ('scene_id', 'scene_index', 'container_id', 'contract_hash', 'final_scene_context')
            left_context = {key: rows[idx][key] for key in scene_fields if isinstance(rows[idx], dict) and key in rows[idx]}
            right_context = {key: rows[swap_idx][key] for key in scene_fields if isinstance(rows[swap_idx], dict) and key in rows[swap_idx]}
            left_source, right_source = rows[idx], rows[swap_idx]
            rows[idx] = {**right_source, **left_context} if isinstance(right_source, dict) else right_source
            rows[swap_idx] = {**left_source, **right_context} if isinstance(left_source, dict) else left_source
        fixed += 1

    return paths, labels[:len(paths)], fixed


def _decode_data_uri_to_temp(data_uri, index=0):
    try:
        payload = data_uri.split(',', 1)[1]
        blob = base64.b64decode(payload)
        suffix = '.png'
        if data_uri.startswith('data:image/jpeg'):
            suffix = '.jpg'
        elif data_uri.startswith('data:image/webp'):
            suffix = '.webp'
        temp_path = TEMP_DIR / f"custom_media_{int(time.time())}_{index}{suffix}"
        with open(temp_path, 'wb') as handle:
            handle.write(blob)
        return str(temp_path)
    except Exception:
        return None


def _extract_custom_media_paths(config):
    items = list(config.get('images') or config.get('custom_images') or [])
    paths = []
    for index, item in enumerate(items):
        candidate = item.get('path') if isinstance(item, dict) else item
        if not candidate:
            continue
        if isinstance(candidate, str) and candidate.startswith('data:'):
            decoded = _decode_data_uri_to_temp(candidate, index=index)
            if decoded:
                paths.append(decoded)
            continue
        if isinstance(candidate, str) and candidate.startswith('/temp/'):
            local_path = TEMP_DIR / Path(candidate).name
            if local_path.exists():
                paths.append(str(local_path))
            continue
        if isinstance(candidate, str) and candidate.startswith('/output/'):
            local_path = OUTPUT_DIR / Path(candidate).name
            if local_path.exists():
                paths.append(str(local_path))
            continue
        if isinstance(candidate, str) and os.path.exists(candidate):
            paths.append(candidate)
    return paths


def _align_scene_media_count(paths, target_count, cycle_existing=False):
    normalized = list(paths or [])
    if target_count <= 0:
        return []
    if len(normalized) >= target_count:
        return normalized[:target_count]
    if cycle_existing and normalized:
        base = list(normalized)
        while len(normalized) < target_count:
            normalized.append(base[len(normalized) % len(base)])
        return normalized[:target_count]
    normalized.extend([None] * (target_count - len(normalized)))
    return normalized


def _snapshot_media_for_render(paths, namespace="youtube", root_dir=None, *, copy_compatible=True, normalize_videos=True):
    """Copy retrieval outputs into a job-local directory and normalize video codecs.

    Remotion's frame compositor is reliable with H.264 MP4 sources. Retrieval
    providers can return AV1 MP4s (especially recovered YouTube clips) that
    pass ordinary ffprobe checks but fail Remotion's review-frame extraction.
    Transcode only non-H.264 video snapshots; leave already-compatible video
    and all still images byte-for-byte intact.
    """
    import shutil
    snapshot_root = Path(root_dir) if root_dir else TEMP_DIR
    snapshot_dir = snapshot_root / "render_media" / f"{namespace}_{int(time.time() * 1000)}_{secrets.token_hex(3)}"
    snapshot_dir.mkdir(parents=True, exist_ok=True)
    snapshotted = []
    copied_by_source = {}

    def _probe_snapshot_source(source_path):
        from services.media_integrity import resolve_ffmpeg_pair

        _ffmpeg, ffprobe = resolve_ffmpeg_pair(BASE_DIR)
        result = subprocess.run(
            [
                ffprobe, "-v", "error", "-show_entries",
                "format=duration,format_name:stream=codec_name,codec_type",
                "-of", "json", str(source_path),
            ],
            capture_output=True,
            text=True,
            timeout=15,
            check=False,
        )
        if result.returncode != 0:
            raise RuntimeError((result.stderr or "ffprobe rejected retrieved video")[-500:])
        payload = json.loads(result.stdout or "{}")
        streams = payload.get("streams") if isinstance(payload, dict) else []
        streams = streams if isinstance(streams, list) else []
        video = next((row for row in streams if isinstance(row, dict) and row.get("codec_type") == "video"), {})
        audio = next((row for row in streams if isinstance(row, dict) and row.get("codec_type") == "audio"), {})
        duration = 0.0
        try:
            duration = float(((payload.get("format") or {}).get("duration")) or 0.0)
        except (TypeError, ValueError):
            pass
        if not video.get("codec_name"):
            raise RuntimeError("retrieved video has no decodable video stream")
        return str(video.get("codec_name") or "").casefold(), duration, bool(audio)

    def _transcode_remotion_video(source_path, target_path, duration, has_audio):
        from services.media_integrity import promote_verified_media, resolve_ffmpeg_pair

        ffmpeg, ffprobe = resolve_ffmpeg_pair(BASE_DIR)
        staged = target_path.with_name(f"{target_path.stem}.{os.getpid()}.part.mp4")
        staged.unlink(missing_ok=True)
        command = [
            ffmpeg, "-y", "-hide_banner", "-loglevel", "error", "-i", str(source_path),
            "-map", "0:v:0", "-map", "0:a?", "-c:v", "libx264", "-preset", "veryfast",
            "-crf", "18", "-pix_fmt", "yuv420p", "-movflags", "+faststart",
        ]
        if has_audio:
            command.extend(["-c:a", "aac", "-b:a", "160k"])
        else:
            command.append("-an")
        command.append(str(staged))
        timeout = max(60.0, min(300.0, 30.0 + max(0.0, duration) * 12.0))
        try:
            completed = subprocess.run(
                command,
                capture_output=True,
                text=True,
                timeout=timeout,
                check=False,
            )
            if completed.returncode != 0:
                raise RuntimeError((completed.stderr or f"ffmpeg exited {completed.returncode}")[-800:])
            promoted = promote_verified_media(
                staged,
                target_path,
                ffprobe_path=ffprobe,
                ffmpeg_path=ffmpeg,
                require_video=True,
                min_bytes=4096,
                min_duration=0.05,
                require_decode=True,
            )
            if not promoted.valid:
                raise RuntimeError(f"transcoded clip failed integrity validation: {promoted.reason}")
            render_codec, _render_duration, _render_audio = _probe_snapshot_source(target_path)
            if render_codec != "h264":
                raise RuntimeError(f"transcoded clip codec is {render_codec!r}, expected h264")
            return str(target_path)
        finally:
            staged.unlink(missing_ok=True)

    for index, raw_path in enumerate(paths or []):
        local_path = _local_media_path_for_render(raw_path)
        if not _media_path_exists_for_render(local_path):
            snapshotted.append(None)
            continue
        source_key = os.path.abspath(local_path).lower()
        if source_key in copied_by_source:
            snapshotted.append(copied_by_source[source_key])
            continue
        is_video = _is_video_path(local_path)
        suffix = Path(local_path).suffix or ".mp4"
        codec = ""
        duration = 0.0
        has_audio = False
        if is_video and normalize_videos:
            try:
                codec, duration, has_audio = _probe_snapshot_source(local_path)
            except Exception as exc:
                print(f"   [media] render snapshot probe failed for {Path(local_path).name}: {exc}", flush=True)
        if (
            is_video
            and codec == "h264"
            and suffix.casefold() == ".mp4"
            and not copy_compatible
        ):
            copied_by_source[source_key] = local_path
            snapshotted.append(local_path)
            continue
        target = snapshot_dir / f"scene_{index + 1:04d}{suffix}"
        try:
            if is_video and codec and (codec != "h264" or suffix.casefold() != ".mp4"):
                target = snapshot_dir / f"scene_{index + 1:04d}.mp4"
                copied_path = _transcode_remotion_video(local_path, target, duration, has_audio)
                print(
                    f"   [media] normalized render clip {Path(local_path).name}: {codec} -> h264 ({duration:.2f}s)",
                    flush=True,
                )
            else:
                shutil.copy2(local_path, target)
                copied_path = str(target)
            copied_by_source[source_key] = copied_path
            snapshotted.append(copied_path)
        except Exception as exc:
            print(f"   [media] render snapshot failed for {Path(local_path).name}: {exc}", flush=True)
            snapshotted.append(local_path if _media_path_exists_for_render(local_path) else None)
    copied_count = sum(1 for path in snapshotted if path)
    if copied_count and (len(snapshotted) > 1 or str(os.environ.get("VIDZEO_VERBOSE", "0")).lower() in {"1", "true", "yes"}):
        print(f"   [media] render snapshot: preserved {copied_count}/{len(snapshotted)} asset slot(s)")
    return snapshotted


def _normalize_selected_render_shots(manifest, root_dir=None):
    """Adapt selected video bytes after retrieval, retaining their review provenance."""
    from services.visual_intelligence.decision import asset_fingerprint
    from services.media_integrity import resolve_ffmpeg_pair

    media_rows = [scene.get('media') for scene in manifest.get('scenes') or []
                  if isinstance(scene, Mapping) and isinstance(scene.get('media'), dict)]
    shots = [shot for media in media_rows for shot in media.get('shots') or [] if isinstance(shot, dict)]
    inputs = list(dict.fromkeys(
        str(value) for row in [*media_rows, *shots] for key in ('path', 'asset_path', 'src')
        if (value := row.get(key)) and _is_video_path(str(value))
        and _media_path_exists_for_render(str(value))
    ))
    if not inputs:
        return []
    outputs = _snapshot_media_for_render(inputs, namespace='selected_render', root_dir=root_dir,
                                         copy_compatible=False)
    _, ffprobe = resolve_ffmpeg_pair(BASE_DIR)
    records = []
    replacements = {}
    for source, target in zip(inputs, outputs):
        if not target:
            raise RuntimeError('Selected render video normalization did not produce an input')
        probe = subprocess.run([ffprobe, '-v', 'error', '-select_streams', 'v:0',
                                '-show_entries', 'stream=codec_name', '-of', 'json', str(target)],
                               capture_output=True, text=True, timeout=15, check=False)
        streams = (json.loads(probe.stdout or '{}').get('streams') or []) if probe.returncode == 0 else []
        if not streams or streams[0].get('codec_name') != 'h264':
            raise RuntimeError('Selected render video is not H.264 after normalization; media retained for retry')
        if os.path.normcase(os.path.abspath(source)) == os.path.normcase(os.path.abspath(str(target))):
            continue
        record = {'schema_version': 'render_media_normalization.v1', 'kind': 'codec_transcode',
                  'tool': 'vidzeo_media_snapshot_v1', 'source_path': source,
                  'source_sha256': asset_fingerprint(source), 'render_path': str(target),
                  'render_sha256': asset_fingerprint(str(target)), 'render_codec': 'h264'}
        records.append(record)
        replacements[source] = record
    for row in [*media_rows, *shots]:
        for key in ('path', 'asset_path', 'src', 'url'):
            value = row.get(key)
            record = replacements.get(str(value or ''))
            if record:
                row[key] = record['render_path']
                if row in shots:
                    row['render_transform'] = dict(record)
            else:
                for original, candidate in replacements.items():
                    if value == _path_to_url(original):
                        row[key] = _path_to_url(candidate['render_path'])
                        break
    manifest['render_input_normalization'] = records
    return records


def _hydrate_grounded_scene_requirements(manifest, media_items):
    """Retain exact entity/provenance after director scene serialization."""
    for index, scene in enumerate(manifest.get('scenes') or []):
        if not isinstance(scene, dict) or index >= len(media_items):
            continue
        item = media_items[index] if isinstance(media_items[index], Mapping) else {}
        requirement = item.get('visual_requirement') or {}
        if isinstance(requirement, Mapping):
            scene['visual_requirement'] = dict(requirement)
        graphic = item.get('graphic_fallback') or {}
        if (isinstance(graphic, Mapping) and graphic.get('grounded') is True
                and graphic.get('requirement_hash')
                and graphic.get('requirement_hash') == requirement.get('requirement_hash')):
            scene.setdefault('media', {})['graphic_fallback'] = dict(graphic)


def _build_component_manifest(media_paths, scene_durations, name, source_labels=None, duration=None, extra=None):
    clips = []
    source_labels = list(source_labels or [])
    resolution_rows = list((extra or {}).get('media_resolution_v2') or [])
    offset = 0.0
    for index, path in enumerate(media_paths):
        clip_duration = float(scene_durations[index] if index < len(scene_durations) else 0.0)
        resolution = resolution_rows[index] if index < len(resolution_rows) and isinstance(resolution_rows[index], dict) else {}
        clip = {
            "path": path,
            "url": _path_to_url(path),
            "start": 0,
            "end": round(clip_duration, 3),
            "track_offset": round(offset, 3),
            "source": source_labels[index] if index < len(source_labels) else "Generated",
            "media_type": "video" if _is_video_path(path) else "image",
        }
        if resolution:
            clip.update({
                "scene_id": resolution.get('scene_id') or '',
                "container_id": resolution.get('container_id') or '',
                "contract_hash": resolution.get('contract_hash') or '',
                "candidate_id": resolution.get('candidate_id') or '',
                "provider": resolution.get('provider') or '',
                "source_url": resolution.get('source_url') or '',
                "rights_status": resolution.get('rights_status') or 'unknown',
                "license": resolution.get('license') or '',
                "license_url": resolution.get('license_url') or '',
                "attribution": resolution.get('attribution') or '',
                "creator": resolution.get('creator') or '',
                "query": resolution.get('query_used') or '',
                "video_start": resolution.get('video_start'),
                "video_end": resolution.get('video_end'),
                "verification_status": resolution.get('verification_status') or '',
                "resolution_kind": resolution.get('resolution_kind') or 'unique',
                "fallback_reason": resolution.get('fallback_reason') or '',
                "overlay_policy": resolution.get('overlay_policy') or '',
                "overlay_types": list(resolution.get('overlay_types') or []),
                "blur_regions": list(resolution.get('blur_regions') or []),
                "rejection_reason": resolution.get('rejection_reason') or '',
                "cleaned_path": resolution.get('cleaned_path') or '',
            })
        clips.append(clip)
        offset += clip_duration

    manifest = {
        "schema_version": "2.0" if resolution_rows else "1.0",
        "name": name,
        "fps": 30,
        "duration": round(duration if duration is not None else offset, 3),
        "video_clips": clips,
        "source_accounting": dict(Counter(
            source_labels[index] if index < len(source_labels) and source_labels[index] else 'Unresolved'
            for index in range(len(media_paths))
        )),
    }
    if extra:
        manifest.update(extra)
    return manifest


def _scene_text_similarity(left, right):
    import difflib
    left = str(left or "").strip().lower()
    right = str(right or "").strip().lower()
    if not left or not right:
        return 0.0
    sequence_score = difflib.SequenceMatcher(None, left, right).ratio()
    left_words = {w for w in re.findall(r"[a-z0-9']+", left) if len(w) > 2}
    right_words = {w for w in re.findall(r"[a-z0-9']+", right) if len(w) > 2}
    if left_words and right_words:
        overlap_score = len(left_words & right_words) / max(1, len(left_words | right_words))
        return (sequence_score * 0.55) + (overlap_score * 0.45)
    return sequence_score


def _remap_media_plan_to_audio_scenes(media_plan, audio_plan):
    source_texts = list((media_plan.get('metadata') or {}).get('source_scene_texts') or [])
    target_texts = list(audio_plan.get('scene_texts') or [])
    if not source_texts or not target_texts:
        return media_plan

    media_paths = list(media_plan.get('media_paths') or [])
    source_labels = list(media_plan.get('source_labels') or [])
    prompt_bundle = media_plan.setdefault('prompt_bundle', {})
    if len(media_paths) == len(target_texts) and source_texts[:len(target_texts)] == target_texts:
        prompt_bundle['beat_texts'] = target_texts
        media_plan['prompt_bundle'] = prompt_bundle
        return media_plan

    if len(media_paths) == len(target_texts) and len(source_texts) == len(target_texts):
        pair_scores = [
            _scene_text_similarity(source_texts[index], target_texts[index])
            for index in range(len(target_texts))
        ]
        avg_pair_score = sum(pair_scores) / max(1, len(pair_scores))
        low_pair_count = sum(1 for score in pair_scores if score < 0.42)
        if avg_pair_score < 0.58 or low_pair_count > max(2, len(pair_scores) // 5):
            print(
                "   [flow] media: same-count Whisper scenes shifted; "
                f"remapping by similarity (avg={avg_pair_score:.2f}, low={low_pair_count})"
            )
        else:
            prompt_bundle['beat_texts'] = target_texts
            media_plan['prompt_bundle'] = prompt_bundle
            metadata = media_plan.setdefault('metadata', {})
            metadata['media_scene_remap'] = {
                "from_scene_count": len(source_texts),
                "to_scene_count": len(target_texts),
                "method": "script_scene_to_whisper_scene_order_preserved",
                "average_text_similarity": round(avg_pair_score, 3),
            }
            print(
                "   [flow] media: synced media to Whisper timings without remapping assets "
                f"({len(source_texts)} scenes preserved one-to-one, avg similarity {avg_pair_score:.2f})"
            )
            return media_plan

    mapped_paths = []
    mapped_labels = []
    last_source_index = -1
    used_source_indices = set()
    youtube_video_source = any(
        'youtube' in str(label or '').lower()
        for label in source_labels
    )
    strict_unique_youtube_timing = bool(
        (media_plan.get('metadata') or {}).get('strict_unique_youtube_timing')
    )
    duplicate_slots_left_for_repair = []
    for target_index, target_text in enumerate(target_texts):
        ideal_position = 0.0
        if len(target_texts) > 1 and len(source_texts) > 1:
            ideal_position = target_index * (len(source_texts) - 1) / (len(target_texts) - 1)
        best_index = None
        best_score = -1.0
        source_range = range(len(source_texts))
        preferred = [idx for idx in source_range if idx not in used_source_indices]
        fallback = [idx for idx in source_range if idx in used_source_indices]
        candidate_indices = preferred + fallback
        for source_index in candidate_indices:
            source_text = source_texts[source_index]
            if source_index >= len(media_paths):
                continue
            text_score = _scene_text_similarity(target_text, source_text)
            position_penalty = abs(source_index - ideal_position) / max(1, len(source_texts))
            monotonic_penalty = 0.35 if source_index < last_source_index else 0.0
            reuse_penalty = 0.50 if source_index in used_source_indices and len(source_texts) >= len(target_texts) else 0.0
            score = text_score - position_penalty - monotonic_penalty - reuse_penalty
            if score > best_score:
                best_score = score
                best_index = source_index
        if best_index is None:
            best_index = min(max(0, round(ideal_position)), max(0, len(media_paths) - 1))
        if (
            youtube_video_source
            and strict_unique_youtube_timing
            and len(source_texts) < len(target_texts)
            and best_index in used_source_indices
        ):
            duplicate_slots_left_for_repair.append(target_index)
            mapped_paths.append(None)
            mapped_labels.append('')
            continue
        last_source_index = max(last_source_index, best_index)
        used_source_indices.add(best_index)
        mapped_paths.append(media_paths[best_index] if best_index < len(media_paths) else None)
        mapped_labels.append(source_labels[best_index] if best_index < len(source_labels) else '')

    media_plan['media_paths'] = mapped_paths
    media_plan['source_labels'] = mapped_labels
    prompt_bundle['beat_texts'] = target_texts
    media_plan['prompt_bundle'] = prompt_bundle
    metadata = media_plan.setdefault('metadata', {})
    metadata['media_scene_remap'] = {
        "from_scene_count": len(source_texts),
        "to_scene_count": len(target_texts),
        "method": "script_scene_to_whisper_scene_similarity",
    }
    if duplicate_slots_left_for_repair:
        metadata['media_scene_remap']['unmapped_duplicate_slots'] = [
            index + 1 for index in duplicate_slots_left_for_repair
        ]
        print(
            "   [flow] media: left "
            f"{len(duplicate_slots_left_for_repair)} duplicate YouTube timing slot(s) "
            "open for real clip repair"
        )
    print(
        "   [flow] media: remapped script-derived media to Whisper scene timings "
        f"({len(source_texts)} -> {len(target_texts)})"
    )
    return media_plan


def _normalize_scene_indices(indices):
    return [int(index) + 1 for index in (indices or [])]


def _resolved_mixed_source(label, path, requested_source=''):
    """Return the source that actually produced a renderable asset."""
    label_key = str(label or '').strip().lower()
    requested = str(requested_source or '').strip()
    if any(term in label_key for term in ('parallel web', 'web image', 'web fallback', 'image fallback')):
        return 'Web Images'
    if 'stock' in label_key:
        return 'Stock Media'
    if 'youtube' in label_key:
        return 'YouTube Clips' if _is_video_path(path) else 'Web Images'
    if 'ai image' in label_key:
        return 'AI Images'
    if 'custom' in label_key:
        return 'Custom Images'
    if requested in {'YouTube Clips', 'Stock Media'} and _is_video_path(path):
        return requested
    return requested or ('Stock Media' if _is_video_path(path) else 'Web Images')


def _mixed_web_minimum_ratio(config):
    """Return the required web-image share for automatic Mixed Media.

    Explicit source weights remain an opt-in contract. Automatic mode is the
    product path used by the desktop Mixed Media control, and keeps web images
    as the majority even when the YouTube branch is faster than retrieval.
    """
    config = config if isinstance(config, dict) else {}
    raw = config.get('mixed_web_minimum_ratio')
    has_explicit_weights = isinstance(config.get('mixed_media_weights'), dict) and any(
        source in config.get('mixed_media_weights')
        for source in ('Web Images', 'YouTube Clips', 'Stock Media', 'AI Images')
    )
    policy = str(config.get('mixed_media_policy') or '').strip().lower()
    automatic_policy = policy in {
        'auto', 'automatic', 'smart', 'topic_aware', 'topic-aware'
    }
    if raw is None and has_explicit_weights:
        return 0.0
    if raw is None and automatic_policy:
        # Script-based allocation owns automatic jobs; old global still-image
        # floors must not replace verified footage with repeated images.
        return 0.0
    if raw is None:
        raw = os.environ.get('VIDZEO_MIXED_MIN_WEB_RATIO')
    if raw is None:
        return 0.0
    try:
        return max(0.0, min(0.95, float(raw)))
    except (TypeError, ValueError):
        return 0.0



def _is_web_image_media(path, label=''):
    """Count only actual still-image files as web-image media."""
    label_key = str(label or '').strip().lower()
    if any(term in label_key for term in ('emergency', 'placeholder', 'generated visual')):
        return False
    return bool(path) and not _is_video_path(path) and _resolved_mixed_source(label, path) == 'Web Images'


def _enforce_mixed_web_image_quota(
    media_plan,
    audio_plan,
    job_config,
    render_resolution,
    title,
    script,
):
    """Wait for web rescue and enforce the automatic Mixed Media web share.

    Web and YouTube retrieval may run in parallel, but source fallback must not
    silently turn web-assigned scenes into clips. Existing YouTube slots are
    temporarily opened and sent through the web resolver until the requested
    minimum is reached. A strict shortfall fails loudly instead of delivering a
    video whose actual mix contradicts the UI setting.
    """
    ratio = _mixed_web_minimum_ratio(job_config)
    paths = list((media_plan or {}).get('media_paths') or [])
    labels = list((media_plan or {}).get('source_labels') or [])
    if ratio <= 0.0 or not paths:
        return 0

    target = int(math.ceil(len(paths) * ratio))

    def web_count():
        return sum(
            1 for index, path in enumerate(paths)
            if _is_web_image_media(path, labels[index] if index < len(labels) else '')
        )

    initial_count = web_count()
    if initial_count >= target:
        media_plan.setdefault('metadata', {})['mixed_web_quota'] = {
            'minimum_ratio': ratio,
            'target_count': target,
            'final_count': initial_count,
            'replacements': 0,
            'waited_for_web': True,
        }
        return 0

    try:
        attempts = max(
            1,
            min(
                3,
                int(
                    (job_config or {}).get('mixed_web_quota_attempts')
                    or os.environ.get('VIDZEO_MIXED_WEB_QUOTA_ATTEMPTS', '2')
                    or 2
                ),
            ),
        )
    except (TypeError, ValueError):
        attempts = 2

    replacements = 0
    quota_reused = 0
    scene_texts = list((audio_plan or {}).get('scene_texts') or [])
    for attempt in range(1, attempts + 1):
        needed = target - web_count()
        if needed <= 0:
            break
        candidates = [
            index for index, path in enumerate(paths)
            if not _is_web_image_media(path, labels[index] if index < len(labels) else '')
        ]
        candidates.sort(
            key=lambda index: (
                0 if not paths[index] else 1,
                0 if 'youtube' in str(labels[index] if index < len(labels) else '').lower() else 1,
                index,
            )
        )
        selected = candidates[:needed]
        if not selected:
            break
        for index in selected:
            paths[index] = None
            if index < len(labels):
                labels[index] = ''
        media_plan['media_paths'] = paths
        media_plan['source_labels'] = labels
        print(
            f"   [mix] web quota: waiting for web images, attempt {attempt}/{attempts}, "
            f"requesting {len(selected)} replacement scene(s) "
            f"({web_count()}/{target} already web)"
        )
        _fill_unresolved_with_general_web_fallback(
            final_paths=paths,
            source_labels=labels,
            unresolved_indices=selected,
            scene_texts=scene_texts,
            render_resolution=render_resolution,
            title=title,
            script=script,
            config={
                **(job_config or {}),
                'web_output_namespace': f"mixed_web_quota_{int(time.time() * 1000)}_{attempt}",
                '_mixed_web_quota_attempt': attempt,
            },
            force_web=True,
        )
        replacements += sum(
            1 for index in selected
            if _is_web_image_media(paths[index], labels[index] if index < len(labels) else '')
        )

    final_count = web_count()
    if final_count < target:
        # The shared delivery clock may reserve the last retrieval seconds for
        # rendering. Use only already validated web stills as a bounded final
        # bridge; never borrow a YouTube frame or create a placeholder.
        web_pool = [
            path for index, path in enumerate(paths)
            if _is_web_image_media(path, labels[index] if index < len(labels) else '')
        ]
        try:
            max_web_quota_reuse = max(
                1,
                min(
                    2,
                    int(
                        (job_config or {}).get('mixed_web_quota_max_reuse')
                        or os.environ.get('VIDZEO_MIXED_WEB_QUOTA_MAX_REUSE', '2')
                        or 2
                    ),
                ),
            )
        except (TypeError, ValueError):
            max_web_quota_reuse = 2
        reuse_counts = Counter(_media_reuse_key(path) for path in web_pool if _media_reuse_key(path))
        remaining_indices = [
            index for index, path in enumerate(paths)
            if not _is_web_image_media(path, labels[index] if index < len(labels) else '')
        ]
        for scene_index in remaining_indices:
            if final_count >= target:
                break
            candidates = []
            for order, candidate in enumerate(web_pool):
                key = _media_reuse_key(candidate)
                family = _media_family_key(candidate)
                if key and reuse_counts[key] >= max_web_quota_reuse:
                    continue
                nearby = False
                for distance in range(1, 3):
                    for neighbor_index in (scene_index - distance, scene_index + distance):
                        if 0 <= neighbor_index < len(paths) and paths[neighbor_index]:
                            neighbor = paths[neighbor_index]
                            if (
                                key and _media_reuse_key(neighbor) == key
                            ) or (
                                family and _media_family_key(neighbor) == family
                            ):
                                nearby = True
                                break
                    if nearby:
                        break
                if not nearby:
                    candidates.append((reuse_counts.get(key, 0), order, candidate, key))
            if not candidates:
                continue
            _, _, selected_path, selected_key = min(candidates)
            paths[scene_index] = selected_path
            if scene_index < len(labels):
                labels[scene_index] = 'Web Images (quota reuse)'
            if selected_key:
                reuse_counts[selected_key] += 1
            quota_reused += 1
            final_count += 1
        media_plan['media_paths'] = paths
        media_plan['source_labels'] = labels
        if quota_reused:
            print(
                f"   [mix] web quota: reused {quota_reused} already validated "
                "web still(s) after the retrieval reserve was reached"
            )

    metadata = media_plan.setdefault('metadata', {})
    metadata['mixed_web_quota'] = {
        'minimum_ratio': ratio,
        'target_count': target,
        'final_count': final_count,
        'initial_count': initial_count,
        'replacements': replacements,
        'existing_web_reuse': quota_reused,
        'waited_for_web': True,
        'attempts': attempts,
    }
    if final_count < target:
        strict = str(
            (job_config or {}).get(
                'strict_mixed_web_minimum',
                os.environ.get('VIDZEO_STRICT_MIXED_WEB_MINIMUM', '1'),
            )
        ).strip().lower() in {'1', 'true', 'yes', 'on'}
        if strict:
            raise MediaContractError(
                'Mixed Media web-image minimum was not reached after web retrieval and rescue.',
                {
                    'minimum_ratio': ratio,
                    'target_web_images': target,
                    'resolved_web_images': final_count,
                    'scene_count': len(paths),
                    'fallback_policy': 'wait_for_web_before_youtube_rescue',
                },
            )
        print(
            f"   [mix] WARNING: web quota shortfall {final_count}/{target}; "
            "continuing because strict minimum is disabled"
        )
    else:
        print(
            f"   [mix] web quota satisfied: {final_count}/{len(paths)} "
            f"web images ({final_count / max(1, len(paths)):.0%})"
        )
    return replacements


def _mixed_media_source_accounting(metadata, grouped_indices, final_paths, source_labels, branch_failures=None):
    """Keep requested, resolved, and fallback state separate for each scene."""
    grouped_indices = grouped_indices or {}
    assigned_source_by_scene = {
        scene_idx: source_name
        for source_name, indices in grouped_indices.items()
        for scene_idx in (indices or [])
    }
    existing_decisions = list((metadata.get('media_plan') or {}).get('decisions') or [])
    decisions_by_scene = {
        int(row.get('scene_index')): dict(row)
        for row in existing_decisions
        if isinstance(row, dict) and row.get('scene_index') is not None
    }
    accounting = []
    resolved_counts = Counter()
    for scene_idx in range(max(len(final_paths or []), len(assigned_source_by_scene))):
        requested_source = assigned_source_by_scene.get(scene_idx, '')
        path = final_paths[scene_idx] if scene_idx < len(final_paths or []) else None
        label = source_labels[scene_idx] if scene_idx < len(source_labels or []) else ''
        resolved_source = _resolved_mixed_source(label, path, requested_source) if path else ''
        label_key = str(label or '').lower()
        if 'parallel web' in label_key:
            fallback_reason = 'parallel_web_rescue'
        elif 'image fallback' in label_key or 'web fallback' in label_key:
            fallback_reason = 'image_fallback'
        elif 'nearest' in label_key:
            fallback_reason = 'nearest_media_rescue'
        elif 'rotated' in label_key:
            fallback_reason = 'rotated_video_rescue'
        elif 'rescue' in label_key:
            fallback_reason = 'source_rescue'
        elif not path:
            fallback_reason = f"{requested_source.lower().replace(' ', '_')}_unresolved" if requested_source else 'unresolved'
        else:
            fallback_reason = ''
        if resolved_source:
            resolved_counts[resolved_source] += 1
        row = decisions_by_scene.get(scene_idx, {
            'scene_index': scene_idx,
            'requested_source': requested_source,
        })
        row['requested_source'] = requested_source or row.get('requested_source', '')
        row['resolved_source'] = resolved_source
        row['fallback_reason'] = fallback_reason
        row['final_source'] = resolved_source
        accounting.append(row)

    media_plan_metadata = metadata.setdefault('media_plan', {})
    media_plan_metadata['decisions'] = accounting
    media_plan_metadata['resolved_source_counts'] = dict(resolved_counts)
    if branch_failures:
        media_plan_metadata['branch_failures'] = dict(branch_failures)
    metadata['source_accounting'] = accounting
    metadata['resolved_source_counts'] = dict(resolved_counts)
    return accounting


def _raise_media_contract_error(
    message,
    *,
    requested_source,
    requested_weights=None,
    target_counts=None,
    resolved_counts=None,
    unresolved_scene_indices=None,
    source_failures=None,
    audit_path=None,
    fallback_policy=None,
):
    detail = {
        "requested_source": requested_source,
        "requested_weights": dict(requested_weights or {}),
        "target_counts": dict(target_counts or {}),
        "resolved_counts": dict(resolved_counts or {}),
        "unresolved_scene_indices": _normalize_scene_indices(unresolved_scene_indices),
        "source_failures": list(source_failures or []),
    }
    if audit_path:
        detail["audit_path"] = audit_path
    if fallback_policy:
        detail["fallback_policy"] = fallback_policy
    raise MediaContractError(message, detail)


def _validate_media_request_config(config):
    image_source = str(config.get('image_source') or '').strip()
    if image_source == 'Mixed':
        image_source = 'Mixed Media'
    if image_source != 'Mixed Media':
        return

    from services.mixed_media_planner import normalize_mixed_media_weights

    # Mixed Media is topic-routed. A weight map is optional and is retained
    # only for older API clients; the UI no longer sends one.
    normalize_mixed_media_weights(config.get('mixed_media_weights'), strict=False)


def _coerce_media_source_from_weights(config):
    updated = dict(config or {})
    raw_source = str(updated.get('image_source') or '').strip()
    media_mode = str(updated.get('media_mode') or '').strip().lower()
    scene_mode = str(updated.get('scene_media_mode') or updated.get('scene_selection_mode') or '').strip().lower()
    if scene_mode:
        updated['scene_media_mode'] = scene_mode
    if media_mode == 'automatic' or scene_mode == 'auto':
        # Automatic mode enables the unified resolver and its cross-source
        # fallback lanes. It must not silently relabel an explicitly chosen
        # YouTube job as Mixed Media: YouTube remains the primary source while
        # verified web candidates are allowed to rescue unresolved scenes.
        normalized_source = raw_source.lower()
        explicit_youtube = normalized_source.startswith('youtube') or normalized_source in {'youtube', 'yt clips'}
        explicit_custom = normalized_source in {'custom images', 'custom media', 'custom'} or bool(updated.get('custom_images') or updated.get('images'))
        media_mode_defaulted = bool(updated.get('_media_mode_defaulted'))
        explicit_other_source = normalized_source in {'web images', 'stock media', 'ai images'}
        if not explicit_youtube and not explicit_custom and not (media_mode_defaulted and explicit_other_source):
            updated['image_source'] = 'Mixed Media'
            raw_source = 'Mixed Media'
        updated.setdefault('cross_source_fallback', True)
    if raw_source == 'Mixed':
        updated['image_source'] = 'Mixed Media'
    raw_mw = updated.get('media_weights') or updated.get('mixed_media_weights')
    if isinstance(raw_mw, dict) and any(raw_mw.values()):
        key_map = {
            'web_images': 'Web Images',
            'web': 'Web Images',
            'web images': 'Web Images',
            'youtube_clips': 'YouTube Clips',
            'youtube': 'YouTube Clips',
            'youtube clips': 'YouTube Clips',
            'stock_media': 'Stock Media',
            'stock': 'Stock Media',
            'stock media': 'Stock Media',
            'ai_images': 'AI Images',
            'ai': 'AI Images',
            'ai images': 'AI Images',
        }
        mapped_weights = {}
        for k, v in raw_mw.items():
            canonical_k = key_map.get(str(k).strip().lower(), str(k))
            try:
                mapped_weights[canonical_k] = float(v)
            except (TypeError, ValueError):
                pass
        if mapped_weights:
            updated['mixed_media_weights'] = mapped_weights
            updated['image_source'] = 'Mixed Media'
            raw_source = 'Mixed Media'

    if str(updated.get('image_source') or '').strip() == 'Mixed Media':
        updated.setdefault('mixed_media_policy', 'automatic')
        # Default to one narration beat per visual scene; legacy grouped modes
        # are normalized to Every Beat by normalize_generation_config().
        if 'scene_mode' not in updated or not updated['scene_mode']:
            updated['scene_mode'] = 'Every Beat'
        updated['yt_allow_same_source_reuse'] = True
        # Direct clip downloads (yt_pool_first=False) download only the 3-5s clip segment in 1.5s
        # instead of downloading full 150MB videos sequentially.
        if 'yt_pool_first' not in updated:
            updated['yt_pool_first'] = False
        updated.setdefault('max_final_video_reuse_per_clip', 1)
        # Give the bounded YouTube lane enough alternatives to survive a
        # stale/blocked result while the aggregate worker wall remains the
        # outer safety guard.  The lane still runs only the requested quota.
        updated.setdefault('yt_download_candidate_limit', 6)
        updated.setdefault('yt_max_download_attempts_per_scene', 6)
        updated['yt_lenient_acceptance'] = True
    return updated




def _stock_rescue_allowed(config, title='', script='', scene_texts=None):
    """Keep stock rescue inside explicit/automatic stock-capable modes."""
    source = str((config or {}).get('image_source') or '').strip()
    if source in {'Stock Media', 'Real Media'}:
        return True
    if source not in {'Mixed Media', 'Mixed'}:
        return False
    # Explicit mixed-media weights are an opt-in contract: when the caller
    # deliberately excludes Stock Media (weight 0 or absent), no rescue pass
    # may resurrect it and burn branch budget on an unrequested source.
    raw_weights = (config or {}).get('mixed_media_weights')
    if isinstance(raw_weights, dict) and any(
        item in raw_weights for item in ('Web Images', 'YouTube Clips', 'Stock Media', 'AI Images')
    ):
        try:
            stock_weight = max(0.0, float(raw_weights.get('Stock Media', 0.0) or 0.0))
        except (TypeError, ValueError):
            stock_weight = 0.0
        if stock_weight <= 0.0:
            return False
    if (
        bool((config or {}).get('strict_retrieval_accuracy'))
        and bool(re.search(
            r"\b(?:top|best|greatest|worst)\s*\d+\b|\branking\b|\blisticle\b",
            str(title or '').lower(),
        ))
        and bool(
            (config or {}).get('pexels_api_key')
            or (config or {}).get('pixabay_api_key')
            or os.environ.get('PEXELS_API_KEY')
            or os.environ.get('PIXABAY_API_KEY')
        )
    ):
        return True
    from services.mixed_media_planner import classify_mixed_media_topic

    return classify_mixed_media_topic(
        title=title,
        script=script,
        scene_texts=scene_texts or [],
        category=(config or {}).get('category') or (config or {}).get('niche') or '',
    ) != 'serious'


def _verified_youtube_session_for_media():
    """Return only a redacted readiness fact for the current YouTube session."""
    try:
        from services.youtube_session import session_status
        status = session_status()
        return bool(
            isinstance(status, dict)
            and status.get("ready")
            and status.get("verified_authenticated") is True
            and not status.get("cookie_update_required")
        )
    except Exception:
        return False


def _apply_authenticated_youtube_mix(policy, config, session_verified=None):
    """Apply an explicitly requested authenticated-video mix target.

    A working cookie session increases retrieval capability; it does not decide
    the editorial footage percentage. The niche/director policy remains in
    charge unless an operator explicitly supplies an authenticated coverage
    target. Any prior boost is restored from its recorded baseline when that
    target or verified session is no longer active.
    """
    from services.mixed_media_planner import authenticated_youtube_mix

    resolved = dict(policy or {})
    weights = dict(resolved.get("weights") or {})
    config = config if isinstance(config, dict) else {}
    baseline = resolved.get("weights_before_authenticated_youtube")

    if session_verified is None:
        session_verified = _verified_youtube_session_for_media()

    image_source = str(config.get("image_source") or "").strip().casefold()
    explicit_weights = config.get("mixed_media_weights") or config.get("media_weights")
    canonical_sources = {"Web Images", "YouTube Clips", "Stock Media", "AI Images"}
    has_explicit_weights = isinstance(explicit_weights, dict) and any(
        str(key).strip() in canonical_sources
        or str(key).strip().casefold() in {"web", "web_images", "youtube", "youtube_clips", "stock", "stock_media", "ai", "ai_images"}
        for key in explicit_weights
    )
    has_explicit_target = any(
        key in config and config.get(key) not in (None, "")
        for key in ("youtube_accepted_coverage_target", "youtube_coverage_target")
    ) or bool(os.environ.get("VIDZEO_YOUTUBE_ACCEPTED_COVERAGE_TARGET"))
    authenticated_target = config.get("youtube_authenticated_coverage_target")
    if authenticated_target in (None, ""):
        authenticated_target = os.environ.get("VIDZEO_AUTHENTICATED_YOUTUBE_MIX_TARGET")
    has_authenticated_target = authenticated_target not in (None, "")

    if baseline and (
        not session_verified
        or has_explicit_weights
        or has_explicit_target
        or not has_authenticated_target
        or image_source not in {"mixed media", "mixed"}
    ):
        weights = dict(baseline)
        resolved.pop("weights_before_authenticated_youtube", None)
        resolved.pop("youtube_coverage_mode", None)
    resolved["weights"] = weights

    if image_source not in {"mixed media", "mixed"} or has_explicit_weights or has_explicit_target:
        resolved.pop("youtube_session_verified", None)
        return resolved

    if not session_verified:
        resolved.pop("youtube_session_verified", None)
        return resolved

    if not has_authenticated_target:
        # Cookie availability is transport capability only. Keep the
        # script-specific ratio instead of silently promoting every subject to
        # a majority-video edit.
        resolved.pop("youtube_session_verified", None)
        resolved.pop("youtube_coverage_mode", None)
        return resolved

    resolved["youtube_session_verified"] = True
    if not baseline:
        baseline = dict(weights)
        resolved["weights_before_authenticated_youtube"] = baseline
    resolved["weights"] = authenticated_youtube_mix(weights, authenticated_target)
    resolved["youtube_coverage_mode"] = "verified_cookie_video_majority"
    return resolved


def _resolve_mixed_media_niche_policy(config, title, script, scene_texts):
    """Attach one auditable script-niche policy before plan/query branches."""
    if not isinstance(config, dict):
        return {}
    existing = config.get('_niche_media_policy')
    if isinstance(existing, dict) and existing.get('weights'):
        # Job configs can be reused by the desktop preview and final render.
        # Recompute when their script context changes so the LLM/deterministic
        # classifier always owns the current request.
        context = "\n".join(
            [str(config.get('category') or config.get('niche') or ''), str(title or ''), str(script or '')]
            + [str(scene or '') for scene in (scene_texts or [])]
        )
        expected_hash = hashlib.sha256(context.encode('utf-8', errors='ignore')).hexdigest()[:24]
        if existing.get('context_hash') == expected_hash:
            retrieval_policy = existing.get('retrieval_policy')
            if not isinstance(retrieval_policy, dict):
                # Policies persisted by an older desktop session predate the
                # retrieval knobs. Upgrade them in place so a cached job does
                # not quietly lose its niche-specific candidate budget.
                from services.mixed_media_planner import _NICHE_RETRIEVAL_POLICIES
                retrieval_policy = dict(
                    _NICHE_RETRIEVAL_POLICIES.get(
                        str(existing.get('niche') or 'general').strip().lower(),
                        _NICHE_RETRIEVAL_POLICIES['general'],
                    )
                )
                existing['retrieval_policy'] = retrieval_policy
            if isinstance(retrieval_policy, dict):
                for key, value in retrieval_policy.items():
                    config.setdefault(key, value)
            existing = _apply_authenticated_youtube_mix(existing, config)
            config['_niche_media_policy'] = existing
            return existing
        print("   [mix] refreshing stale niche policy for the current script context")
    try:
        from services.mixed_media_planner import resolve_media_policy
        key = (
            config.get('openrouter_api_key')
            or os.environ.get('OPENROUTER_API_KEY')
            or os.environ.get('VIDZEO_OPENROUTER_API_KEY')
            or ''
        )
        policy = resolve_media_policy(
            title=title,
            script=script,
            scene_texts=list(scene_texts or []),
            category=config.get('category') or config.get('niche') or '',
            openrouter_api_key=str(key).strip(),
            llm_model=config.get('llm_model') or os.environ.get('VIDZEO_LLM_MODEL') or '',
            llm_analysis=config.get('_llm_topic_analysis') if isinstance(config.get('_llm_topic_analysis'), dict) else None,
        )
    except Exception as exc:
        print(f"   [mix] niche policy fallback warning: {exc}")
        from services.mixed_media_planner import (
            _NICHE_RETRIEVAL_POLICIES,
            automatic_mixed_media_weights,
            classify_mixed_media_topic,
        )
        niche = classify_mixed_media_topic(title, script, list(scene_texts or []), config.get('category') or config.get('niche') or '')
        policy = {
            'version': 'niche-policy-v2',
            'niche': niche,
            'heuristic_niche': niche,
            'weights': automatic_mixed_media_weights(title, script, list(scene_texts or []), config.get('category') or config.get('niche') or ''),
            'gta_vi': bool(re.search(r'\b(?:gta\s*(?:vi|6)|grand theft auto\s*(?:vi|6))\b', f'{title} {script}', re.I)),
            'llm_used': False,
            'llm_supported': False,
            # Keep the bounded retrieval/variety knobs available even when
            # the optional niche-analysis call itself fails. Without this,
            # a transient model outage silently reverted sparse niches to the
            # generic candidate budget.
            'retrieval_policy': dict(
                _NICHE_RETRIEVAL_POLICIES.get(
                    niche,
                    _NICHE_RETRIEVAL_POLICIES['general'],
                )
            ),
        }
    policy = _apply_authenticated_youtube_mix(policy, config)
    config['_niche_media_policy'] = policy
    niche_val = str(policy.get('niche') or '').strip().lower()
    if niche_val:
        config['script_niche'] = niche_val
    # Apply bounded niche retrieval knobs once per job. Explicit operator
    # values still win; these defaults only tune recall/variety for sparse
    # lanes such as gaming and keep ordinary topics at a calmer cadence.
    retrieval_policy = policy.get('retrieval_policy') if isinstance(policy, dict) else None
    if isinstance(retrieval_policy, dict):
        for key, value in retrieval_policy.items():
            config.setdefault(key, value)
    weights = policy.get('weights') or {}
    print(
        f"   [mix] script niche policy: {policy.get('niche') or 'general'} "
        f"(LLM={'yes' if policy.get('llm_supported') else 'fallback'}, "
        f"web={float(weights.get('Web Images') or 0):.0%}, "
        f"yt={float(weights.get('YouTube Clips') or 0):.0%}, "
        f"stock={float(weights.get('Stock Media') or 0):.0%}"
        + (", verified YouTube session" if policy.get('youtube_coverage_mode') == 'verified_cookie_video_majority' else '')
        + (", GTA VI exact-title media; prior-title clips only for an explicit scene comparison" if policy.get('gta_vi') else '')
        + ")"
    )
    return policy


def _count_script_words(script: str) -> int:
    return len(re.findall(r"\b[\w']+\b", script or ""))


def _normalize_plan_minutes(value):
    try:
        minutes = float(value)
    except (TypeError, ValueError):
        return None
    return minutes if minutes > 0 else None


def _derive_script_word_limit(max_video_minutes):
    minutes = _normalize_plan_minutes(max_video_minutes)
    if minutes is None:
        return None
    return max(1, int(minutes * SCRIPT_WORDS_PER_MINUTE))


def _parse_duration_to_seconds(value) -> float:
    if value is None:
        return 0.0
    if isinstance(value, (int, float)):
        return max(float(value), 0.0)

    text = str(value).strip().lower()
    if not text:
        return 0.0

    match = re.match(r"^\s*(\d+(?:\.\d+)?)\s*(second|seconds|minute|minutes|hour|hours)\s*$", text)
    if not match:
        return 0.0

    amount = float(match.group(1))
    unit = match.group(2)
    if unit.startswith('second'):
        return amount
    if unit.startswith('minute'):
        return amount * 60.0
    if unit.startswith('hour'):
        return amount * 3600.0
    return 0.0


def _format_duration_limit(minutes) -> str:
    normalized = _normalize_plan_minutes(minutes)
    if normalized is None:
        return "your plan limit"
    if normalized >= 60 and math.isclose(normalized % 60, 0.0, abs_tol=1e-6):
        hours = normalized / 60.0
        return "1 hour" if math.isclose(hours, 1.0, abs_tol=1e-6) else f"{int(hours)} hours"
    if math.isclose(normalized, round(normalized), abs_tol=1e-6):
        whole = int(round(normalized))
        return "1 minute" if whole == 1 else f"{whole} minutes"
    return f"{normalized:g} minutes"


def _format_script_word_limit(word_limit) -> str:
    try:
        words = int(word_limit)
    except (TypeError, ValueError):
        return "your plan word limit"
    return f"{words:,} words"


def _get_plan_constraints(auth_state=None, config=None):
    source = {}
    if isinstance(config, dict) and isinstance(config.get('plan_constraints'), dict):
        source = dict(config.get('plan_constraints') or {})
    if auth_state:
        source.update({
            "plan_key": auth_state.get("plan_key"),
            "plan_name": auth_state.get("plan_name"),
            "max_video_minutes": auth_state.get("max_video_minutes"),
            "max_script_words": auth_state.get("max_script_words"),
        })

    max_video_minutes = _normalize_plan_minutes(source.get("max_video_minutes"))
    max_script_words = source.get("max_script_words")
    try:
        max_script_words = int(max_script_words) if max_script_words is not None else None
    except (TypeError, ValueError):
        max_script_words = None
    if max_script_words is None and max_video_minutes is not None:
        max_script_words = _derive_script_word_limit(max_video_minutes)

    if max_video_minutes is None and max_script_words is None:
        return None

    return {
        "plan_key": source.get("plan_key"),
        "plan_name": source.get("plan_name") or "your active plan",
        "max_video_minutes": max_video_minutes,
        "max_script_words": max_script_words,
    }


def _attach_plan_constraints(config, auth_state):
    updated = dict(config or {})
    constraints = _get_plan_constraints(auth_state=auth_state)
    if constraints:
        updated["plan_constraints"] = constraints
        if constraints.get('max_video_minutes'):
            updated['maximum_duration_seconds'] = constraints['max_video_minutes'] * 60
            updated['minimum_duration_seconds'] = min(float(updated.get('minimum_duration_seconds') or 0),
                max(0, updated['maximum_duration_seconds'] - .5))
    if auth_state:
        updated["auth_user_id"] = auth_state.get("user_id") or auth_state.get("auth_user_id")
        updated["plan_key"] = auth_state.get("plan_key")
    return updated


def _enforce_generation_plan_limits(config, auth_state=None):
    updated = dict(config or {})
    constraints = _get_plan_constraints(auth_state=auth_state, config=updated)
    if not constraints:
        return updated

    updated["plan_constraints"] = constraints
    max_seconds = (constraints["max_video_minutes"] or 0) * 60.0
    plan_name = constraints["plan_name"]
    duration_label = _format_duration_limit(constraints["max_video_minutes"])
    word_limit_label = _format_script_word_limit(constraints["max_script_words"])

    # 1. Monthly Export Quota Enforcement
    user_id = (auth_state or {}).get("user_id") or (auth_state or {}).get("auth_user_id") or updated.get("auth_user_id")
    plan_key = constraints.get("plan_key") or (auth_state or {}).get("plan_key") or updated.get("plan_key")
    usage = {
        'is_unlimited': (auth_state or {}).get('is_unlimited_exports', get_plan_export_limit(plan_key) is None),
        'limit': (auth_state or {}).get('monthly_export_limit', get_plan_export_limit(plan_key)),
        'used': (auth_state or {}).get('monthly_exports_used', 0),
    }
    if not usage.get("is_unlimited"):
        limit = usage.get("limit")
        used = usage.get("used", 0)
        if limit is not None and used >= limit:
            raise ValueError(
                f"PLAN_LIMIT_REACHED: You have reached your monthly limit of {limit} exports on the {plan_name}. "
                "View upgrade options to continue, or wait for the next monthly reset."
            )

    # 2. Video Duration and Script Limits
    script = (updated.get("script") or "").strip()
    input_mode = str(updated.get("input_mode") or "").strip().lower()
    if not input_mode:
        if script:
            input_mode = "script"
        elif updated.get("title"):
            input_mode = "title"

    requested_duration_seconds = _parse_duration_to_seconds(updated.get("duration"))
    if input_mode == "title" and requested_duration_seconds and max_seconds and requested_duration_seconds > max_seconds:
        raise ValueError(
            f"PLAN_LIMIT_REACHED: {plan_name} allows exports up to {duration_label} per video. "
            f"Choose a shorter duration or upgrade to Creator ($19) or Pro ($49) for longer videos."
        )

    if script:
        script_words = _count_script_words(script)
        estimated_seconds = _estimate_script_duration_seconds(script)
        if constraints["max_script_words"] and script_words > constraints["max_script_words"]:
            raise ValueError(
                f"PLAN_LIMIT_REACHED: {plan_name} supports scripts up to about {word_limit_label} ({duration_label} per export). "
                f"Your current script is {script_words:,} words. Upgrade to Pro ($49) for up to 30+ minute exports."
            )
        if max_seconds and estimated_seconds > max_seconds:
            estimated_minutes = max(1, math.ceil(estimated_seconds / 60.0))
            raise ValueError(
                f"PLAN_LIMIT_REACHED: {plan_name} allows exports up to {duration_label} per video. "
                f"Your script currently estimates to about {estimated_minutes} minutes. Upgrade to Creator ($19) or Pro ($49) to export."
            )

    return updated


