def _normalize_flask_result(result):
    """Convert a Flask view return value into (payload_dict, status_code)."""
    status_code = 200
    response_obj = result

    if isinstance(result, tuple):
        response_obj = result[0]
        if len(result) > 1 and isinstance(result[1], int):
            status_code = result[1]

    payload = None
    if hasattr(response_obj, 'get_json'):
        payload = response_obj.get_json(silent=True)

    return payload or {}, status_code


def _ensure_script_for_queue(config: dict, update_progress=None) -> dict:
    """Queue jobs must include the final narration script."""
    config = normalize_generation_config(config)
    script = (config.get('script') or '').strip()
    if len(script) >= 10:
        return _enforce_generation_plan_limits(config)

    raise ValueError("Paste a finished narration script before creating a video.")


def _resume_checkpointed_remotion_render(config, update_progress, cancellation=None):
    return _run_job_scoped(
        lambda context: _resume_checkpointed_remotion_render_impl(config, update_progress, context),
        config, cancellation,
    )


def _resume_checkpointed_remotion_render_impl(config, update_progress, cancellation=None):
    """Resume a memory-paused job from its validated edit plan and local media.

    A retry must not repeat narration, LLM planning, or media retrieval after
    those stages have already produced durable checkpoints. Return ``None``
    only when the package is not a complete render-ready checkpoint; recognized
    low-memory checkpoints that remain short on RAM raise the normal retryable
    renderer error and stay paused in the queue.
    """
    config = dict(config or {})
    package_raw = config.get('_output_package_dir') or config.get('output_package_dir')
    if not package_raw:
        return None
    package_dir = Path(str(package_raw)).expanduser().resolve()
    checkpoint_dir = package_dir / 'checkpoints'

    def _read_json(path):
        try:
            return json.loads(Path(path).read_text(encoding='utf-8'))
        except (OSError, ValueError, TypeError):
            return {}

    state = _read_json(checkpoint_dir / 'state.json')
    failure = _read_json(checkpoint_dir / 'render_failure.json')
    failure_kind = str(failure.get('kind') or '').strip().lower()
    retry_checkpoint = (
        failure_kind in {'low_memory', 'edit_plan_invalid', 'render_failed'}
        and bool(failure.get('retryable'))
        and not bool(failure.get('resolved'))
        and (checkpoint_dir / 'pre_render.json').is_file()
    )
    completed_checkpoint = _read_json(checkpoint_dir / 'render_complete.json')
    explicit_rerender = (
        _enabled(config.get('rerender_from_checkpoint'))
        and str(state.get('stage') or '').lower() == 'complete'
        and str(state.get('status') or '').lower() == 'complete'
        and completed_checkpoint.get('backend') == 'remotion'
    )
    interrupted_render_checkpoint = (
        str(state.get('stage') or '').lower() in {'ready_for_render', 'resuming_render'}
        and str(state.get('status') or '').lower() == 'saved'
        and (checkpoint_dir / 'pre_render.json').is_file()
    )
    pending_validation_checkpoint = (
        str(state.get('stage') or '').lower() == 'render_pending_validation'
        and (checkpoint_dir / 'render_pending_validation.json').is_file()
    )
    if not retry_checkpoint and not explicit_rerender and not interrupted_render_checkpoint and not pending_validation_checkpoint:
        return None

    pre_render = _read_json(checkpoint_dir / 'pre_render.json')
    from services.media_asset_policy import excess_media_reuse_indices
    if excess_media_reuse_indices(_read_json(checkpoint_dir / 'media_plan.json')):
        print('   [retry] saved media exceeds physical reuse limits; repairing affected scenes before rendering', flush=True)
        return None
    if str(pre_render.get('backend') or '').strip().lower() not in {'remotion', 'react'}:
        return None
    candidate_paths = [
        pre_render.get('edit_plan_path'),
        package_dir / 'editorial' / 'remotion_edit_plan.json',
        package_dir / f"{sanitize_output_name(config.get('output_name') or config.get('name') or 'Video')}_remotion_edit_plan.json",
    ]
    plan_path = next(
        (Path(str(candidate)).expanduser().resolve() for candidate in candidate_paths if candidate and Path(str(candidate)).expanduser().is_file()),
        None,
    )
    audio_plan = _read_json(checkpoint_dir / 'audio_plan.json')
    if plan_path is None or not audio_plan:
        return None
    retained_master = _retained_remotion_master(package_dir, plan_path)
    manifest = _read_json(plan_path)
    scenes = list(manifest.get('scenes') or []) if isinstance(manifest, Mapping) else []
    scene_texts = list(audio_plan.get('scene_texts') or [])
    scene_durations = list(audio_plan.get('scene_durations') or [])
    if not scenes or len(scenes) != len(scene_texts) or len(scenes) != len(scene_durations):
        print('   [retry] saved plan does not preserve one narration beat per scene; rebuilding from script')
        return None

    def _normalized_words(value):
        return re.findall(r"[\wÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢']+", str(value or '').casefold())

    requested_script = str(config.get('script') or config.get('source_script') or '').strip()
    if requested_script and _normalized_words(requested_script) != _normalized_words(' '.join(scene_texts)):
        print('   [retry] narration input changed; saved render is not reusable')
        return None

    fps = max(1, int(manifest.get('fps') or 30))
    cursor = 0.0
    for index, (scene, scene_text, planned_duration) in enumerate(zip(scenes, scene_texts, scene_durations)):
        if not isinstance(scene, Mapping):
            return None
        if _normalized_words(scene.get('narration')) != _normalized_words(scene_text):
            print(f'   [retry] saved narration no longer matches beat {index + 1}; rebuilding from script')
            return None
        try:
            start = float(scene.get('start') or 0.0)
            duration = float(scene.get('duration') or 0.0)
            planned_duration = float(planned_duration or 0.0)
        except (TypeError, ValueError):
            return None
        frame_tolerance = max(0.025, 1.01 / fps)
        if duration <= 0 or abs(start - cursor) > frame_tolerance or abs(duration - planned_duration) > frame_tolerance:
            print(f'   [retry] saved scene {index + 1} timing is not aligned to its Whisper beat; rebuilding from script')
            return None
        cursor += planned_duration

    expected_duration = float(audio_plan.get('duration') or 0.0)
    if expected_duration <= 0 or abs(cursor - expected_duration) > max(0.05, 1.01 / fps):
        print('   [retry] saved beat timeline does not reach the narration endpoint; rebuilding from script')
        return None

    # Recheck local inputs before skipping retrieval. A deleted cache file or
    # voiceover makes this package non-resumable, so the full pipeline repairs
    # it instead of producing an incomplete export.
    local_inputs = []
    for path_value in list(pre_render.get('media_paths') or []):
        if path_value:
            local_inputs.append(path_value)
    voiceover = ((manifest.get('audio') or {}).get('voiceover') or {}) if isinstance(manifest.get('audio'), Mapping) else {}
    audio_path = str(
        voiceover.get('src') or voiceover.get('path') or pre_render.get('audio_path') or audio_plan.get('audio_path') or ''
    ).strip()
    if not audio_path:
        return None
    local_inputs.append(audio_path)
    # Caption phrases and their timing are embedded in the saved Remotion
    # manifest; retry no longer depends on an SRT or FFmpeg subtitle pass.
    for row in list(((manifest.get('audio') or {}).get('effects') or [])) if isinstance(manifest.get('audio'), Mapping) else []:
        if isinstance(row, Mapping) and (row.get('src') or row.get('path')):
            local_inputs.append(row.get('src') or row.get('path'))
    music = ((manifest.get('audio') or {}).get('music') or {}) if isinstance(manifest.get('audio'), Mapping) else {}
    if isinstance(music, Mapping) and (music.get('src') or music.get('path')):
        local_inputs.append(music.get('src') or music.get('path'))

    # Saved render checkpoints bypass retrieval's snapshot boundary. Normalize
    # their video inputs here too: recovered YouTube clips can be AV1 MP4s that
    # pass ffprobe but fail Remotion's frame compositor during review.
    saved_media_paths = list(pre_render.get('media_paths') or [])
    prior_normalization = [
        row for row in (pre_render.get('render_input_normalization') or [])
        if isinstance(row, Mapping)
    ]
    prior_by_render = {
        os.path.normcase(os.path.abspath(str(row.get('render_path') or ''))): row
        for row in prior_normalization
        if row.get('render_path')
    }
    video_indices = [
        index for index, value in enumerate(saved_media_paths)
        if value and _is_video_path(str(value))
    ]
    if video_indices:
        first_video = Path(str(saved_media_paths[video_indices[0]])).expanduser().resolve()
        run_root = (
            first_video.parents[2]
            if len(first_video.parents) > 2 and first_video.parents[1].name.casefold() == 'render_media'
            else package_dir / 'render'
        )
        source_videos = [str(saved_media_paths[index]) for index in video_indices]
        compatible_videos = _snapshot_media_for_render(
            source_videos,
            namespace='remotion_resume',
            root_dir=run_root,
            copy_compatible=False,
        )
        path_map = {
            os.path.normcase(os.path.abspath(source)): str(target)
            for source, target in zip(source_videos, compatible_videos)
            if target
        }
        if path_map:
            def _file_sha256(path_value):
                digest = hashlib.sha256()
                with open(path_value, 'rb') as handle:
                    for block in iter(lambda: handle.read(1024 * 1024), b''):
                        digest.update(block)
                return digest.hexdigest()

            def _video_codec(path_value):
                from services.media_integrity import resolve_ffmpeg_pair
                _ffmpeg, ffprobe = resolve_ffmpeg_pair(BASE_DIR)
                probed = subprocess.run(
                    [ffprobe, '-v', 'error', '-select_streams', 'v:0', '-show_entries', 'stream=codec_name', '-of', 'json', str(path_value)],
                    capture_output=True, text=True, timeout=15, check=False,
                )
                if probed.returncode != 0:
                    return ''
                streams = (json.loads(probed.stdout or '{}').get('streams') or [])
                return str((streams[0] or {}).get('codec_name') or '').casefold() if streams else ''

            original_by_target = {}
            normalization_rows = []
            for source, target in zip(source_videos, compatible_videos):
                if not target:
                    continue
                source_key = os.path.normcase(os.path.abspath(source))
                target_key = os.path.normcase(os.path.abspath(str(target)))
                prior = prior_by_render.get(source_key) or {}
                original_path = str(prior.get('original_path') or source)
                original_by_target[target_key] = original_path
                try:
                    source_sha = _file_sha256(original_path)
                    render_sha = _file_sha256(str(target))
                except OSError:
                    source_sha = ''
                    render_sha = ''
                source_codec = str(prior.get('source_codec') or _video_codec(original_path))
                render_codec = _video_codec(str(target))
                normalization_rows.append({
                    'schema_version': 'render_media_normalization.v1',
                    'kind': 'codec_transcode',
                    'tool': 'vidzeo_media_snapshot_v1',
                    'original_path': original_path,
                    'render_path': str(target),
                    'source_sha256': source_sha,
                    'render_sha256': render_sha,
                    'source_codec': source_codec,
                    'render_codec': render_codec,
                    'normalized': os.path.normcase(os.path.abspath(original_path)) != target_key,
                })

            def _replace_saved_video_paths(value):
                if isinstance(value, str):
                    return path_map.get(os.path.normcase(os.path.abspath(value)), value)
                if isinstance(value, list):
                    return [_replace_saved_video_paths(item) for item in value]
                if isinstance(value, dict):
                    # render_transform is a provenance record, not a render
                    # input: its source_path must keep pointing at the
                    # verified original. Rewriting it to the transcode
                    # breaks the verification hash chain on resume
                    # (verified_shot_changed_after_review).
                    return {key: (item if key == 'render_transform' else _replace_saved_video_paths(item)) for key, item in value.items()}
                return value

            manifest = _replace_saved_video_paths(manifest)
            saved_media_paths = _replace_saved_video_paths(saved_media_paths)
            for scene in manifest.get('scenes') or []:
                if not isinstance(scene, dict):
                    continue
                media = scene.get('media') if isinstance(scene.get('media'), Mapping) else {}
                for shot in media.get('shots') or []:
                    if not isinstance(shot, dict):
                        continue
                    render_path = str(shot.get('path') or shot.get('asset_path') or '')
                    target_key = os.path.normcase(os.path.abspath(render_path)) if render_path else ''
                    original_path = original_by_target.get(target_key)
                    if not original_path or not os.path.isfile(original_path) or not os.path.isfile(render_path):
                        continue
                    decision = shot.get('visual_decision') if isinstance(shot.get('visual_decision'), Mapping) else {}
                    verified_source_sha = str(
                        decision.get('verified_asset_sha256')
                        or shot.get('verified_asset_sha256')
                        or shot.get('asset_sha256')
                        or ''
                    )
                    try:
                        source_sha = _file_sha256(original_path)
                        render_sha = _file_sha256(render_path)
                    except OSError:
                        continue
                    if verified_source_sha and verified_source_sha == source_sha and render_sha:
                        shot['render_transform'] = {
                            'schema_version': 'render_media_normalization.v1',
                            'kind': 'codec_transcode',
                            'tool': 'vidzeo_media_snapshot_v1',
                            'source_path': original_path,
                            'source_sha256': source_sha,
                            'render_path': render_path,
                            'render_sha256': render_sha,
                            'source_codec': _video_codec(original_path),
                            'render_codec': _video_codec(render_path),
                        }
            pre_render['media_paths'] = saved_media_paths
            pre_render['render_input_normalization'] = normalization_rows
            manifest['render_input_normalization'] = normalization_rows
            local_inputs = [
                path_map.get(os.path.normcase(os.path.abspath(str(value))), value)
                if isinstance(value, str) else value
                for value in local_inputs
            ]
            checkpoint_tmp = checkpoint_dir / 'pre_render.normalized.tmp.json'
            checkpoint_tmp.write_text(json.dumps(pre_render, ensure_ascii=False, indent=2, default=str), encoding='utf-8')
            os.replace(checkpoint_tmp, checkpoint_dir / 'pre_render.json')
            print(
                f"   [retry] normalized {sum(row['normalized'] for row in normalization_rows)} saved video input(s) for Remotion",
                flush=True,
            )

    for asset_path in dict.fromkeys(str(value).strip() for value in local_inputs if value):
        local_path = _local_media_path_for_render(asset_path)
        if not _media_path_exists_for_render(local_path):
            print(f'   [retry] saved render input is missing or unreadable: {asset_path}')
            return None

    try:
        if failure_kind == 'edit_plan_invalid':
            repairs = _repair_unsupported_route_map_scenes(manifest)
            repairs_charts = _repair_unsupported_chart_scenes(manifest)
            repairs_adj = _repair_repeated_adjacent_treatments(manifest)
            local_repeat_repairs = _repair_verified_local_perceptual_repeats(manifest)
            media_plan = _read_json(package_dir / 'media' / 'media_plan.json')
            media_metadata = media_plan.get('metadata') if isinstance(media_plan.get('metadata'), Mapping) else {}
            resolution_rows = list(media_metadata.get('media_resolution_v2') or [])
            requirement_rows = list(media_metadata.get('visual_requirements') or [])
            repetition_audit = (manifest.get('media_shot_plan') or {}).get('perceptual_repetition_audit') or {}
            unresolved_repeats = list(repetition_audit.get('unresolved_repeats') or [])
            repeat_repair = {
                'status': 'repaired_from_verified_local_alternate' if local_repeat_repairs else 'not_needed',
                'scene_indices': list(local_repeat_repairs),
                'candidate_source': 'already_verified_local_alternate' if local_repeat_repairs else '',
            }
            if unresolved_repeats and resolution_rows:
                repair_findings = []
                for row in unresolved_repeats:
                    try:
                        scene_index = int(row.get('scene_index'))
                    except (TypeError, ValueError, AttributeError):
                        continue
                    if not 0 <= scene_index < len(scenes):
                        continue
                    matching = []
                    try:
                        matching = [int(row.get('matches_scene_index'))]
                    except (TypeError, ValueError):
                        pass
                    repair_findings.append({
                        'scene_index': scene_index,
                        'repair_kind': 'media',
                        'fallback_reason': 'repeated_pixels',
                        'matching_scene_indices': matching,
                        'issues': ['The saved shot repeats verified film pixels. Try an unused alternative already verified for this exact scene before fresh retrieval.'],
                    })
                if repair_findings:
                    repair_started = time.monotonic()
                    repair_config = {
                        **config,
                        '_media_resolution_rows': resolution_rows,
                        '_visual_requirement_rows': requirement_rows,
                        '_creative_media_findings': repair_findings,
                    }
                    try:
                        repaired = _repair_creative_media(
                            manifest,
                            repair_findings,
                            min(45.0, max(8.0, float(config.get('media_repair_budget_seconds') or 45.0))),
                            repair_config,
                            cancellation,
                        )
                    except Exception as repair_error:
                        repaired = False
                        repeat_repair['error'] = f'{type(repair_error).__name__}: {str(repair_error)[:500]}'
                    repeat_repair = {
                        **repeat_repair,
                        'status': 'repaired' if repaired else 'unresolved',
                        'scene_indices': [row['scene_index'] for row in repair_findings],
                        'elapsed_seconds': round(time.monotonic() - repair_started, 3),
                        'candidate_source': 'saved_media_resolution_alternates_then_bounded_retrieval',
                    }
            # Rebuild derived component mappings and timeline tracks from the
            # immutable narration before retry validation. This repairs
            # event-prefaced score comparisons and avoids stale generic cards.
            from services.editorial_director.production_contract import compile_production_timeline
            compile_production_timeline(manifest)
            manifest['checkpoint_repair_audit'] = {
                **dict(manifest.get('checkpoint_repair_audit') or {}),
                'saved_plan_repair': {
                    'map_scenes_repaired': repairs,
                    'chart_scenes_repaired': repairs_charts,
                    'adjacent_treatments_repaired': repairs_adj,
                    'repeated_media': repeat_repair,
                    'production_audit': (manifest.get('production_audit') or {}).get('status'),
                    'production_errors': (manifest.get('production_audit') or {}).get('errors') or [],
                },
            }
        # A ready render checkpoint already contains accepted direction. Do not
        # call the writer again and mutate it underneath a decoder/render retry.
        # Local repairs also cover interrupted older retries that persisted a
        # repeated treatment before their validation failed.
        resume_layout_repairs = _repair_repeated_adjacent_treatments(manifest)
        if resume_layout_repairs:
            from services.editorial_director.production_contract import compile_production_timeline
            compile_production_timeline(manifest)
        validation = _validate_remotion_edit_plan(manifest, len(scenes))
    except RemotionEditPlanError:
        raise
    except Exception as exc:
        print(f'   [retry] saved edit plan validation failed; rebuilding from script: {exc}')
        return None
    if not isinstance(validation, Mapping) or validation.get('status') != 'pass':
        raise RemotionEditPlanError(
            f"Saved Remotion edit plan still needs correction: {(validation or {}).get('errors')}"
        )

    validated_plan_tmp = plan_path.with_suffix('.validated.tmp.json')
    validated_plan_tmp.write_text(json.dumps(manifest, ensure_ascii=False, indent=2, default=str), encoding='utf-8')
    os.replace(validated_plan_tmp, plan_path)

    if cancellation is not None:
        cancellation.raise_if_cancelled()
    update_progress(72, 'Resuming saved Remotion edit; narration and media are ready...')
    render_dir = package_dir / 'render'
    render_dir.mkdir(parents=True, exist_ok=True)
    output_name = sanitize_output_name(
        config.get('output_name') or config.get('name') or config.get('content_title') or 'Video'
    )
    director = manifest.get('director') if isinstance(manifest.get('director'), Mapping) else {}
    if str(director.get('status') or '').lower() in {'deterministic_fallback', 'local_fallback'} and not output_name.endswith('_local_director_fallback'):
        output_name = f'{output_name}_local_director_fallback'
    output_path = package_dir / f'{output_name}.mp4'
    render_output_path = render_dir / f'{output_name}_remotion.mp4'

    render_config = dict(manifest.get('config') or {}) if isinstance(manifest.get('config'), Mapping) else {}
    for key in (
        'quality', 'semantic_render_quality', 'semantic_render_scale',
        'semantic_render_concurrency', 'semantic_render_x264_preset',
        'semantic_render_crf', 'semantic_render_threads_per_job',
        'semantic_render_timeout_seconds', 'semantic_render_budget_seconds',
        'fast_mode', 'semantic_fast_render', 'openrouter_api_key',
        'creative_review_budget_seconds', 'creative_revision_rounds',
        'strict_creative_review', 'semantic_preview_gate',
    ):
        if config.get(key) not in (None, ''):
            render_config[key] = config[key]
    render_config.update({
        'render_backend': 'remotion',
        'semantic_render_required': True,
        'job_type': str(config.get('type') or 'long'),
        '_creative_media_repair': lambda film, findings, budget: _repair_creative_media(
            film, findings, budget, config, cancellation
        ),
    })
    if render_config.get('semantic_fast_render') in (None, ''):
        render_config['semantic_fast_render'] = str(
            render_config.get('fast_mode', 'true')
        ).strip().lower() in {'1', 'true', 'yes', 'on'}

    memory = _memory_status_snapshot()
    _write_generation_checkpoint(
        config,
        'pre_render.json',
        {
            **pre_render,
            'backend': 'remotion',
            'edit_plan_path': str(plan_path),
            'media_paths': list(pre_render.get('media_paths') or []),
            'audio_path': audio_path,
            'duration': expected_duration,
            'retry_attempt': int(config.get('_queue_attempt') or 1),
            'memory': memory,
        },
        stage='resuming_render',
    )
    _set_video_package_status(config, 'rendering', retry_attempt=int(config.get('_queue_attempt') or 1))

    from services.native_render_policy import render_semantic_documentary

    def _render_progress(fraction, message):
        if cancellation is not None:
            cancellation.raise_if_cancelled()
        try:
            fraction = max(0.0, min(1.0, float(fraction)))
        except (TypeError, ValueError):
            fraction = 0.0
        update_progress(73 + int(round(fraction * 25)), str(message or 'Rendering saved Remotion edit...'))

    try:
        result = retained_master or _run_with_remotion_render_slot(
            lambda: render_semantic_documentary(
                manifest=manifest,
                output_path=render_output_path,
                config=render_config,
                progress_callback=_render_progress,
                cancellation=cancellation,
            ),
            cancellation=cancellation,
            progress_callback=_render_progress,
            render_config=render_config,
        )
    except Exception as render_error:
        memory_warning = getattr(render_error, 'memory_warning', None) or getattr(render_error, 'memory_snapshot', None)
        if memory_warning is None:
            memory_warning = getattr(getattr(render_error, '__cause__', None), 'memory_snapshot', None)
        if memory_warning:
            _write_generation_checkpoint(
                config,
                'render_failure.json',
                {
                    'kind': 'low_memory',
                    'error': f'{type(render_error).__name__}: {render_error}',
                    'memory': memory_warning,
                    'retryable': True,
                },
                stage='waiting_for_memory',
                status='retryable',
            )
            _set_video_package_status(
                config,
                'waiting_for_memory',
                retryable=True,
                memory=memory_warning,
            )
        raise
    if cancellation is not None:
        cancellation.raise_if_cancelled()
    rendered_path = Path(str((result or {}).get('output_path') or render_output_path)).expanduser().resolve()
    if not rendered_path.is_file():
        raise RuntimeError('Resumed Remotion render finished without an output file.')
    _pending_master_checkpoint(config, rendered_path, result or {})
    # Persist the actual reviewed render plan, including revised scenes and QA
    # evidence. A checkpoint export must not return an older unreviewed plan.
    revised_manifest_path = (result or {}).get('rendered_manifest_path')
    if revised_manifest_path and Path(revised_manifest_path).is_file():
        rendered_manifest = json.loads(Path(revised_manifest_path).read_text(encoding='utf-8'))
        for key in ('scenes', 'production_timeline', 'media_shot_plan', 'creative_review', 'preview_review', 'render_media_timing'):
            if key in rendered_manifest:
                manifest[key] = rendered_manifest[key]
    width = int(manifest.get('width') or (manifest.get('config') or {}).get('width') or 1920)
    height = int(manifest.get('height') or (manifest.get('config') or {}).get('height') or 1080)
    vision_key = str(
        render_config.get('openrouter_api_key')
        or os.environ.get('OPENROUTER_API_KEY')
        or os.environ.get('VIDZEO_OPENROUTER_API_KEY')
        or ''
    ).strip()
    # Validate the completed Remotion file before replacing the previous
    # deliverable. A retry or visual QA failure must leave the older file
    # intact and the package available for another correction.
    quality_checks = _validate_remotion_master(
        rendered_path,
        expected_duration,
        (width, height),
        manifest,
        vision_key=vision_key,
        require_audio=True,
    )
    if rendered_path != output_path.resolve():
        import shutil
        shutil.copy2(rendered_path, output_path)
    render_metadata = {
        **dict(manifest.get('render_metadata') or {}),
        'selected_backend': 'remotion',
        'renderer': (result or {}).get('renderer', 'remotion-react'),
        'status': 'validated',
        'edit_plan_schema_version': manifest.get('edit_plan_schema_version', 1),
        'edit_plan_path': str(plan_path),
        'model_route': {
            'selected': director.get('model'),
            'stages': director.get('model_routes') or [],
            'models_used': director.get('models_used') or [],
            'fallback_used': bool(director.get('fallback_used')),
            'status': director.get('status') or 'not_recorded',
        },
        'remotion_workers': (result or {}).get('render_resources', {}).get('recommended_workers'),
        'render_resources': (result or {}).get('render_resources', {}),
        'quality_checks': quality_checks,
        'resumed_from_checkpoint': True,
        'creative_review': (result or {}).get('creative_review'),
        'preview_review': (result or {}).get('preview_review'),
        'one_beat_per_scene': True,
    }
    from services.editorial_director.release_review import release_review
    from services.delivery_quality import delivery_quality_summary
    render_metadata['release_review'] = release_review(manifest, quality_checks)
    delivery_quality = delivery_quality_summary(render_metadata, manifest)
    render_metadata['delivery_quality'] = delivery_quality
    manifest['release_review'] = render_metadata['release_review']
    manifest['edit_plan_validation'] = dict(validation)
    manifest['render_metadata'] = render_metadata
    plan_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2, default=str), encoding='utf-8')
    if failure:
        _write_generation_checkpoint(
            config,
            'render_failure.json',
            {
                **failure,
                'resolved': True,
                'resolved_at': time.strftime('%Y-%m-%dT%H:%M:%S%z'),
                'resolved_by': str(output_path),
            },
            stage='render_retry_resolved',
        )
    render_checkpoint = _write_generation_checkpoint(
        config,
        'render_complete.json',
        {
            'backend': 'remotion',
            'output_path': str(output_path),
            'duration': expected_duration,
            'scene_count': len(scenes),
            'one_beat_per_scene': True,
            'edit_plan_path': str(plan_path),
            'render_metadata': render_metadata,
        },
        stage='complete',
        status='complete',
    )
    _set_video_package_status(config, 'completed', output_path=str(output_path), render_checkpoint=render_checkpoint)
    update_progress(100, 'Completed from saved Remotion checkpoint')
    return {
        'success': True,
        'video': _path_to_url(output_path),
        'video_url': _path_to_url(output_path),
        'video_path': str(output_path),
        'duration': round(expected_duration, 3),
        'component_manifest': manifest,
        'render_metadata': render_metadata,
        'manifest_path': str(plan_path),
        'storyboard': str(checkpoint_dir / 'storyboard.json') if (checkpoint_dir / 'storyboard.json').is_file() else None,
        'output_package_dir': str(package_dir),
        'checkpoint_dir': str(checkpoint_dir),
        'name': config.get('output_name') or config.get('name') or 'Video',
        'content_title': config.get('content_title') or config.get('title') or 'Video',
        **delivery_quality,
    }


GENERATION_PREPARATION_GATE = threading.BoundedSemaphore(int(os.environ.get('VIDNETS_MAX_PARALLEL_PREPARATION', '4')))


def generate_video(config, update_progress=None, check_cancelled=None, cancellation=None):
    """The single generation orchestrator used by HTTP, queue and retries."""
    from services.generation_cost_policy import apply_generation_cost_policy
    config.update(apply_generation_cost_policy(config))
    update_progress = update_progress or (lambda _value, _message: None)
    check_cancelled = check_cancelled or (lambda: False)
    def execute(context):
        from services.job_context import check_job_active
        began = time.monotonic()
        while not GENERATION_PREPARATION_GATE.acquire(timeout=.2):
            check_job_active()
            if check_cancelled():
                raise InterruptedError('Job cancelled before preparation.')
            if time.monotonic() - began >= float(os.environ.get('VIDNETS_PREPARATION_GATE_TIMEOUT', '120')):
                error = RuntimeError('Video preparation is busy. Retry with the same request ID, or use queue mode.')
                error.stage = 'generation_capacity'
                error.retryable = True
                raise error
        try:
            return _generate_video_impl(config, update_progress, check_cancelled, context)
        finally:
            GENERATION_PREPARATION_GATE.release()
    from services.export_entitlements import finish_generation_export
    try:
        result = _run_job_scoped(execute, config, cancellation)
    except Exception as exc:
        if not getattr(exc, 'retryable', False) and getattr(exc, 'stage', '') not in {
                'generation_capacity', 'remotion_edit_plan', 'remotion_render', 'delivery_deadline'}:
            finish_generation_export(config, False)
        raise
    finish_generation_export(config, bool(result.get('success')), result.get('duration') or 0)
    return result


def _queue_generation_callback(config, update_progress, check_cancelled, cancellation=None):
    return generate_video(config, update_progress, check_cancelled, cancellation)


def _generate_video_impl(config, update_progress, check_cancelled, cancellation=None):
    """Run the unified pipeline directly for queue jobs."""
    if cancellation is None:
        from services.cancellation import CancellationContext
        cancellation = CancellationContext()
    cancellation.raise_if_cancelled()
    callback_config = config
    config = _apply_env_api_key_defaults(config)
    job_type = (config.get('type') or 'long').strip().lower()

    # Retry a memory-paused render from its saved Remotion plan before warming
    # Whisper or re-running narration, source queries, model direction, or media.
    resumed = _resume_checkpointed_remotion_render(config, update_progress, cancellation)
    if resumed is not None:
        return resumed

    # YouTube Clips standalone job
    if job_type == 'yt-clips':
        return _run_yt_clips_queue_job(config, update_progress, check_cancelled, cancellation)

    job_config = _coerce_media_source_from_weights(_ensure_script_for_queue(config, update_progress=update_progress))
    whisper_warmup_handle = _start_whisper_warmup(job_config)
    content_title = str(
        job_config.get('content_title')
        or job_config.get('title')
        or job_config.get('name')
        or 'Video'
    ).strip()
    safe_name = sanitize_output_name(
        job_config.get('output_name')
        or job_config.get('name')
        or content_title
        or 'Video'
    )
    job_config['content_title'] = content_title
    job_config['output_name'] = safe_name
    job_config['name'] = safe_name
    job_config['title'] = content_title
    job_config['_whisper_warmup_handle'] = whisper_warmup_handle
    # The queue callback receives an isolated copy. Publish its durable package
    # path back to that copy before any expensive stage can fail, so the queue
    # can persist the path and Retry reuses the same checkpoints.
    package_dir = _prepare_video_output_package(job_config, safe_name)
    callback_config['_output_package_dir'] = str(package_dir)
    callback_config['output_package_dir'] = str(package_dir)
    callback_config['output_dir'] = str(package_dir)

    if check_cancelled():
        raise InterruptedError("Job cancelled by user")

    update_progress(10, "Starting video generation...")
    payload = _run_video_pipeline(
        job_config,
        progress_callback=lambda fraction, message: update_progress(int(round(max(0.0, min(1.0, float(fraction))) * 100)), message),
        cancellation=cancellation,
    )

    if job_config.get('media_retrieval_only') is True and payload.get('media_retrieval_only') is True:
        cancellation.raise_if_cancelled()
        update_progress(100, "Media retrieval-only check complete; render was not started")
        return payload

    if not payload.get('success') or not Path(str(payload.get('video_path') or '')).is_file():
        error = RuntimeError('Generation did not produce an available video file. Retry from the saved project.')
        error.stage = 'remotion_render'
        error.retryable = True
        raise error
    cancellation.raise_if_cancelled()
    update_progress(100, "Completed")
    return {
        **payload,
        "success": True,
        "video": payload.get('video'),
        "video_url": payload.get('video_url') or payload.get('video'),
        "duration": payload.get('duration', 0),
        "video_path": payload.get('video_path'),
        "component_manifest": payload.get('component_manifest', {}),
        "manifest_path": payload.get('manifest_path'),
        "storyboard": payload.get('storyboard'),
        "output_package_dir": payload.get('output_package_dir'),
        "checkpoint_dir": payload.get('checkpoint_dir'),
        "name": job_config.get('output_name') or job_config.get('name') or 'Video',
        "content_title": job_config.get('content_title') or job_config.get('title') or 'Video'
    }


def _run_yt_clips_queue_job(config, update_progress, check_cancelled, cancellation=None):
    """Run standalone YouTube Clips search/download job."""
    from services.youtube_clips_service import get_youtube_clips

    title = config.get('title', 'YouTube Clips').strip()
    script = (config.get('script') or '').strip()
    num_scenes = int(config.get('num_scenes') or 10)
    openrouter_api_key = (config.get('openrouter_api_key') or '').strip()
    if not openrouter_api_key:
        raise ValueError("OpenRouter API key required for YouTube Clips brain")
    if not script or len(script) < 10:
        raise ValueError("Script too short for YouTube Clips")

    update_progress(10, f"Starting YouTube Clips search: {title}")

    if check_cancelled():
        raise InterruptedError("Job cancelled by user")

    topic_anchor = _resolve_topic_anchor_for_config(title, script, config).strip()
    if topic_anchor:
        title = f"{topic_anchor} - {title}" if topic_anchor.lower() not in title.lower() else topic_anchor
    scene_texts = None
    scene_query_future = None
    try:
        from services.scene_splitter import build_expected_scenes, get_scene_texts
        expected_scenes = build_expected_scenes(script, config.get('scene_mode', 'Every Beat'), max(8.0, num_scenes * 7.0))
        scene_texts = get_scene_texts(expected_scenes)[:num_scenes]
        if len(scene_texts) < num_scenes:
            scene_texts.extend([script] * (num_scenes - len(scene_texts)))
        from concurrent.futures import ThreadPoolExecutor
        from services.job_context import JobThreadPoolExecutor as ThreadPoolExecutor
        scene_query_executor = ThreadPoolExecutor(max_workers=1)
        scene_query_future = scene_query_executor.submit(
            _generate_fast_youtube_scene_queries, script, topic_anchor or title, scene_texts, config, True
        )
    except Exception as exc:
        print(f"   Warning: standalone YouTube LLM scene query pre-bake skipped: {exc}")

    clip_paths = get_youtube_clips(
        script=script,
        title=title,
        num_scenes=num_scenes,
        scene_durations=[7.0] * num_scenes,
        openrouter_api_key=openrouter_api_key,
        scene_texts=scene_texts,
        scene_query_future=scene_query_future,
        video_format=config.get('_video_format', ''),
        lenient_acceptance=config.get('lenient_acceptance', True),
        download_candidate_limit=int(config.get('download_candidate_limit', os.environ.get('VIDZEO_YT_DOWNLOAD_CANDIDATES', '3')) or 3),
        allow_same_source_reuse=config.get('allow_same_source_reuse', True),
        stop_on_soft_timeout=config.get('stop_on_soft_timeout', True),
        stream_downloads=config.get('stream_downloads', True),
        max_download_scenes=int(config.get('max_download_scenes', 0)),
        min_resolved_ratio_before_soft_stop=float(config.get('min_resolved_ratio_before_soft_stop', 0.72)),
        progress_callback=lambda p, msg: update_progress(min(95, 10 + int(p * 85)), msg),
        cancellation=cancellation,
    )

    resolved = sum(1 for p in clip_paths if p)
    update_progress(100, f"Complete: {resolved}/{num_scenes} clips found")

    return {
        "success": True,
        "type": "yt-clips",
        "title": title,
        "clips": [
            {"path": p, "scene_index": i}
            for i, p in enumerate(clip_paths) if p
        ],
        "total_scenes": num_scenes,
        "resolved_count": resolved,
    }


@app.route('/api/queue/add', methods=['POST'])
@require_active_access
def api_queue_add():
    from services.generation_request import normalize_request
    try:
        incoming = normalize_request(request.get_json(silent=True))
    except ValueError as exc:
        return _json_error(str(exc), 400)
    if getattr(request, 'vidzeo_agent', False) and str(incoming.get('llm_provider') or '') == 'external_agent':
        # A paired local agent submitted this job (local-bypass carries owner
        # 'local-user'): stamp its owner on the config so the brain, vision
        # and director can post agent-bridge requests. Without it agent_post
        # refuses with "Pair a local agent..." and the job silently falls back
        # to mechanical queries that find nothing — every /api/queue/add
        # external_agent job before this fix finished 0 real media.
        incoming['agent_owner_id'] = request.vidzeo_agent_owner
    data = _apply_env_api_key_defaults(_attach_plan_constraints(incoming, request.vidzeo_user))
    data = _coerce_media_source_from_weights(data)
    from services.generation_cost_policy import apply_generation_cost_policy
    data = apply_generation_cost_policy(data)
    try:
        data = _enforce_generation_plan_limits(data, request.vidzeo_user)
        _validate_media_request_config(data)
        from services.export_entitlements import reserve_generation_export
        # The compatibility route has no idempotency registry. Each enqueue is
        # a distinct export; public request IDs cannot reuse an old allowance.
        from uuid import uuid4
        data['_export_request_id'] = str(uuid4())
        reserve_generation_export(data, request.vidzeo_access_token,
            _parse_duration_to_seconds(data.get('duration')) or _estimate_script_duration_seconds(data.get('script') or ''))
        return jsonify(_enqueue_generation_request(data, request.vidzeo_user))
    except ValueError as exc:
        from services.export_entitlements import finish_generation_export
        finish_generation_export(data, False)
        return jsonify({'error': str(exc), 'limit_reached': 'PLAN_LIMIT_REACHED:' in str(exc)}), 400
    except AuthServiceError as exc:
        return _json_error(str(exc), getattr(exc,'status_code',503) or 503)


def _enqueue_generation_request(data, user):
    """Legacy queue admission and /api/generate share setup and worker startup."""
    caller_data = data
    try:
        normalized = normalize_generation_config(data)
        data.update(normalized)
        content_title = str(data.get('content_title') or data.get('title') or data.get('name') or 'Video').strip()
        safe_name = sanitize_output_name(data.get('output_name') or data.get('name') or content_title or 'Video')
        data['content_title'] = content_title
        data['output_name'] = safe_name
        data['name'] = safe_name
        data['title'] = content_title
        data = _enforce_generation_plan_limits(data, user)
        _validate_media_request_config(data)
        # Reserve the package before the worker starts so a restart or
        # low-memory pause has a stable folder to resume from.
        package_dir = _prepare_video_output_package(data, safe_name)
        caller_data.update(output_package_dir=str(package_dir), _output_package_dir=str(package_dir))
    except ValueError as exc:
        raise
    qm = get_queue_manager()
    item = qm.add_item(data)
    # Adding a queue item is the user action that starts background work. Keep
    # the explicit /start endpoint for older clients, but never leave a newly
    # accepted job stranded in `queued` just because that second request failed.
    started = qm.start_worker(_queue_generation_callback)
    return {
        "success": True,
        "item": item,
        "worker_running": qm.worker_running,
        "worker_started": bool(started),
    }


