@app.route('/api/queue/update', methods=['POST'])
@require_active_access
def api_queue_update():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return _json_error('Queue update must be a JSON object.', 400)
    job_id = data.get('id')
    updates = data.get('updates') or {}
    if not isinstance(updates, dict):
        return _json_error('updates must be a JSON object.', 400)
    if set(updates) - {'config'}:
        return _json_error('Only queued generation settings may be updated.', 400)
    if 'config' in updates and not isinstance(updates['config'], dict):
        return _json_error('config must be a JSON object.', 400)
    if not job_id:
        return jsonify({"error": "id required"}), 400
    if not get_queue_manager().get_item_snapshot(job_id, owner_id=request.vidzeo_user.get('user_id')):
        return _json_error('Job not found.', 404)
    try:
        if isinstance(updates.get('config'), dict):
            from services.generation_request import normalize_request
            public_updates = normalize_request(updates['config'])
            current_item = get_queue_manager().get_item(job_id) or {}
            merged_config = {
                **(current_item.get('config') or {}),
                **public_updates,
            }
            merged_config = _attach_plan_constraints(merged_config, request.vidzeo_user)
            merged_config = _coerce_media_source_from_weights(merged_config)
            merged_config = normalize_generation_config(merged_config)
            merged_config = _enforce_generation_plan_limits(merged_config, request.vidzeo_user)
            _validate_media_request_config(merged_config)
            updates['config'] = merged_config
    except ValueError as exc:
        return jsonify({"error": str(exc)}), 400
    updated = get_queue_manager().update_item(job_id, updates)
    if not updated:
        return jsonify({"error": "Unable to update job"}), 400
    return jsonify({"success": True})


@app.route('/api/queue/resume', methods=['POST'])
@require_active_access
def api_queue_resume():
    data = request.json or {}
    job_id = data.get('id')
    if not job_id:
        return jsonify({"error": "id required"}), 400
    qm = get_queue_manager()
    if not qm.get_item_snapshot(job_id, owner_id=request.vidzeo_user.get('user_id')):
        return _json_error('Job not found.', 404)
    item = qm.get_item(job_id)
    if item.get('status') not in {'paused', 'error', 'shutdown_timeout'} or job_id in qm.active_jobs:
        return _json_error('This job is not ready for retry.', 409)
    updated_config = _attach_plan_constraints(dict(item.get('config') or {}), request.vidzeo_user)
    try:
        updated_config = _enforce_generation_plan_limits(updated_config, request.vidzeo_user)
        from services.export_entitlements import reserve_generation_export
        reserve_generation_export(updated_config, request.vidzeo_access_token,
            _parse_duration_to_seconds(updated_config.get('duration')) or _estimate_script_duration_seconds(updated_config.get('script') or ''))
    except ValueError as exc:
        return jsonify({'error': str(exc), 'limit_reached': 'PLAN_LIMIT_REACHED:' in str(exc)}), 400
    except AuthServiceError as exc:
        return _json_error(str(exc), getattr(exc, 'status_code', 503) or 503)
    resumed = qm.resume_item(job_id, config=updated_config)
    if not resumed:
        return jsonify({"error": "Unable to resume job"}), 400
    return jsonify({"success": True, "needs_start": not qm.worker_running})

@app.route('/api/queue/advance-scene', methods=['POST'])
@require_active_access
def api_queue_advance_scene():
    """Debugger scene advance: resolve a stuck scene from media already on
    disk instead of hunting further. Body: {id, scene_number, reason}.
    The media coordinator honors the flag between waves / at resolution
    time (tier 1: on-disk reuse, then the existing same-job reuse and
    graphic tiers). Does not duplicate or restart the job."""
    data = request.json or {}
    job_id = data.get('id')
    if not job_id:
        return jsonify({"error": "id required"}), 400
    qm = get_queue_manager()
    if not qm.get_item_snapshot(job_id, owner_id=request.vidzeo_user.get('user_id')):
        return _json_error('Job not found.', 404)
    try:
        scene_number = int(data.get('scene_number') or 0)
    except (TypeError, ValueError):
        return jsonify({"error": "scene_number must be an integer"}), 400
    if scene_number <= 0:
        return jsonify({"error": "scene_number must be a positive scene number"}), 400
    item = qm.get_item(job_id) or {}
    if str(item.get('status') or '').strip().lower() != 'processing':
        return _json_error('Job is not processing.', 409)
    reason = str(data.get('reason') or 'manual advance-scene request')
    if not qm.request_scene_advance(job_id, scene_number, reason):
        return jsonify({"error": "Unable to request scene advance"}), 400
    return jsonify({"success": True, "job_id": job_id, "scene_number": scene_number})

