def _resolve_editor_media_path(media_info, root=BASE_DIR):
    if not isinstance(media_info, Mapping) and not isinstance(root, Mapping):
        return None
    sources = []
    if isinstance(media_info, Mapping):
        sources.append(media_info)
    if isinstance(root, Mapping):
        sources.append(root)
    base_root = root if isinstance(root, (str, Path)) and not isinstance(root, Mapping) else BASE_DIR

    candidates = []
    for info in sources:
        for key in ('path', 'src', 'file', 'filepath', 'selected_path'):
            val = info.get(key)
            if val:
                candidates.append(str(val))
        for raw_url in (info.get('url'), info.get('src')):
            if not raw_url:
                continue
            url = str(raw_url)
            if url.startswith('/output/'):
                resolved = _resolve_output_file(url[len('/output/'):])
                if resolved:
                    candidates.append(str(resolved))
            elif url.startswith('/temp/'):
                resolved = _resolve_temp_file(url[len('/temp/'):])
                if resolved:
                    candidates.append(str(resolved))
            elif url.startswith('local-media://'):
                candidates.append(urllib.parse.unquote(url[len('local-media://'):]))
    for raw_path in candidates:
        if not raw_path:
            continue
        try:
            candidate = Path(str(raw_path))
            if not candidate.is_absolute():
                rooted = base_root / candidate
                if rooted.exists():
                    candidate = rooted
            candidate = candidate.resolve()
            if candidate.is_file():
                return candidate
        except OSError:
            continue
    return None


def _editor_resolution(value, default=(1920, 1080)):
    if isinstance(value, Mapping):
        width = value.get('w', 1920)
        height = value.get('h', 1080)
    else:
        raw = str(value or '1920x1080').strip().lower()
        presets = {
            '480p': (854, 480),
            '720p': (1280, 720),
            '1080p': (1920, 1080),
            '1440p': (2560, 1440),
            '2160p': (3840, 2160),
        }
        if raw in presets:
            return presets[raw]
        match = re.match(r'^(\d+)\s*[xÃƒÆ’Ã¢â‚¬â€]\s*(\d+)$', raw)
        if match:
            width, height = match.groups()
        else:
            width, height = (1920, 1080)
    try:
        width = int(width)
        height = int(height)
        if not (320 <= width <= 7680 and 180 <= height <= 4320):
            raise ValueError("Editor resolution must be between 320x180 and 7680x4320")
        return (width, height)
    except (TypeError, ValueError):
        return (1920, 1080)


def _editor_float(value, default=0.0):
    try:
        number = float(value)
        if math.isfinite(number):
            return number
        return float(default)
    except (TypeError, ValueError):
        return float(default)


def _upgrade_legacy_video_clip_manifest(manifest, width=1920, height=1080, fps=30):
    """Translate video_clips-only project manifests into Remotion scenes.

    Older generated projects did not store the versioned scene plan. Keep them
    editable by deriving one straightforward media scene per saved clip; this
    preserves their footage and timing while routing their export through the
    same Remotion composition.
    """
    upgraded = dict(manifest or {})
    if isinstance(upgraded.get('scenes'), list) and upgraded['scenes']:
        return upgraded
    clips = [clip for clip in (upgraded.get('video_clips') or []) if isinstance(clip, Mapping)]
    if not clips:
        return upgraded
    fps = max(12, min(60, int(fps or upgraded.get('fps') or 30)))
    width = int(upgraded.get('width') or width or 1920)
    height = int(upgraded.get('height') or height or 1080)
    source_texts = list(upgraded.get('source_scene_texts') or upgraded.get('scene_texts') or [])
    scenes = []
    final_frame = 0
    for index, clip in enumerate(clips):
        clip_path = str(clip.get('path') or '').strip()
        clip_url = str(clip.get('url') or '').strip()
        source = clip_path or clip_url
        if clip_path and clip_url and _remotion_asset_status(clip_path) == 'missing':
            source = clip_url
        if not source:
            continue
        start = max(0.0, _editor_float(clip.get('track_offset', clip.get('trackOffset', 0.0)), 0.0))
        clip_in = max(0.0, _editor_float(clip.get('start'), 0.0))
        clip_end = _editor_float(clip.get('end'), clip_in + _editor_float(clip.get('duration'), 3.0))
        duration = max(0.2, clip_end - clip_in)
        extension = Path(clip_path or clip_url.split('?', 1)[0]).suffix.lower()
        media_type = str(clip.get('media_type') or clip.get('type') or '').lower()
        is_video = media_type == 'video' or media_type.startswith('video/') or extension in {
            '.mp4', '.mov', '.m4v', '.webm', '.mkv', '.avi', '.wmv',
        }
        visual_type = 'SmartVideo' if is_video else 'SmartImage'
        variant = 'full_bleed' if is_video else 'full_bleed_cinematic'
        from_frame = int(round(start * fps))
        duration_frames = max(1, int(round(duration * fps)))
        end = start + duration_frames / fps
        design = dict(clip.get('design') or {}) if isinstance(clip.get('design'), Mapping) else {}
        asset = {
            'src': source,
            'path': clip_path or source,
            'type': 'video' if is_video else 'image',
            'source_start': clip_in,
            'fit': clip.get('fit') or 'cover',
            'position': clip.get('position') or 'center',
            'safe_framing': clip.get('safe_framing') is not False,
        }
        if clip_url:
            asset['url'] = clip_url
        narration = str(clip.get('narration') or clip.get('text') or (source_texts[index] if index < len(source_texts) else '')).strip()
        scene_id = str(clip.get('scene_id') or clip.get('id') or f'legacy-scene-{index + 1}')
        scenes.append({
            'id': scene_id,
            'scene_id': scene_id,
            'scene_index': index,
            'start': round(start, 3),
            'end': round(end, 3),
            'from': from_frame,
            'duration': round(duration_frames / fps, 3),
            'duration_in_frames': duration_frames,
            'narration': narration,
            'visual_intent': 'Preserve saved legacy footage and timeline timing',
            'primary_visual': {
                'type': visual_type,
                'variant': variant,
                'props': {'variant': variant},
                'asset': asset,
            },
            'media': asset,
            'camera': {'motion': str(design.get('camera') or 'slow_push')},
            'transition_out': 'hard_cut',
            'transition': {'template_id': 'hard_cut', 'duration': 0.25},
            'design': design,
        })
        final_frame = max(final_frame, from_frame + duration_frames)

    if not scenes:
        return upgraded
    upgraded.update({
        'version': upgraded.get('version') or 2,
        'fps': fps,
        'width': width,
        'height': height,
        'scenes': scenes,
        'duration_in_frames': final_frame,
        'duration': round(final_frame / fps, 3),
    })
    if not isinstance(upgraded.get('visual_dna'), Mapping) and isinstance(upgraded.get('theme'), Mapping):
        upgraded['visual_dna'] = dict(upgraded['theme'])
    audio_plan = dict(upgraded.get('audio_plan') or {}) if isinstance(upgraded.get('audio_plan'), Mapping) else {}
    voiceover = dict(audio_plan.get('voiceover') or {}) if isinstance(audio_plan.get('voiceover'), Mapping) else {}
    voiceover_src = str(upgraded.get('audio_url') or upgraded.get('audio_path') or voiceover.get('src') or voiceover.get('path') or '').strip()
    if voiceover_src:
        voiceover.setdefault('src', voiceover_src)
        audio_plan['voiceover'] = voiceover
        upgraded['audio_plan'] = audio_plan
    return upgraded


@app.route('/api/editor/templates', methods=['GET'])
@require_active_access
def api_editor_templates():
    """Shared curated template catalog for the UI, director, and Remotion."""
    from services.template_library import list_template_catalog
    include_drafts = str(request.args.get('include_drafts') or '').strip().lower() in {'1', 'true', 'yes'}
    return jsonify({"success": True, **list_template_catalog(include_drafts=include_drafts)})


@app.route('/api/editor/templates/validate', methods=['POST'])
@require_active_access
def api_editor_template_validate():
    from services.template_library import save_custom_template, validate_template_recipe
    data = request.get_json(silent=True) or {}
    recipe = data.get('recipe') if isinstance(data.get('recipe'), Mapping) else data
    try:
        normalized = validate_template_recipe(recipe)
        saved = False
        if data.get('save') is True:
            review_status = 'approved' if data.get('approve') is True else 'draft'
            save_custom_template(normalized, review_status=review_status)
            saved = True
        return jsonify({"success": True, "recipe": normalized, "saved": saved,
                        "review_status": "approved" if saved and data.get('approve') is True else "draft"})
    except (TypeError, ValueError) as exc:
        return jsonify({"success": False, "error": str(exc)}), 422


@app.route('/api/editor/media-info', methods=['POST'])
@require_active_access
def api_editor_media_info():
    data = request.json or {}
    source = _resolve_editor_media_path(data)
    if not source:
        return jsonify({"error": "Media path does not exist"}), 404
    media_type = "image" if source.suffix.lower() in {".png", ".jpg", ".jpeg", ".webp", ".bmp"} else "video"
    if media_type == "image":
        try:
            from PIL import Image
            with Image.open(source) as img:
                w, h = img.size
            return jsonify({
                "basename": source.name,
                "path": str(source),
                "type": "image",
                "duration": 0.0,
                "width": int(w),
                "height": int(h),
            })
        except Exception as exc:
            return jsonify({"error": f"Unable to probe image: {exc}"}), 400
    try:
        import subprocess, json
        ffprobe_bin = str(os.environ.get("VIDZEO_FFPROBE_PATH") or "ffprobe")
        cmd = [
            ffprobe_bin, "-v", "error", "-select_streams", "v:0",
            "-show_entries", "stream=width,height:format=duration",
            "-of", "json", str(source)
        ]
        probe = subprocess.run(cmd, capture_output=True, text=True, timeout=10)
        payload = json.loads(probe.stdout or "{}") if probe.returncode == 0 else {}
        streams = payload.get("streams") or []
        video_stream = next((row for row in streams if row.get("width") and row.get("height")), {})
        duration = _editor_float((payload.get("format") or {}).get("duration"), 0.0)
        return jsonify({
            "basename": source.name,
            "path": str(source),
            "type": media_type,
            "duration": duration,
            "width": int(video_stream.get("width") or 0),
            "height": int(video_stream.get("height") or 0),
        })
    except Exception as exc:
        return jsonify({"error": f"Unable to probe media: {exc}"}), 400


@app.route('/api/editor/source-capture', methods=['POST'])
@require_active_access
def api_editor_source_capture():
    data = request.json or {}
    url = str(data.get('url') or '').strip()
    excerpt = str(data.get('excerpt') or '').strip()
    if not url or not excerpt:
        return jsonify({"success": False, "error": "A source URL and exact passage are required."}), 400
    try:
        from services.source_evidence import capture_source_evidence
        source_capture = capture_source_evidence(url, excerpt, OUTPUT_DIR)
        return jsonify({"success": True, "source_capture": source_capture})
    except ValueError as exc:
        return jsonify({"success": False, "error": str(exc)}), 400
    except Exception as exc:
        return jsonify({"success": False, "error": f"Source capture failed: {type(exc).__name__}: {exc}"}), 422


@app.route('/api/editor/render', methods=['POST'])
@require_active_access
def api_editor_render():
    from services.export_entitlements import reserve_generation_export,finish_generation_export
    data=request.get_json(silent=True) or {}
    if not isinstance(data,dict):
        return _json_error('A timeline object is required.',400)
    manifest=data.get('manifest') if isinstance(data.get('manifest'),dict) else data
    fps=max(1,_editor_float(manifest.get('fps'),30))
    duration=max(0,_editor_float(data.get('duration'),0),_editor_float(manifest.get('duration'),0))
    for scene in [*(manifest.get('scenes') or []), *(manifest.get('video_clips') or [])]:
        if isinstance(scene,dict):
            length=_editor_float(scene.get('duration'),_editor_float(scene.get('duration_in_frames'),0)/fps)
            duration=max(duration,_editor_float(scene.get('start'),0)+length)
    for track in data.get('tracks') or []:
        if not isinstance(track,dict):
            return _json_error('Each timeline track must be an object.',400)
        for clip in track.get('clips') or []:
            if not isinstance(clip,dict):
                return _json_error('Each timeline clip must be an object.',400)
            offset=_editor_float(clip.get('trackOffset',clip.get('track_offset')),0)
            length=max(0,_editor_float(clip.get('end'),0)-_editor_float(clip.get('start'),0))
            duration=max(duration,offset+length)
    if duration<=0:
        return _json_error('The timeline must specify a positive duration.',400)
    allowance=_attach_plan_constraints({},request.vidzeo_user)
    try:
        reserve_generation_export(allowance,request.vidzeo_access_token,duration)
    except AuthServiceError as exc:
        return _json_error(str(exc),getattr(exc,'status_code',503) or 503)
    except ValueError as exc:
        return jsonify({'error':str(exc),'limit_reached':True}),400
    try:
        response=app.make_response(_api_editor_render_impl())
    except Exception:
        finish_generation_export(allowance,False)
        raise
    payload=response.get_json(silent=True) or {}
    finish_generation_export(allowance,response.status_code<300 and payload.get('success') is True,duration)
    return response


def _api_editor_render_impl():
    edit_plan_path = None
    manifest = None
    try:
        data = request.json or {}
        project_name = str(data.get('name') or data.get('title') or 'Edited_Video').strip()
        safe_name = re.sub(r'[^a-zA-Z0-9_\-]', '_', project_name).strip('_') or 'video'
        timestamp = int(time.time())
        out_filename = f"{safe_name}_edit_{timestamp}.mp4"
        out_path = OUTPUT_DIR / out_filename
        OUTPUT_DIR.mkdir(parents=True, exist_ok=True)

        manifest = data.get('manifest')
        if not (isinstance(manifest, dict) and manifest) and (isinstance(data, dict) and data.get('scenes')):
            manifest = data

        if manifest and isinstance(manifest, dict) and (manifest.get('scenes') or manifest.get('video_clips')):
            from services.native_render_policy import render_semantic_documentary
            requested_resolution = data.get('resolution') or data.get('aspect_ratio') or '1080p'
            fallback_width, fallback_height = _editor_resolution(requested_resolution)
            manifest = _upgrade_legacy_video_clip_manifest(
                manifest,
                width=fallback_width,
                height=fallback_height,
                fps=max(12, min(60, int(manifest.get('fps') or data.get('fps') or 30))),
            )
            director_info = manifest.get('director') if isinstance(manifest.get('director'), Mapping) else {}
            director_status = str(director_info.get('status') or '').strip().lower()
            director_fallback = director_status in {'deterministic_fallback', 'local_fallback'}
            if director_fallback:
                safe_name = f"{safe_name}_local_director_fallback"
                out_filename = f"{safe_name}_edit_{timestamp}.mp4"
                out_path = OUTPUT_DIR / out_filename
            if manifest.get('audio_url') or manifest.get('audio_path'):
                audio_plan = dict(manifest.get('audio_plan') or {}) if isinstance(manifest.get('audio_plan'), Mapping) else {}
                voiceover = dict(audio_plan.get('voiceover') or {}) if isinstance(audio_plan.get('voiceover'), Mapping) else {}
                voiceover.setdefault('src', str(manifest.get('audio_url') or manifest.get('audio_path')))
                audio_plan['voiceover'] = voiceover
                manifest['audio_plan'] = audio_plan
            cfg = dict(manifest.get('config') or {})
            cfg['render_backend'] = 'remotion'
            cfg['semantic_render_required'] = True
            fast_setting = data.get('fast_render', data.get('fast_mode', cfg.get('semantic_fast_render', True)))
            cfg['semantic_fast_render'] = str(fast_setting).strip().lower() in {'1', 'true', 'yes', 'on'}
            _repair_unsupported_chart_scenes(manifest)
            _repair_unsupported_route_map_scenes(manifest)
            _repair_repeated_adjacent_treatments(manifest)
            edit_plan_path = OUTPUT_DIR / f"{safe_name}_edit_plan.json"
            validation = _validate_remotion_edit_plan(manifest, len(manifest.get('scenes') or []))
            manifest['edit_plan_validation'] = validation
            edit_plan_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2, default=str), encoding='utf-8')
            if validation.get('status') != 'pass':
                raise RuntimeError(
                    f"Remotion edit plan failed validation: {validation.get('errors')}. "
                    f"The plan is saved at {edit_plan_path} for correction."
                )
            result = _run_with_remotion_render_slot(
                lambda: render_semantic_documentary(
                    manifest=manifest,
                    output_path=out_path,
                    config={**cfg, '_creative_media_repair': lambda film, findings, budget: _repair_creative_media(film,findings,budget,cfg)},
                ),
                render_config=cfg,
            )
            actual_plan = (result or {}).get('rendered_manifest_path')
            if actual_plan and Path(actual_plan).is_file():
                manifest = json.loads(Path(actual_plan).read_text(encoding='utf-8'))
                validation = _validate_remotion_edit_plan(manifest,len(manifest.get('scenes') or []))
            audio_plan = manifest.get('audio_plan') if isinstance(manifest.get('audio_plan'), Mapping) else {}
            audio = manifest.get('audio') if isinstance(manifest.get('audio'), Mapping) else {}
            voiceover = audio.get('voiceover') or audio_plan.get('voiceover') or {}
            music = audio.get('music') or audio_plan.get('music') or {}
            has_audio = any(
                row.get(key)
                for row in (voiceover, music)
                if isinstance(row, Mapping)
                for key in ('src', 'path', 'url')
            )
            width = int(manifest.get('width') or fallback_width)
            height = int(manifest.get('height') or fallback_height)
            expected_duration = _editor_float(manifest.get('duration'), 0.0)
            if expected_duration <= 0:
                expected_duration = max(
                    (
                        _editor_float(scene.get('start'), 0.0) + _editor_float(scene.get('duration'), 0.0)
                        for scene in manifest.get('scenes') or []
                        if isinstance(scene, Mapping)
                    ),
                    default=0.0,
                )
            vision_key = str(
                cfg.get('openrouter_api_key') or cfg.get('openrouterApiKey')
                or os.environ.get('OPENROUTER_API_KEY') or os.environ.get('VIDZEO_OPENROUTER_API_KEY') or ''
            ).strip()
            quality_checks = _validate_remotion_master(
                out_path,
                expected_duration,
                (width, height),
                manifest,
                vision_key=vision_key,
                require_audio=has_audio,
            )
            render_metadata = {
                'selected_backend': 'remotion',
                'renderer': (result or {}).get('renderer', 'remotion-react'),
                'status': 'validated',
                'edit_plan_schema_version': manifest.get('edit_plan_schema_version', 1),
                'edit_plan_path': str(edit_plan_path),
                'asset_status': validation.get('asset_status') or [],
                'source_status': [
                    {
                        'scene_index': index,
                        'status': (((scene.get('primary_visual') or {}).get('props') or {}).get('source_capture') or {}).get('status', 'not_required')
                        if isinstance((((scene.get('primary_visual') or {}).get('props') or {}).get('source_capture')), Mapping)
                        else 'not_required',
                    }
                    for index, scene in enumerate(manifest.get('scenes') or [])
                    if isinstance(scene, Mapping)
                ],
                'director': dict(director_info),
                'model_route': {
                    'selected': director_info.get('model'),
                    'fallback_chain': director_info.get('fallback_chain') or [],
                    'stages': director_info.get('model_routes') or [],
                    'models_used': director_info.get('models_used') or [],
                    'fallback_used': bool(director_info.get('fallback_used')),
                    'status': director_status or 'not_recorded',
                },
                'director_label': 'LOCAL DIRECTOR FALLBACK' if director_fallback else ('PARTIAL LLM DIRECTION' if director_info.get('local_fallback_scene_indices') else ('OPENROUTER DIRECTOR' if director_status == 'directed' else '')),
                'export_label': 'LOCAL DIRECTOR FALLBACK' if director_fallback else '',
                'remotion_workers': (result or {}).get('render_resources', {}).get('recommended_workers'),
                'render_resources': (result or {}).get('render_resources', {}),
                'quality_checks': quality_checks,
            }
            from services.editorial_director.release_review import release_review
            render_metadata['release_review'] = release_review(manifest, quality_checks)
            manifest['release_review'] = render_metadata['release_review']
            manifest['render_metadata'] = render_metadata
            edit_plan_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2, default=str), encoding='utf-8')
            return jsonify({
                "success": True,
                "output_path": str(out_path),
                "url": f"/output/{out_filename}",
                "filename": out_filename,
                "edit_plan_path": str(edit_plan_path),
                "render_metadata": render_metadata,
            })

        tracks = [t for t in (data.get('tracks') or []) if isinstance(t, Mapping)]
        media_pool = {
            str(m.get('id') or ''): m
            for m in (data.get('mediaPool') or data.get('media_pool') or [])
            if isinstance(m, Mapping) and m.get('id')
        }
        fps = max(12, min(60, int(data.get('fps') or 30)))
        width, height = _editor_resolution(data.get('resolution') or data.get('aspect_ratio') or '1080p')

        video_clips = []
        audio_clips = []
        text_clips = []
        for track_index, track in enumerate(tracks):
            track_type = str(track.get('type') or 'video').lower()
            for clip_index, clip in enumerate(track.get('clips') or []):
                if not isinstance(clip, Mapping):
                    continue
                if track_type == 'video':
                    video_clips.append((track_index, clip_index, clip))
                elif track_type == 'audio':
                    audio_clips.append((track_index, clip_index, clip))
                elif track_type == 'text':
                    text_clips.append((track_index, clip_index, clip))

        image_exts = {'.jpg', '.jpeg', '.png', '.webp', '.bmp'}
        prepared_video = []
        prepared_audio = []
        timeline_duration = _editor_float(data.get('duration'), 0.0)

        def prepare_clip(entry, media_kind):
            track_index, clip_index, clip = entry
            media_info = media_pool.get(str(clip.get('mediaId') or '')) or {}
            source = _resolve_editor_media_path(clip, media_info)
            if not source:
                label = clip.get('name') or clip.get('mediaId') or f"clip {clip_index + 1}"
                raise ValueError(f"Missing {media_kind} media for {label}")
            source_start = max(0.0, _editor_float(clip.get('start'), 0.0))
            source_end = _editor_float(clip.get('end'), source_start)
            clip_duration = source_end - source_start
            if clip_duration <= 0:
                clip_duration = max(0.2, _editor_float(media_info.get('duration'), 3.0))
            timeline_start = max(0.0, _editor_float(
                clip.get('trackOffset', clip.get('track_offset', 0.0)), 0.0
            ))
            timeline_end = timeline_start + clip_duration
            return {
                'source': source,
                'source_start': source_start,
                'duration': clip_duration,
                'timeline_start': timeline_start,
                'timeline_end': timeline_end,
                'is_image': source.suffix.lower() in image_exts,
                'clip': clip,
            }

        for entry in video_clips:
            prepared = prepare_clip(entry, 'video')
            prepared_video.append(prepared)
            timeline_duration = max(timeline_duration, prepared['timeline_end'])
        for entry in audio_clips:
            prepared = prepare_clip(entry, 'audio')
            prepared_audio.append(prepared)
            timeline_duration = max(timeline_duration, prepared['timeline_end'])

        import uuid
        render_tmp_dir = TEMP_DIR / f"ed_render_{uuid.uuid4().hex[:8]}"
        render_tmp_dir.mkdir(parents=True, exist_ok=True)
        try:
            duration = max(0.2, timeline_duration)
            ffmpeg_inputs = []
            filter_parts = [
                f"color=c=black:s={width}x{height}:r={fps}:d={duration:.3f},format=rgba[base0]"
            ]
            input_index = 0
            current_label = 'base0'
            for index, item in enumerate(prepared_video):
                if item['is_image']:
                    ffmpeg_inputs.extend(['-loop', '1', '-framerate', str(fps), '-i', str(item['source'])])
                else:
                    ffmpeg_inputs.extend([
                        '-ss', f"{item['source_start']:.3f}",
                        '-t', f"{item['duration']:.3f}",
                        '-i', str(item['source']),
                    ])
                clip_label = f'clip{index}'
                next_label = f'base{index + 1}'
                filter_parts.append(
                    f"[{input_index}:v]fps={fps},trim=duration={item['duration']:.3f},"
                    f"setpts=PTS-STARTPTS,scale={width}:{height}:"
                    f"force_original_aspect_ratio=decrease,pad={width}:{height}:(ow-iw)/2:(oh-ih)/2:color=black,"
                    f"format=rgba[{clip_label}]"
                )
                filter_parts.append(
                    f"[{current_label}][{clip_label}]overlay=shortest=0:"
                    f"eof_action=pass:x=0:y=0:enable='between(t,{item['timeline_start']:.3f},{item['timeline_end']:.3f})'"
                    f"[{next_label}]"
                )
                current_label = next_label
                input_index += 1

            text_label = current_label
            for text_index, (_track_index, _clip_index, clip) in enumerate(text_clips):
                text = str(clip.get('text') or clip.get('content') or clip.get('name') or '').strip()
                if not text:
                    continue
                start = max(0.0, _editor_float(clip.get('trackOffset', clip.get('track_offset', 0.0)), 0.0))
                clip_start = max(0.0, _editor_float(clip.get('start'), 0.0))
                clip_end = _editor_float(clip.get('end'), clip_start + 2.0)
                end = start + max(0.2, clip_end - clip_start)
                escaped = (text.replace('\\', r'\\').replace(':', r'\:')
                           .replace("'", r"\'").replace(',', r'\,')
                           .replace('[', r'\[').replace(']', r'\]'))
                next_label = f'text{ text_index }'.replace(' ', '')
                filter_parts.append(
                    f"[{text_label}]drawtext=text='{escaped}':x=(w-text_w)/2:y=h-text_h-64:"
                    f"fontsize=42:fontcolor=white:borderw=2:bordercolor=black@0.75:"
                    f"enable='between(t,{start:.3f},{end:.3f})'[{next_label}]"
                )
                text_label = next_label

            audio_labels = []
            for index, item in enumerate(prepared_audio):
                ffmpeg_inputs.extend([
                    '-ss', f"{item['source_start']:.3f}",
                    '-t', f"{item['duration']:.3f}",
                    '-i', str(item['source']),
                ])
                audio_label = f'audio{index}'
                delay_ms = max(0, int(round(item['timeline_start'] * 1000)))
                filter_parts.append(
                    f"[{input_index}:a]atrim=duration={item['duration']:.3f},"
                    f"asetpts=PTS-STARTPTS,adelay={delay_ms}:all=1[{audio_label}]"
                )
                audio_labels.append(audio_label)
                input_index += 1

            final_label = text_label
            filter_parts.append(f"[{final_label}]format=yuv420p[vout]")
            if audio_labels:
                joined = ''.join(f'[{label}]' for label in audio_labels)
                filter_parts.append(
                    f"{joined}amix=inputs={len(audio_labels)}:duration=longest:"
                    f"dropout_transition=0,atrim=duration={duration:.3f},asetpts=PTS-STARTPTS[aout]"
                )

            from services.gpu_accelerator import get_ffmpeg_video_encoder_args
            enc_args = get_ffmpeg_video_encoder_args(preset="veryfast", crf=22)
            cmd = [
                'ffmpeg', '-y', '-hide_banner', '-loglevel', 'warning', '-nostdin',
                *ffmpeg_inputs, '-filter_complex', ';'.join(filter_parts),
                '-map', '[vout]',
            ]
            if audio_labels:
                cmd.extend(['-map', '[aout]', '-c:a', 'aac', '-b:a', '192k'])
            else:
                cmd.extend(['-an'])
            cmd.extend([*enc_args, '-r', str(fps), '-t', f'{duration:.3f}', str(out_path)])
            subprocess.run(cmd, check=True, timeout=300)
            if not out_path.is_file() or out_path.stat().st_size < 4096:
                raise RuntimeError('FFmpeg completed without producing a usable editor export')
        finally:
            try:
                import shutil
                shutil.rmtree(render_tmp_dir, ignore_errors=True)
            except Exception:
                pass

        return jsonify({
            "success": True,
            "output_path": str(out_path),
            "url": f"/output/{out_filename}",
            "filename": out_filename,
        })

    except Exception as exc:
        print(f"   [editor-render] Error rendering timeline: {exc}")
        failed_metadata = {"selected_backend": "remotion", "status": "failed", "error": str(exc)}
        if edit_plan_path:
            failed_metadata["edit_plan_path"] = str(edit_plan_path)
            if isinstance(manifest, dict):
                try:
                    manifest["render_metadata"] = failed_metadata
                    edit_plan_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2, default=str), encoding='utf-8')
                except Exception:
                    pass
        return jsonify({"error": str(exc), "edit_plan_path": str(edit_plan_path) if edit_plan_path else None, "render_metadata": failed_metadata}), 500


